INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C1','kor',2,1,'u1',1,'잘 듣기(경청) — 말하는 사람을 바라보며 끼어들지 않고 끝까지 듣고, 고개를 끄덕이거나 끝난 뒤 박수로 들은 마음을 전하기',ARRAY['2국01-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C2','kor',2,1,'u1',1,'소개하는 글이란 — 나를 잘 모르는 사람에게 누구인지·좋아하는 것·잘하는 것처럼 읽을 사람이 궁금해할 내용을 담아 나를 알려 주는 글임을 알기',ARRAY['2국03-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C3','kor',2,1,'u1',3,'말차례의 뜻 — 대화에서 한 사람씩 차례대로 말하는 것이며, 한꺼번에 말하거나 끼어들면 알아듣기 어렵고 말하던 사람이 속상함을 알기',ARRAY['2국01-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C4','kor',2,1,'u1',3,'말차례를 지키며 대화하기 — 손을 들고 기다리기·끝까지 듣기·내 차례에 또박또박 말하기, 묻는 말에 알맞게 답하고 되물어 대화를 이어 가며 모두가 고르게 말하게 하기',ARRAY['2국01-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C5','kor',2,1,'u1',5,'글을 읽고 내용 파악하기 — 짧은 이야기에서 누가·무엇을·왜 했는지, 일이 일어난 차례를 글에서 찾아 말하기',ARRAY['2국01-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C6','kor',2,1,'u1',5,'인물의 마음을 짐작하고 생각 나누기 — 인물이 처한 일에서 마음과 그 까닭을 짐작하고, 「나라면?」 하고 떠올린 생각을 말차례를 지켜 나누며 다른 생각도 인정하기',ARRAY['2국01-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C7','kor',2,1,'u1',7,'소개할 내용 정리하기 — 이름·좋아하는 것·잘하는 것·꿈 같은 항목에서 읽을 사람이 궁금해할 내용을 고르고, 관계없는 내용과 개인 정보는 빼며 까닭을 더해 정리하기',ARRAY['2국03-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C8','kor',2,1,'u1',9,'나를 소개하는 글 쓰기 — 「저는 ○○○입니다.」로 시작해 한 문장에 한 가지 내용씩 문장으로 이어 쓰고(끝에 마침표), 다시 읽으며 관계없는 문장을 빼고 까닭을 더해 다듬기',ARRAY['2국03-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C9','kor',2,1,'u1',11,'주변 사람 소개하기 — 「제 ○○ ○○○를 소개합니다.」로 누구인지 밝히고 잘하는 것·좋은 점·함께한 일을 존중하는 마음으로 전하며, 흉이나 전화번호·주소 같은 개인 정보는 넣지 않기',ARRAY['2국03-02']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C10','kor',2,1,'u1',9,'발표하고 듣고 묻기 — 듣는 사람을 바라보며 알맞은 크기로 또박또박 발표하고, 들을 때는 끝까지 들은 뒤 손을 들어 내용과 관련 있는 것을 묻고 박수로 반응하기',ARRAY['2국01-04']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X01','kor',2,'u1',ARRAY['K2-1-u1-C1','K2-1-u1-C10']::text[],'귀로 소리만 들리면 잘 듣는 것이라고 여겨 딴 곳을 보거나 다른 일을 하며 듣는다','말하는 사람 쪽으로 몸과 눈을 돌리고, 들은 말을 한 가지 되말해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X02','kor',2,'u1',ARRAY['K2-1-u1-C1','K2-1-u1-C3','K2-1-u1-C4','K2-1-u1-C10']::text[],'생각이 떠오르면 친구 말이 끝나기 전에 끼어들어 말하거나 묻는다','말하고 싶으면 손을 들고, 친구 말이 끝났는지 확인한 뒤 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X03','kor',2,'u1',ARRAY['K2-1-u1-C3','K2-1-u1-C4']::text[],'말차례를 「먼저·크게 말하는 사람이 말하는 것」으로 여긴다','「지금 누구 차례지?」 하고 차례를 먼저 살피기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X04','kor',2,'u1',ARRAY['K2-1-u1-C4','K2-1-u1-C10']::text[],'상대가 묻는 말이나 앞 사람 말과 관계없는 엉뚱한 말을 해 대화가 이어지지 않는다','앞 사람 말의 중심 낱말을 넣어 대답하거나 되묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X05','kor',2,'u1',ARRAY['K2-1-u1-C3','K2-1-u1-C4']::text[],'차례를 고르게 나누지 않는다 — 한 사람이 혼자 길게 말하거나, 내 차례에도 말하지 않고 듣기만 한다','한 번 말하면 다음 사람에게 「너는 어때?」 하고 차례 건네기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X06','kor',2,'u1',ARRAY['K2-1-u1-C2','K2-1-u1-C7','K2-1-u1-C8']::text[],'소개하는 글에 나를 알려 주지 않는 내용(날씨·급식·어제 본 만화)을 넣는다','「이 문장이 나를 알려 주나?」 한 문장씩 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X07','kor',2,'u1',ARRAY['K2-1-u1-C2','K2-1-u1-C7','K2-1-u1-C8','K2-1-u1-C9']::text[],'누구를 소개하는지 밝히지 않고 시작해 읽는 사람이 누구의 이야기인지 알 수 없게 쓴다','첫 문장에 「저는 ○○○입니다.」·「제 ○○ ○○○를 소개합니다.」 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X08','kor',2,'u1',ARRAY['K2-1-u1-C2','K2-1-u1-C8']::text[],'낱말만 늘어놓거나 문장 끝을 맺지 않아 문장이 되지 않게 쓴다(축구. 줄넘기. / 마침표 없음)','「누가 무엇을 어찌합니다.」로 끝까지 말해 보고 끝에 마침표 찍기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X09','kor',2,'u1',ARRAY['K2-1-u1-C8']::text[],'한 문장에 여러 내용을 몰아 써서 읽기 어렵게 만든다','「그리고」가 나오면 거기서 문장을 나누어 한 문장에 한 가지만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X10','kor',2,'u1',ARRAY['K2-1-u1-C7','K2-1-u1-C8']::text[],'소개 항목(이름·좋아하는 것·잘하는 것·꿈)을 서로 헷갈려 엉뚱한 칸에 넣는다','「좋아하는 것」은 즐기는 것, 「잘하는 것」은 솜씨, 「꿈」은 되고 싶은 것 — 항목 이름을 소리 내어 읽고 넣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X11','kor',2,'u1',ARRAY['K2-1-u1-C5','K2-1-u1-C9']::text[],'글을 끝까지 살피지 않아 인물이나 한 일을 바꾸어 말하거나 글에 없는 일을 말한다','「누가? 무엇을?」을 글에서 찾아 손가락으로 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X12','kor',2,'u1',ARRAY['K2-1-u1-C6']::text[],'인물의 마음을 일어난 일과 반대로, 또는 까닭 없이 짐작한다','「이런 일이 생기면 나는 어떤 마음일까?」를 일어난 일과 이어 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X13','kor',2,'u1',ARRAY['K2-1-u1-C6','K2-1-u1-C10']::text[],'나와 다른 생각은 틀렸다고 여기거나 친구 생각을 깎아내린다','「그렇게 생각할 수도 있구나. 왜 그렇게 생각해?」 하고 되묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X14','kor',2,'u1',ARRAY['K2-1-u1-C7','K2-1-u1-C9']::text[],'소개에 흉(실수·단점)이나 전화번호·주소·비밀번호 같은 개인 정보를 넣는다','「이 사람이 들으면 기분 좋을까? 남이 알아도 괜찮을까?」 두 번 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X15','kor',2,'u1',ARRAY['K2-1-u1-C10']::text[],'발표할 때 듣는 사람을 보지 않고 종이만 보거나 작게·빠르게 말해도 된다고 여긴다','한 문장 읽고 고개 들어 친구들 보기 — 맨 뒤 친구에게 들리게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X16','kor',2,'u1',ARRAY['K2-1-u1-C1','K2-1-u1-C2','K2-1-u1-C4','K2-1-u1-C8']::text[],'묻는 말을 거꾸로 읽는다 — 어긴 것↔지킨 것, 어울리지 않는 것↔어울리는 것, 빼야 할 것↔넣을 것','물음의 「않는·못한·빼야」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_basic#1','kor',2,1,'u1','L01','g2_1_kor_u1_L01_basic','lesson_basic','K2-1-u1-C1',1,'mc','auto','친구가 발표할 때 바른 듣기 태도는 어느 것인가요?',ARRAY['K2-1-u1-X02','K2-1-u1-X01']::text[],true,'{"seq":1,"concept":"K2-1-u1-C1","difficulty":1,"kind":"mc","stem":"친구가 발표할 때 바른 듣기 태도는 어느 것인가요?","options":[{"t":"말하는 친구를 바라보며 끝까지 들어요","correct":true},{"t":"중간에 끼어들어 내 생각을 말해요","mis":"K2-1-u1-X02"},{"t":"옆 친구와 이야기하며 들어요","mis":"K2-1-u1-X01"}],"explanation":["잘 듣는 사람은 말하는 사람을 바라보며 끝까지 들어요.","끼어들거나 떠들면 말하는 친구의 말이 끊겨요.","잘 들어 주면 말하는 친구도 기분이 좋아져요."],"variant_rule":{"alt":[{"stem":"선생님께서 이야기하실 때 바른 듣기 태도는 어느 것인가요?","options":[{"t":"선생님을 바라보며 끝까지 들어요","correct":true},{"t":"그림을 그리며 귀로만 들어요","mis":"K2-1-u1-X01"},{"t":"궁금한 것이 생기면 바로 끼어들어요","mis":"K2-1-u1-X02"}],"explanation":["말하는 사람을 바라보며 끝까지 들어요.","다른 일을 하거나 끼어들면 잘 들을 수 없어요.","궁금한 것은 이야기가 끝난 뒤 손을 들고 물어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_basic#2','kor',2,1,'u1','L01','g2_1_kor_u1_L01_basic','lesson_basic','K2-1-u1-C1',1,'sa','auto','말하는 사람을 바라보며 끝까지 귀 기울여 잘 듣는 것을 두 글자로 무엇이라고 하나요?','{}'::text[],true,'{"seq":2,"concept":"K2-1-u1-C1","difficulty":1,"kind":"sa","stem":"말하는 사람을 바라보며 끝까지 귀 기울여 잘 듣는 것을 두 글자로 무엇이라고 하나요?","answer":["경청","경청하기"],"explanation":["귀 기울여 잘 듣는 것을 「경청」이라고 해요.","바라보며, 끼어들지 않고, 끝까지 들어요.","경청하면 말하는 사람의 마음까지 잘 알 수 있어요."],"variant_rule":{"alt":[{"stem":"친구 말에 귀 기울여 끝까지 잘 듣는 것을 무엇이라고 하나요?","answer":["경청","경청하기"],"explanation":["끝까지 귀 기울여 잘 듣는 것은 「경청」이에요.","말하는 친구를 바라보며 들어요.","들은 뒤에 반응을 해 주면 더 좋아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_basic#3','kor',2,1,'u1','L01','g2_1_kor_u1_L01_basic','lesson_basic','K2-1-u1-C1',1,'ox','auto','친구가 말할 때 딴 곳을 보아도 귀로 소리가 들리면 잘 듣는 것이에요.',ARRAY['K2-1-u1-X01']::text[],true,'{"seq":3,"concept":"K2-1-u1-C1","difficulty":1,"kind":"ox","stem":"친구가 말할 때 딴 곳을 보아도 귀로 소리가 들리면 잘 듣는 것이에요.","answer":"X","reason_options":[{"t":"말하는 사람을 바라보며 마음을 기울여 들어야 잘 듣는 것이니까","correct":true},{"t":"귀로 소리만 들리면 되니까","mis":"K2-1-u1-X01"}],"mis":"K2-1-u1-X01","explanation":["잘 듣기는 귀만이 아니라 눈과 마음으로 하는 거예요.","딴 곳을 보면 말하는 친구는 내 말을 안 듣는다고 느껴요.","말하는 사람을 바라보며 들어요."],"variant_rule":{"alt":[{"stem":"친구 말이 끝날 때까지 기다렸다가 내 생각을 말하는 것은 잘 듣는 태도예요.","answer":"O","reason_options":[{"t":"끼어들지 않고 끝까지 들었으니까","correct":true},{"t":"생각나면 바로 말해야 잊지 않으니까","mis":"K2-1-u1-X02"}],"explanation":["끝까지 기다렸다가 말하는 것이 잘 듣는 태도예요.","생각나는 대로 끼어들면 친구 말이 끊겨요.","잊을까 걱정되면 짧게 적어 두어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_basic#4','kor',2,1,'u1','L01','g2_1_kor_u1_L01_basic','lesson_basic','K2-1-u1-C2',1,'mc','auto','나를 소개하는 글에 넣으면 좋은 내용은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],true,'{"seq":4,"concept":"K2-1-u1-C2","difficulty":1,"kind":"mc","stem":"나를 소개하는 글에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"내가 좋아하는 것","correct":true},{"t":"어제 본 만화 줄거리","mis":"K2-1-u1-X06"},{"t":"내일 날씨","mis":"K2-1-u1-X06"}],"explanation":["소개하는 글은 나를 알려 주는 글이에요.","좋아하는 것은 나를 잘 알려 줘요.","만화 줄거리나 날씨는 나를 알려 주지 않아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나를 소개하는 글에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"내가 잘하는 것","correct":true},{"t":"오늘 급식 반찬","mis":"K2-1-u1-X06"},{"t":"버스가 오는 시간","mis":"K2-1-u1-X06"}],"explanation":["소개하는 글에는 나를 알려 주는 내용을 담아요.","잘하는 것은 나를 잘 보여 줘요.","급식 반찬이나 버스 시간은 나와 관계가 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_basic#5','kor',2,1,'u1','L01','g2_1_kor_u1_L01_basic','lesson_basic','K2-1-u1-C2',2,'mc','auto','소개하는 글은 어떤 글인가요?',ARRAY['K2-1-u1-X06']::text[],true,'{"seq":5,"concept":"K2-1-u1-C2","difficulty":2,"kind":"mc","stem":"소개하는 글은 어떤 글인가요?","options":[{"t":"나를 잘 모르는 사람에게 나를 알려 주는 글","correct":true},{"t":"있었던 일을 날짜와 함께 적는 글","mis":"K2-1-u1-X06"},{"t":"물건을 쓰는 방법을 알려 주는 글","mis":"K2-1-u1-X06"}],"explanation":["소개하는 글은 나를 알려 주는 글이에요.","이름, 좋아하는 것, 잘하는 것 같은 내용을 담아요.","읽는 사람이 나를 더 잘 알게 돼요."],"variant_rule":{"alt":[{"stem":"소개하는 글을 읽은 사람이 알 수 있는 것은 무엇인가요?","options":[{"t":"글쓴이가 누구이고 무엇을 좋아하는지","correct":true},{"t":"글쓴이가 어제 무엇을 먹었는지","mis":"K2-1-u1-X06"},{"t":"내일 날씨가 어떨지","mis":"K2-1-u1-X06"}],"explanation":["소개하는 글은 글쓴이를 알려 줘요.","누구인지, 무엇을 좋아하는지 알 수 있어요.","어제 먹은 것이나 날씨는 소개하는 글의 내용이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_basic#6','kor',2,1,'u1','L01','g2_1_kor_u1_L01_basic','lesson_basic','K2-1-u1-C2',2,'mc','auto','소개하는 글을 읽고 답해 보세요. 도윤이가 좋아하는 것은 무엇인가요?',ARRAY['K2-1-u1-X10','K2-1-u1-X11']::text[],true,'{"seq":6,"concept":"K2-1-u1-C2","difficulty":2,"kind":"mc","stem":"소개하는 글을 읽고 답해 보세요. 도윤이가 좋아하는 것은 무엇인가요?","options":[{"t":"종이비행기 접기","correct":true},{"t":"줄넘기","mis":"K2-1-u1-X10"},{"t":"달리기","mis":"K2-1-u1-X11"}],"explanation":["「저는 종이비행기 접기를 좋아합니다.」라고 썼어요.","줄넘기는 도윤이가 잘하는 것이에요.","좋아하는 것과 잘하는 것을 가려 읽어요."],"asset":{"type":"passage","lines":["저는 한도윤입니다.","저는 종이비행기 접기를 좋아합니다.","제가 잘하는 것은 줄넘기입니다."],"title":"나를 소개합니다"},"variant_rule":{"alt":[{"stem":"소개하는 글을 읽고 답해 보세요. 다은이가 잘하는 것은 무엇인가요?","options":[{"t":"피아노 치기","correct":true},{"t":"고양이","mis":"K2-1-u1-X10"},{"t":"노래하기","mis":"K2-1-u1-X11"}],"explanation":["「제가 잘하는 것은 피아노 치기입니다.」라고 썼어요.","고양이는 다은이가 좋아하는 것이에요.","글에 나온 말을 찾아 답해요."],"asset":{"type":"passage","lines":["저는 윤다은입니다.","저는 고양이를 좋아합니다.","제가 잘하는 것은 피아노 치기입니다."],"title":"나를 소개합니다"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_basic#7','kor',2,1,'u1','L01','g2_1_kor_u1_L01_basic','lesson_basic','K2-1-u1-C2',2,'mc','auto','나를 소개할 때 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u1-X08']::text[],true,'{"seq":7,"concept":"K2-1-u1-C2","difficulty":2,"kind":"mc","stem":"나를 소개할 때 알맞은 말은 어느 것인가요?","options":[{"t":"저는 축구를 좋아합니다.","correct":true},{"t":"축구. 줄넘기.","mis":"K2-1-u1-X08"},{"t":"축구 좋아 나","mis":"K2-1-u1-X08"}],"explanation":["「저는 축구를 좋아합니다.」는 무엇을 좋아하는지 문장으로 전해요.","낱말만 늘어놓으면 무슨 뜻인지 알기 어려워요.","「저는 ~을 좋아합니다.」로 또박또박 말해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나를 소개할 때 알맞은 말은 어느 것인가요?","options":[{"t":"저는 그림 그리기를 잘합니다.","correct":true},{"t":"그림. 잘함.","mis":"K2-1-u1-X08"},{"t":"그림 나 잘해","mis":"K2-1-u1-X08"}],"explanation":["「저는 그림 그리기를 잘합니다.」는 문장으로 또렷하게 전해요.","낱말만 늘어놓으면 뜻이 흐려요.","문장으로 끝까지 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_basic#8','kor',2,1,'u1','L01','g2_1_kor_u1_L01_basic','lesson_basic','K2-1-u1-C1',2,'match','auto','듣는 사람의 모습과 알맞은 설명을 이어 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u1-C1","difficulty":2,"kind":"match","stem":"듣는 사람의 모습과 알맞은 설명을 이어 보세요.","pairs":[{"l":"친구를 바라보며 들어요","r":"잘 듣는 모습"},{"l":"친구 말을 자르고 말해요","r":"끼어드는 모습"},{"l":"옆 친구와 떠들어요","r":"듣지 않는 모습"}],"mis":"K2-1-u1-X02","explanation":["바라보며 끝까지 듣는 것이 잘 듣는 모습이에요.","말을 자르면 끼어드는 것이고, 떠들면 듣지 않는 거예요.","나는 어떤 모습인지 떠올려 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 듣는 사람의 모습과 알맞은 설명을 이어 보세요.","pairs":[{"l":"고개를 끄덕이며 들어요","r":"잘 듣는 모습"},{"l":"말하는 중에 「내 말 좀!」 해요","r":"끼어드는 모습"},{"l":"엎드려 딴생각을 해요","r":"듣지 않는 모습"}],"explanation":["고개를 끄덕이면 잘 듣고 있다는 뜻이 전해져요.","말하는 중에 끼어들거나 딴생각을 하면 잘 듣지 못해요.","바라보고, 끄덕이고, 끝까지 들어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_basic#9','kor',2,1,'u1','L01','g2_1_kor_u1_L01_basic','lesson_basic','K2-1-u1-C2',2,'ox','auto','「어제는 비가 많이 왔습니다.」는 나를 소개하는 글에 어울리는 문장이에요.',ARRAY['K2-1-u1-X06']::text[],true,'{"seq":9,"concept":"K2-1-u1-C2","difficulty":2,"kind":"ox","stem":"「어제는 비가 많이 왔습니다.」는 나를 소개하는 글에 어울리는 문장이에요.","answer":"X","reason_options":[{"t":"나를 알려 주는 내용이 아니니까","correct":true},{"t":"글에 문장이 많을수록 좋으니까","mis":"K2-1-u1-X06"}],"mis":"K2-1-u1-X06","explanation":["날씨는 나를 알려 주지 않아요.","소개하는 글에는 나에 대한 내용만 담아요.","문장이 많다고 좋은 소개가 되는 것이 아니에요."],"variant_rule":{"alt":[{"stem":"「제 꿈은 소방관입니다.」는 나를 소개하는 글에 어울리는 문장이에요.","answer":"O","reason_options":[{"t":"꿈은 나를 알려 주는 내용이니까","correct":true},{"t":"꿈은 아직 이루지 않은 일이라 소개할 수 없으니까","mis":"K2-1-u1-X06"}],"explanation":["꿈은 나를 잘 보여 주는 내용이에요.","아직 이루지 않았어도 소개할 수 있어요.","이름, 좋아하는 것, 잘하는 것, 꿈을 담아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_basic#10','kor',2,1,'u1','L01','g2_1_kor_u1_L01_basic','lesson_basic','K2-1-u1-C1',3,'error','auto','친구들이 발표를 들었어요. 잘 듣지 못한 친구는 누구인가요?',ARRAY['K2-1-u1-X02','K2-1-u1-X16']::text[],true,'{"seq":10,"concept":"K2-1-u1-C1","difficulty":3,"kind":"error","stem":"친구들이 발표를 들었어요. 잘 듣지 못한 친구는 누구인가요?","options":[{"t":"로아 — 발표 중에 「나도 그거 해 봤어!」 하고 끼어들었어요","correct":true,"mis_target":"K2-1-u1-X02"},{"t":"시우 — 발표하는 친구를 바라보며 들었어요","mis":"K2-1-u1-X16"},{"t":"예린 — 발표가 끝난 뒤 손을 들고 물었어요","mis":"K2-1-u1-X16"}],"explanation":["로아는 발표 중에 끼어들었어요.","하고 싶은 말이 있어도 발표가 끝날 때까지 기다려요.","시우와 예린이는 잘 들었어요."],"variant_rule":{"alt":[{"stem":"친구들이 이야기를 들었어요. 잘 듣지 못한 친구는 누구인가요?","options":[{"t":"준우 — 친구가 말하는 동안 창밖만 보았어요","correct":true,"mis_target":"K2-1-u1-X01"},{"t":"하린 — 고개를 끄덕이며 들었어요","mis":"K2-1-u1-X16"},{"t":"도윤 — 끝까지 듣고 박수를 쳤어요","mis":"K2-1-u1-X16"}],"explanation":["준우는 말하는 친구를 보지 않았어요.","바라보며 들어야 잘 듣는 거예요.","하린이와 도윤이는 잘 들었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#1','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C1',2,'mc','auto','친구가 내 말을 끝까지 잘 들어 주면 나는 어떤 마음이 들까요?',ARRAY['K2-1-u1-X12']::text[],false,'{"seq":1,"concept":"K2-1-u1-C1","difficulty":2,"kind":"mc","stem":"친구가 내 말을 끝까지 잘 들어 주면 나는 어떤 마음이 들까요?","options":[{"t":"내 말을 소중히 여겨 주어 기분이 좋아요","correct":true},{"t":"아무도 안 듣는 것 같아 속상해요","mis":"K2-1-u1-X12"},{"t":"빨리 말을 끝내고 싶어요","mis":"K2-1-u1-X12"}],"explanation":["잘 들어 주면 말하는 사람은 존중받는다고 느껴요.","그래서 기분이 좋아지고 더 말하고 싶어져요.","나도 친구 말을 잘 들어 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#2','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C2',2,'mc','auto','처음 만난 친구에게 나를 소개하는 글을 쓰려고 해요. 가장 먼저 쓸 내용은 무엇인가요?',ARRAY['K2-1-u1-X06','K2-1-u1-X07']::text[],false,'{"seq":2,"concept":"K2-1-u1-C2","difficulty":2,"kind":"mc","stem":"처음 만난 친구에게 나를 소개하는 글을 쓰려고 해요. 가장 먼저 쓸 내용은 무엇인가요?","options":[{"t":"내 이름","correct":true},{"t":"어제 한 일","mis":"K2-1-u1-X06"},{"t":"친구의 이름","mis":"K2-1-u1-X07"}],"explanation":["소개하는 글은 누구인지부터 알려요.","그래서 첫 문장에 내 이름을 써요.","어제 한 일이나 친구 이름으로 시작하면 누구 소개인지 알기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#3','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C1',3,'mc','auto','대화를 읽고 답해 보세요. 준우가 잘 듣지 못했다고 할 수 있는 까닭은 무엇인가요?',ARRAY['K2-1-u1-X16','K2-1-u1-X01']::text[],false,'{"seq":3,"concept":"K2-1-u1-C1","difficulty":3,"kind":"mc","stem":"대화를 읽고 답해 보세요. 준우가 잘 듣지 못했다고 할 수 있는 까닭은 무엇인가요?","options":[{"t":"하린이를 보지 않고 하린이 말과 관계없는 말을 했어요","correct":true},{"t":"하린이가 너무 짧게 말해서예요","mis":"K2-1-u1-X16"},{"t":"「응.」 하고 대답했으니 잘 들은 거예요","mis":"K2-1-u1-X01"}],"explanation":["준우는 먼 곳을 보며 엉뚱한 말을 했어요.","대답을 했다고 잘 들은 것은 아니에요.","잘 들으면 친구 말과 이어지는 말을 할 수 있어요."],"asset":{"type":"speech","turns":[{"who":"하린","text":"나 주말에 바다에 갔어."},{"who":"준우","text":"(먼 곳을 보며) 응…"},{"who":"하린","text":"파도가 정말 컸어!"},{"who":"준우","text":"아, 나 숙제 안 했다!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#4','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C2',3,'ox','auto','소개하는 글에는 읽을 사람이 궁금해할 내용을 골라 써요.',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":4,"concept":"K2-1-u1-C2","difficulty":3,"kind":"ox","stem":"소개하는 글에는 읽을 사람이 궁금해할 내용을 골라 써요.","answer":"O","reason_options":[{"t":"나를 잘 알려 주는 내용이어야 하니까","correct":true},{"t":"생각나는 것은 모두 써야 하니까","mis":"K2-1-u1-X06"}],"mis":"K2-1-u1-X06","explanation":["읽을 사람이 궁금해할 내용을 골라요.","생각나는 대로 다 쓰면 나와 관계없는 내용까지 섞여요.","좋아하는 것, 잘하는 것, 꿈처럼 나를 알려 주는 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#5','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C2',3,'mc','auto','소개하는 글을 읽고 답해 보세요. 이 글에 어울리지 않는 문장은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],false,'{"seq":5,"concept":"K2-1-u1-C2","difficulty":3,"kind":"mc","stem":"소개하는 글을 읽고 답해 보세요. 이 글에 어울리지 않는 문장은 어느 것인가요?","options":[{"t":"오늘 아침에 버스가 늦게 왔습니다.","correct":true},{"t":"저는 곤충 관찰을 좋아합니다.","mis":"K2-1-u1-X16"},{"t":"제가 잘하는 것은 줄넘기입니다.","mis":"K2-1-u1-X16"}],"explanation":["버스가 늦게 온 일은 소율이를 알려 주지 않아요.","좋아하는 것과 잘하는 것은 소율이를 알려 주는 문장이에요.","소개하는 글에는 나를 알려 주는 문장만 넣어요."],"asset":{"type":"passage","lines":["저는 강소율입니다.","저는 곤충 관찰을 좋아합니다.","오늘 아침에 버스가 늦게 왔습니다.","제가 잘하는 것은 줄넘기입니다."],"title":"나를 소개합니다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#6','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C2',3,'error','auto','친구들이 소개하는 글에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X07','K2-1-u1-X16']::text[],false,'{"seq":6,"concept":"K2-1-u1-C2","difficulty":3,"kind":"error","stem":"친구들이 소개하는 글에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 소개하는 글은 이름 없이 좋아하는 것만 써도 돼요","correct":true,"mis_target":"K2-1-u1-X07"},{"t":"다은 — 누구의 글인지 알 수 있게 이름을 써요","mis":"K2-1-u1-X16"},{"t":"민호 — 좋아하는 것과 잘하는 것을 담아요","mis":"K2-1-u1-X16"}],"explanation":["이름이 없으면 누구를 소개하는지 알 수 없어요.","그래서 「저는 ○○○입니다.」로 시작해요.","다은이와 민호는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#7','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C1',3,'mc','auto','발표하는 친구의 목소리가 작아 잘 들리지 않아요. 어떻게 하면 좋을까요?',ARRAY['K2-1-u1-X02','K2-1-u1-X01']::text[],false,'{"seq":7,"concept":"K2-1-u1-C1","difficulty":3,"kind":"mc","stem":"발표하는 친구의 목소리가 작아 잘 들리지 않아요. 어떻게 하면 좋을까요?","options":[{"t":"발표가 끝난 뒤 손을 들고 다시 말해 달라고 해요","correct":true},{"t":"발표 중에 「안 들려!」 하고 크게 외쳐요","mis":"K2-1-u1-X02"},{"t":"안 들리니까 그냥 다른 일을 해요","mis":"K2-1-u1-X01"}],"explanation":["발표 중에 외치면 친구 말이 끊기고 친구가 당황해요.","다른 일을 하면 더 들을 수 없어요.","끝난 뒤 정중하게 다시 말해 달라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#8','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C2',4,'mc','auto','두 친구가 자기를 소개했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#9','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C2',4,'essay','teacher','처음 만난 친구에게 나를 소개하는 문장을 세 문장 써 보세요. 첫 문장은 내 이름으로 시작해요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u1-C2","difficulty":4,"kind":"essay","stem":"처음 만난 친구에게 나를 소개하는 문장을 세 문장 써 보세요. 첫 문장은 내 이름으로 시작해요.","answer_guide":{"answer":"예: 저는 김하늘입니다. / 저는 공룡 책 읽기를 좋아합니다. / 제가 잘하는 것은 달리기입니다.","scoring_points":["「저는 ○○○입니다.」로 시작했는가","나를 알려 주는 내용(좋아하는 것·잘하는 것·꿈)을 담았는가","한 문장에 한 가지씩 문장으로 썼는가"]},"explanation":["이름으로 시작하기.","나를 알려 주는 내용.","한 문장에 한 가지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#10','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C1',4,'essay','teacher','친구의 말을 잘 들어야 하는 까닭을 쓰고, 내가 지킬 듣기 약속을 한 가지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u1-C1","difficulty":4,"kind":"essay","stem":"친구의 말을 잘 들어야 하는 까닭을 쓰고, 내가 지킬 듣기 약속을 한 가지 써 보세요.","answer_guide":{"answer":"예: 잘 들어야 친구의 생각과 마음을 알 수 있기 때문입니다. 저는 친구가 말할 때 끝까지 바라보며 듣겠습니다.","scoring_points":["잘 들어야 하는 까닭을 썼는가","지킬 수 있는 듣기 약속을 썼는가","바라보기·끝까지·끼어들지 않기 가운데 하나가 드러났는가"]},"explanation":["까닭.","약속.","바라보며 끝까지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_basic#1','kor',2,1,'u1','L03','g2_1_kor_u1_L03_basic','lesson_basic','K2-1-u1-C3',1,'mc','auto','말차례란 무엇인가요?',ARRAY['K2-1-u1-X03','K2-1-u1-X05']::text[],true,'{"seq":1,"concept":"K2-1-u1-C3","difficulty":1,"kind":"mc","stem":"말차례란 무엇인가요?","options":[{"t":"대화할 때 한 사람씩 차례대로 말하는 것","correct":true},{"t":"먼저 큰 소리로 말하는 사람이 말하는 것","mis":"K2-1-u1-X03"},{"t":"한 사람만 계속 말하는 것","mis":"K2-1-u1-X05"}],"explanation":["말차례는 한 사람씩 차례대로 말하는 거예요.","목소리가 크거나 먼저 말한다고 차례가 되는 것이 아니에요.","모두가 돌아가며 말해요."],"variant_rule":{"alt":[{"stem":"여러 친구가 한꺼번에 말하면 어떻게 될까요?","options":[{"t":"무슨 말인지 알아듣기 어려워요","correct":true},{"t":"말이 더 잘 들려요","mis":"K2-1-u1-X03"},{"t":"이야기가 더 빨리 끝나서 좋아요","mis":"K2-1-u1-X03"}],"explanation":["한꺼번에 말하면 말소리가 섞여요.","그래서 서로의 말을 알아듣기 어려워요.","그래서 말차례가 필요해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_basic#2','kor',2,1,'u1','L03','g2_1_kor_u1_L03_basic','lesson_basic','K2-1-u1-C3',1,'sa','auto','대화할 때 한 사람씩 차례대로 말하는 것을 무엇이라고 하나요?','{}'::text[],true,'{"seq":2,"concept":"K2-1-u1-C3","difficulty":1,"kind":"sa","stem":"대화할 때 한 사람씩 차례대로 말하는 것을 무엇이라고 하나요?","answer":["말차례","말 차례"],"explanation":["한 사람씩 차례대로 말하는 것을 「말차례」라고 해요.","내 차례가 올 때까지 기다려요.","다른 사람이 말할 때는 잘 들어요."],"variant_rule":{"alt":[{"stem":"내 차례가 올 때까지 기다렸다가 말하는 것은 무엇을 지키는 것인가요?","answer":["말차례","말 차례","말차례 지키기"],"explanation":["차례를 기다렸다 말하는 것은 「말차례」를 지키는 거예요.","끼어들지 않고 기다려요.","내 차례가 되면 또박또박 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_basic#3','kor',2,1,'u1','L03','g2_1_kor_u1_L03_basic','lesson_basic','K2-1-u1-C4',1,'mc','auto','말차례를 지키지 못한 행동은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],true,'{"seq":3,"concept":"K2-1-u1-C4","difficulty":1,"kind":"mc","stem":"말차례를 지키지 못한 행동은 어느 것인가요?","options":[{"t":"친구가 말하는데 끼어들기","correct":true},{"t":"손 들고 기다리기","mis":"K2-1-u1-X16"},{"t":"끝까지 잘 듣기","mis":"K2-1-u1-X16"}],"explanation":["끼어드는 것은 말차례를 어긴 거예요.","손 들고 기다리기, 끝까지 듣기는 말차례를 지킨 행동이에요.","묻는 말을 끝까지 읽어요 — 「지키지 못한」 행동을 찾아요."],"variant_rule":{"alt":[{"stem":"말차례를 잘 지킨 행동은 어느 것인가요?","options":[{"t":"친구 말이 끝난 뒤 내 차례에 말하기","correct":true},{"t":"생각나면 바로 끼어들기","mis":"K2-1-u1-X02"},{"t":"친구보다 먼저 크게 말하기","mis":"K2-1-u1-X03"}],"explanation":["친구 말이 끝나면 내 차례에 말해요.","끼어들거나 먼저 크게 말하면 말차례를 어긴 거예요.","차례를 기다리면 모두의 말이 잘 들려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_basic#4','kor',2,1,'u1','L03','g2_1_kor_u1_L03_basic','lesson_basic','K2-1-u1-C4',1,'ox','auto','말하고 싶을 때는 손을 들고 기다려요.',ARRAY['K2-1-u1-X02']::text[],true,'{"seq":4,"concept":"K2-1-u1-C4","difficulty":1,"kind":"ox","stem":"말하고 싶을 때는 손을 들고 기다려요.","answer":"O","reason_options":[{"t":"차례가 와서 말해야 모두의 말이 잘 들리니까","correct":true},{"t":"손을 들면 바로 말해도 되니까","mis":"K2-1-u1-X02"}],"mis":"K2-1-u1-X02","explanation":["손을 드는 것은 「말하고 싶어요.」라는 신호예요.","손을 들고 차례가 올 때까지 기다려요.","차례가 되면 또박또박 말해요."],"variant_rule":{"alt":[{"stem":"생각이 떠오르면 친구 말을 끊고 바로 말해도 돼요.","answer":"X","reason_options":[{"t":"친구 말을 끝까지 듣고 내 차례에 말해야 하니까","correct":true},{"t":"잊어버리기 전에 말하는 게 더 중요하니까","mis":"K2-1-u1-X02"}],"explanation":["친구 말을 끊으면 말차례를 어기는 거예요.","친구 말이 끝날 때까지 기다려요.","잊을까 걱정되면 짧게 적어 두어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_basic#5','kor',2,1,'u1','L03','g2_1_kor_u1_L03_basic','lesson_basic','K2-1-u1-C3',2,'mc','auto','대화를 읽고 답해 보세요. 두 친구의 대화에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u1-X05','K2-1-u1-X11']::text[],true,'{"seq":5,"concept":"K2-1-u1-C3","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 두 친구의 대화에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"한 사람씩 차례로 말해 이야기가 잘 이어져요","correct":true},{"t":"서아만 계속 말했어요","mis":"K2-1-u1-X05"},{"t":"두 친구가 동시에 말했어요","mis":"K2-1-u1-X11"}],"explanation":["서아가 묻고, 지우가 답하고, 다시 서아가 물었어요.","한 사람씩 차례로 말했어요.","그래서 이야기가 차근차근 이어졌어요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"너는 어떤 동물을 키우고 싶어?"},{"who":"지우","text":"나는 강아지를 키우고 싶어."},{"who":"서아","text":"왜 강아지야?"},{"who":"지우","text":"같이 산책하고 싶어서."}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 답해 보세요. 이 대화에서 아쉬운 점은 무엇인가요?","options":[{"t":"시우가 하람이 말을 끝까지 듣지 않고 끼어들었어요","correct":true},{"t":"하람이가 너무 천천히 말했어요","mis":"K2-1-u1-X16"},{"t":"아쉬운 점이 없어요","mis":"K2-1-u1-X02"}],"explanation":["하람이가 말하는 중에 시우가 끼어들었어요.","하람이는 하던 말을 끝내지 못했어요.","친구 말이 끝난 뒤 내 차례에 말해요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"어제 공원에 가서…"},{"who":"시우","text":"나도! 나도 공원 갔어!"},{"who":"하람","text":"내 말 좀 끝까지…"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_basic#6','kor',2,1,'u1','L03','g2_1_kor_u1_L03_basic','lesson_basic','K2-1-u1-C4',2,'mc','auto','짝이 「좋아하는 음식이 뭐야?」 하고 물었어요. 말차례를 지켜 알맞게 대답한 것은 어느 것인가요?',ARRAY['K2-1-u1-X04']::text[],true,'{"seq":6,"concept":"K2-1-u1-C4","difficulty":2,"kind":"mc","stem":"짝이 「좋아하는 음식이 뭐야?」 하고 물었어요. 말차례를 지켜 알맞게 대답한 것은 어느 것인가요?","options":[{"t":"「나는 떡볶이를 좋아해. 너는?」","correct":true},{"t":"「나 어제 축구했어!」","mis":"K2-1-u1-X04"},{"t":"「몰라. 그런데 오늘 비 온대.」","mis":"K2-1-u1-X04"}],"explanation":["묻는 말에 맞게 대답했어요.","그리고 「너는?」 하고 짝에게 차례를 건넸어요.","묻는 말과 관계없는 말을 하면 대화가 이어지지 않아요."],"variant_rule":{"alt":[{"stem":"짝이 「주말에 뭐 했어?」 하고 물었어요. 말차례를 지켜 알맞게 대답한 것은 어느 것인가요?","options":[{"t":"「할머니 댁에 갔어. 너는 뭐 했어?」","correct":true},{"t":"「나 연필 새로 샀다!」","mis":"K2-1-u1-X04"},{"t":"「응.」","mis":"K2-1-u1-X05"}],"explanation":["묻는 말에 맞게 대답하고 짝에게 되물었어요.","관계없는 말이나 「응.」만 하면 대화가 끊겨요.","대답하고 차례를 건네요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_basic#7','kor',2,1,'u1','L03','g2_1_kor_u1_L03_basic','lesson_basic','K2-1-u1-C4',2,'match','auto','말차례를 지키는 방법을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"K2-1-u1-C4","difficulty":2,"kind":"match","stem":"말차례를 지키는 방법을 알맞게 이어 보세요.","pairs":[{"l":"말하고 싶을 때","r":"손을 들고 기다려요"},{"l":"친구가 말할 때","r":"끝까지 들어요"},{"l":"내 차례가 되면","r":"또박또박 말해요"}],"mis":"K2-1-u1-X02","explanation":["말하고 싶으면 손을 들고 기다려요.","친구 말은 끝까지 들어요.","내 차례가 되면 또박또박 말해요."],"variant_rule":{"alt":[{"stem":"대화할 때 할 일을 알맞게 이어 보세요.","pairs":[{"l":"짝이 물어보면","r":"묻는 말에 맞게 대답해요"},{"l":"대답한 뒤에는","r":"짝에게도 물어봐요"},{"l":"친구 말이 안 끝났으면","r":"기다려요"}],"explanation":["묻는 말에 맞게 대답해요.","대답한 뒤에는 짝에게 되물어 차례를 건네요.","친구 말이 끝날 때까지 기다려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_basic#8','kor',2,1,'u1','L03','g2_1_kor_u1_L03_basic','lesson_basic','K2-1-u1-C3',2,'mc','auto','친구가 말하는데 끼어들면 말하던 친구는 어떤 마음이 들까요?',ARRAY['K2-1-u1-X03']::text[],true,'{"seq":8,"concept":"K2-1-u1-C3","difficulty":2,"kind":"mc","stem":"친구가 말하는데 끼어들면 말하던 친구는 어떤 마음이 들까요?","options":[{"t":"속상하고 더 말하기 싫어져요","correct":true},{"t":"기분이 좋아져요","mis":"K2-1-u1-X03"},{"t":"아무렇지 않아요","mis":"K2-1-u1-X03"}],"explanation":["말이 끊기면 하고 싶은 말을 다 못 해요.","그래서 속상하고 말할 기운이 없어져요.","친구 말이 끝날 때까지 기다려요."],"variant_rule":{"alt":[{"stem":"말차례를 지켜 대화하면 어떤 점이 좋을까요?","options":[{"t":"서로의 말이 잘 들리고 마음도 잘 통해요","correct":true},{"t":"목소리가 큰 사람만 말할 수 있어요","mis":"K2-1-u1-X03"},{"t":"대화가 금방 끝나요","mis":"K2-1-u1-X03"}],"explanation":["차례대로 말하면 말소리가 섞이지 않아요.","서로의 말을 잘 듣게 되어 마음도 잘 통해요.","모두가 돌아가며 말할 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_basic#9','kor',2,1,'u1','L03','g2_1_kor_u1_L03_basic','lesson_basic','K2-1-u1-C3',2,'ox','auto','말차례를 지키면 한 사람이 혼자 오래 말해도 괜찮아요.',ARRAY['K2-1-u1-X05']::text[],true,'{"seq":9,"concept":"K2-1-u1-C3","difficulty":2,"kind":"ox","stem":"말차례를 지키면 한 사람이 혼자 오래 말해도 괜찮아요.","answer":"X","reason_options":[{"t":"모두가 돌아가며 말할 수 있게 해야 하니까","correct":true},{"t":"먼저 말을 시작한 사람이 끝까지 말해야 하니까","mis":"K2-1-u1-X05"}],"mis":"K2-1-u1-X05","explanation":["말차례는 모두가 돌아가며 말하는 거예요.","한 사람이 오래 말하면 다른 친구는 말할 차례가 없어요.","내 말을 마치면 다음 친구에게 차례를 건네요."],"variant_rule":{"alt":[{"stem":"모둠에서 이야기할 때는 친구들도 말할 수 있게 돌아가며 말해요.","answer":"O","reason_options":[{"t":"말차례는 모두가 차례로 말하는 것이니까","correct":true},{"t":"말을 잘하는 친구만 말하면 되니까","mis":"K2-1-u1-X05"}],"explanation":["모두가 돌아가며 말해요.","말을 잘하는 친구만 말하면 다른 친구의 생각을 들을 수 없어요.","「너는 어때?」 하고 차례를 건네요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_basic#10','kor',2,1,'u1','L03','g2_1_kor_u1_L03_basic','lesson_basic','K2-1-u1-C4',3,'error','auto','모둠 친구들이 말차례에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X03','K2-1-u1-X16']::text[],true,'{"seq":10,"concept":"K2-1-u1-C4","difficulty":3,"kind":"error","stem":"모둠 친구들이 말차례에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준우 — 목소리가 큰 사람이 먼저 말하는 게 말차례예요","correct":true,"mis_target":"K2-1-u1-X03"},{"t":"소율 — 한 사람씩 차례대로 말해요","mis":"K2-1-u1-X16"},{"t":"예린 — 다른 사람 말을 끝까지 들어요","mis":"K2-1-u1-X16"}],"explanation":["목소리가 크다고 먼저 말하는 것이 아니에요.","말차례는 한 사람씩 차례대로 말하는 거예요.","소율이와 예린이는 바르게 말했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모둠 친구들이 말차례에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 먼저 말하기 시작한 사람이 끝까지 혼자 말해요","correct":true,"mis_target":"K2-1-u1-X05"},{"t":"태민 — 말하고 싶으면 손을 들어요","mis":"K2-1-u1-X16"},{"t":"지호 — 내 차례에 또박또박 말해요","mis":"K2-1-u1-X16"}],"explanation":["한 사람이 혼자 말하면 다른 친구는 말할 수 없어요.","모두가 돌아가며 말해요.","태민이와 지호는 바르게 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#1','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C3',2,'mc','auto','말차례가 필요한 까닭은 무엇인가요?',ARRAY['K2-1-u1-X03','K2-1-u1-X05']::text[],false,'{"seq":1,"concept":"K2-1-u1-C3","difficulty":2,"kind":"mc","stem":"말차례가 필요한 까닭은 무엇인가요?","options":[{"t":"서로의 말을 잘 듣고 이야기를 이어 가기 위해서","correct":true},{"t":"이야기를 빨리 끝내기 위해서","mis":"K2-1-u1-X03"},{"t":"말 잘하는 친구만 말하게 하려고","mis":"K2-1-u1-X05"}],"explanation":["차례대로 말하면 서로의 말이 잘 들려요.","그래서 이야기가 차근차근 이어져요.","모두가 말할 기회를 얻어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#2','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C4',2,'mc','auto','친구와 동시에 말을 시작했어요. 어떻게 하면 좋을까요?',ARRAY['K2-1-u1-X03']::text[],false,'{"seq":2,"concept":"K2-1-u1-C4","difficulty":2,"kind":"mc","stem":"친구와 동시에 말을 시작했어요. 어떻게 하면 좋을까요?","options":[{"t":"「먼저 말해.」 하고 친구에게 차례를 양보해요","correct":true},{"t":"목소리를 더 크게 해서 끝까지 말해요","mis":"K2-1-u1-X03"},{"t":"친구 말을 막고 내가 먼저라고 말해요","mis":"K2-1-u1-X03"}],"explanation":["동시에 말하면 둘 다 들리지 않아요.","한 사람이 양보하고 끝까지 들은 뒤 말해요.","크게 말하거나 막는 것은 말차례를 어기는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#3','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C4',3,'mc','auto','대화를 읽고 답해 보세요. 도윤이가 이어서 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X04','K2-1-u1-X13']::text[],false,'{"seq":3,"concept":"K2-1-u1-C4","difficulty":3,"kind":"mc","stem":"대화를 읽고 답해 보세요. 도윤이가 이어서 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「나는 과일을 가져갈래. 같이 나눠 먹자.」","correct":true},{"t":"「나 어제 게임에서 이겼어!」","mis":"K2-1-u1-X04"},{"t":"「김밥은 맛없어. 그런 걸 왜 가져가?」","mis":"K2-1-u1-X13"}],"explanation":["다은이는 「너는?」 하고 도윤이에게 차례를 건넸어요.","도윤이는 소풍에 무엇을 가져갈지 대답해야 해요.","친구 말을 깎아내리거나 관계없는 말을 하면 대화가 끊겨요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"이번 소풍 때 뭐 가져갈 거야?"},{"who":"다은","text":"나는 김밥을 가져갈 거야. 너는?"},{"who":"도윤","text":"( ? )"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#4','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C3',3,'ox','auto','말차례를 지키려면 아무 말도 하지 않고 듣기만 하면 돼요.',ARRAY['K2-1-u1-X05']::text[],false,'{"seq":4,"concept":"K2-1-u1-C3","difficulty":3,"kind":"ox","stem":"말차례를 지키려면 아무 말도 하지 않고 듣기만 하면 돼요.","answer":"X","reason_options":[{"t":"듣고 나서 내 차례에는 내 생각을 말해야 하니까","correct":true},{"t":"말을 안 하면 끼어들 일이 없으니까","mis":"K2-1-u1-X05"}],"mis":"K2-1-u1-X05","explanation":["말차례는 듣기와 말하기가 번갈아 이어지는 거예요.","내 차례가 오면 내 생각을 말해요.","듣기만 하면 대화가 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#5','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C3',3,'mc','auto','대화를 읽고 답해 보세요. 이 대화에서 생긴 문제는 무엇인가요?',ARRAY['K2-1-u1-X16','K2-1-u1-X11']::text[],false,'{"seq":5,"concept":"K2-1-u1-C3","difficulty":3,"kind":"mc","stem":"대화를 읽고 답해 보세요. 이 대화에서 생긴 문제는 무엇인가요?","options":[{"t":"두 친구가 서로 말을 끊어 무슨 말인지 알기 어려워요","correct":true},{"t":"민호가 질문을 해서 생긴 문제예요","mis":"K2-1-u1-X16"},{"t":"놀이 이름이 어려워서 생긴 문제예요","mis":"K2-1-u1-X11"}],"explanation":["로아와 지안이는 서로 말을 끊었어요.","그래서 둘 다 하고 싶은 말을 끝내지 못했어요.","한 사람씩 끝까지 말하고 들어요."],"asset":{"type":"speech","turns":[{"who":"민호","text":"우리 무슨 놀이 할까?"},{"who":"로아","text":"술래잡기!"},{"who":"지안","text":"아니야, 공놀이가…"},{"who":"로아","text":"술래잡기가 더 재밌…"},{"who":"지안","text":"공놀이가 더…"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#6','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C4',3,'error','auto','친구들이 말차례를 지키는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X02','K2-1-u1-X16']::text[],false,'{"seq":6,"concept":"K2-1-u1-C4","difficulty":3,"kind":"error","stem":"친구들이 말차례를 지키는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 내 생각이 맞으면 친구 말을 끊어도 돼요","correct":true,"mis_target":"K2-1-u1-X02"},{"t":"서윤 — 말하고 싶으면 손을 들고 기다려요","mis":"K2-1-u1-X16"},{"t":"태민 — 친구 말이 끝나면 내 차례에 말해요","mis":"K2-1-u1-X16"}],"explanation":["내 생각이 맞아도 친구 말을 끊으면 안 돼요.","친구 말이 끝난 뒤 말해요.","서윤이와 태민이는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#7','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C4',3,'mc','auto','모둠에서 한 번도 말하지 못한 친구가 있어요. 어떻게 하면 좋을까요?',ARRAY['K2-1-u1-X05']::text[],false,'{"seq":7,"concept":"K2-1-u1-C4","difficulty":3,"kind":"mc","stem":"모둠에서 한 번도 말하지 못한 친구가 있어요. 어떻게 하면 좋을까요?","options":[{"t":"「너는 어떻게 생각해?」 하고 차례를 건네요","correct":true},{"t":"말하지 않는 친구는 그냥 두어요","mis":"K2-1-u1-X05"},{"t":"내가 대신 더 많이 말해요","mis":"K2-1-u1-X05"}],"explanation":["말차례는 모두가 돌아가며 말하는 거예요.","말하지 못한 친구에게 차례를 건네요.","그러면 모두의 생각을 들을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#8','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C3',4,'mc','auto','세 모둠이 이야기를 나눴어요. 말차례를 가장 잘 지킨 모둠은 어디인가요?',ARRAY['K2-1-u1-X02','K2-1-u1-X03']::text[],false,'{"seq":8,"concept":"K2-1-u1-C3","difficulty":4,"kind":"mc","stem":"세 모둠이 이야기를 나눴어요. 말차례를 가장 잘 지킨 모둠은 어디인가요?","options":[{"t":"가 모둠 — 한 사람씩 돌아가며 말하고, 다른 친구는 끝까지 들었어요","correct":true},{"t":"나 모둠 — 하고 싶은 말이 있으면 누구든 바로 말했어요","mis":"K2-1-u1-X02"},{"t":"다 모둠 — 목소리가 큰 친구가 주로 말했어요","mis":"K2-1-u1-X03"}],"explanation":["가 모둠은 한 사람씩 돌아가며 말했어요.","나 모둠은 끼어들기, 다 모둠은 한 사람만 말하기가 생겨요.","차례대로, 끝까지 듣기, 고르게 말하기를 함께 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#9','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C3',4,'essay','teacher','말차례를 지키지 않아 생긴 일을 떠올리거나 상상해서 쓰고, 어떻게 하면 좋았을지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u1-C3","difficulty":4,"kind":"essay","stem":"말차례를 지키지 않아 생긴 일을 떠올리거나 상상해서 쓰고, 어떻게 하면 좋았을지 써 보세요.","answer_guide":{"answer":"예: 모둠에서 모두 한꺼번에 말해서 무엇을 정했는지 아무도 몰랐습니다. 손을 들고 한 사람씩 말했으면 좋았을 것입니다.","scoring_points":["말차례를 지키지 않은 일을 썼는가","그 때문에 생긴 문제를 썼는가","말차례를 지키는 방법으로 고쳐 썼는가"]},"explanation":["일어난 일.","생긴 문제.","고치는 방법."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#10','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C4',4,'essay','teacher','짝에게 「좋아하는 놀이가 뭐야?」 하고 물었을 때 이어질 대화를 말차례를 지켜 네 마디로 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u1-C4","difficulty":4,"kind":"essay","stem":"짝에게 「좋아하는 놀이가 뭐야?」 하고 물었을 때 이어질 대화를 말차례를 지켜 네 마디로 써 보세요.","answer_guide":{"answer":"예: 나: 좋아하는 놀이가 뭐야? / 짝: 나는 술래잡기를 좋아해. 너는? / 나: 나는 공기놀이를 좋아해. / 짝: 그럼 쉬는 시간에 같이 하자!","scoring_points":["한 사람씩 번갈아 네 마디를 썼는가","묻는 말에 알맞게 대답했는가","되묻거나 이어 말해 대화가 이어졌는가"]},"explanation":["번갈아 말하기.","알맞은 대답.","대화 잇기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#1','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 하람이는 무엇을 집에 두고 왔나요?',ARRAY['K2-1-u1-X11']::text[],true,'{"seq":1,"concept":"K2-1-u1-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 하람이는 무엇을 집에 두고 왔나요?","options":[{"t":"줄넘기 줄","correct":true},{"t":"공","mis":"K2-1-u1-X11"},{"t":"물통","mis":"K2-1-u1-X11"}],"explanation":["「줄넘기 줄을 집에 두고 와서」라고 나와 있어요.","공이나 물통은 이야기에 나오지 않아요.","글에서 찾아 답해요."],"asset":{"type":"passage","lines":["체육 시간에 줄넘기를 했어요.","하람이는 줄넘기 줄을 집에 두고 와서 발을 동동 굴렀어요.","그 모습을 본 다은이가 「내 줄로 같이 연습하자!」 하고 말했어요.","두 친구는 한 번씩 번갈아 가며 줄을 넘었어요.","하람이는 「고마워, 다은아!」 하고 활짝 웃었어요."],"title":"나눠 쓴 줄넘기"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 시우는 무엇을 안쪽으로 옮겼나요?","options":[{"t":"화분","correct":true},{"t":"우산","mis":"K2-1-u1-X11"},{"t":"책상","mis":"K2-1-u1-X11"}],"explanation":["「화분을 안쪽으로 옮겼어요」라고 나와 있어요.","우산이나 책상은 옮기지 않았어요.","글에서 찾아 답해요."],"asset":{"type":"passage","lines":["아침부터 비가 내렸어요.","교실 창가의 화분이 비에 흠뻑 젖고 있었어요.","시우가 얼른 창문을 닫고 화분을 안쪽으로 옮겼어요.","선생님께서 「시우 덕분에 꽃이 무사하구나.」 하고 칭찬하셨어요.","시우는 쑥스러웠지만 기분이 좋았어요."],"title":"빗속의 화분"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#2','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 「내 줄로 같이 연습하자!」 하고 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X11']::text[],true,'{"seq":2,"concept":"K2-1-u1-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 「내 줄로 같이 연습하자!」 하고 말한 친구는 누구인가요?","options":[{"t":"다은","correct":true},{"t":"하람","mis":"K2-1-u1-X11"},{"t":"선생님","mis":"K2-1-u1-X11"}],"explanation":["그 말을 한 친구는 다은이에요.","하람이는 줄을 두고 온 친구예요.","누가 한 말인지 글에서 짚어요."],"asset":{"type":"passage","lines":["체육 시간에 줄넘기를 했어요.","하람이는 줄넘기 줄을 집에 두고 와서 발을 동동 굴렀어요.","그 모습을 본 다은이가 「내 줄로 같이 연습하자!」 하고 말했어요.","두 친구는 한 번씩 번갈아 가며 줄을 넘었어요.","하람이는 「고마워, 다은아!」 하고 활짝 웃었어요."],"title":"나눠 쓴 줄넘기"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 시우를 칭찬한 사람은 누구인가요?","options":[{"t":"선생님","correct":true},{"t":"시우","mis":"K2-1-u1-X11"},{"t":"친구들","mis":"K2-1-u1-X11"}],"explanation":["선생님께서 시우를 칭찬하셨어요.","칭찬을 들은 사람이 시우예요.","누가 한 말인지 글에서 짚어요."],"asset":{"type":"passage","lines":["아침부터 비가 내렸어요.","교실 창가의 화분이 비에 흠뻑 젖고 있었어요.","시우가 얼른 창문을 닫고 화분을 안쪽으로 옮겼어요.","선생님께서 「시우 덕분에 꽃이 무사하구나.」 하고 칭찬하셨어요.","시우는 쑥스러웠지만 기분이 좋았어요."],"title":"빗속의 화분"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#3','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C6',1,'mc','auto','이야기를 읽고 답해 보세요. 줄을 함께 쓴 하람이는 어떤 마음이었을까요?',ARRAY['K2-1-u1-X12']::text[],true,'{"seq":3,"concept":"K2-1-u1-C6","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 줄을 함께 쓴 하람이는 어떤 마음이었을까요?","options":[{"t":"고맙고 기쁜 마음","correct":true},{"t":"화나는 마음","mis":"K2-1-u1-X12"},{"t":"심심한 마음","mis":"K2-1-u1-X12"}],"explanation":["하람이는 「고마워, 다은아!」 하고 활짝 웃었어요.","곤란할 때 도움을 받으면 고맙고 기뻐요.","인물이 한 말과 모습에서 마음을 찾아요."],"asset":{"type":"passage","lines":["체육 시간에 줄넘기를 했어요.","하람이는 줄넘기 줄을 집에 두고 와서 발을 동동 굴렀어요.","그 모습을 본 다은이가 「내 줄로 같이 연습하자!」 하고 말했어요.","두 친구는 한 번씩 번갈아 가며 줄을 넘었어요.","하람이는 「고마워, 다은아!」 하고 활짝 웃었어요."],"title":"나눠 쓴 줄넘기"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 칭찬을 들은 시우는 어떤 마음이었을까요?","options":[{"t":"쑥스럽지만 기쁜 마음","correct":true},{"t":"슬픈 마음","mis":"K2-1-u1-X12"},{"t":"무서운 마음","mis":"K2-1-u1-X12"}],"explanation":["「쑥스러웠지만 기분이 좋았어요」라고 나와 있어요.","칭찬을 들어서 기뻤어요.","글에 나온 마음을 찾아요."],"asset":{"type":"passage","lines":["아침부터 비가 내렸어요.","교실 창가의 화분이 비에 흠뻑 젖고 있었어요.","시우가 얼른 창문을 닫고 화분을 안쪽으로 옮겼어요.","선생님께서 「시우 덕분에 꽃이 무사하구나.」 하고 칭찬하셨어요.","시우는 쑥스러웠지만 기분이 좋았어요."],"title":"빗속의 화분"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#4','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C5',1,'ox','auto','이야기를 읽고 답해 보세요. 하람이와 다은이는 한 번씩 번갈아 가며 줄을 넘었어요.',ARRAY['K2-1-u1-X11']::text[],true,'{"seq":4,"concept":"K2-1-u1-C5","difficulty":1,"kind":"ox","stem":"이야기를 읽고 답해 보세요. 하람이와 다은이는 한 번씩 번갈아 가며 줄을 넘었어요.","answer":"O","reason_options":[{"t":"이야기에 번갈아 가며 줄을 넘었다고 나와 있으니까","correct":true},{"t":"줄이 하나뿐이라 다은이만 넘었을 테니까","mis":"K2-1-u1-X11"}],"mis":"K2-1-u1-X11","explanation":["「한 번씩 번갈아 가며 줄을 넘었어요」라고 나와 있어요.","줄이 하나여도 번갈아 쓸 수 있어요.","짐작보다 글을 먼저 살펴요."],"asset":{"type":"passage","lines":["체육 시간에 줄넘기를 했어요.","하람이는 줄넘기 줄을 집에 두고 와서 발을 동동 굴렀어요.","그 모습을 본 다은이가 「내 줄로 같이 연습하자!」 하고 말했어요.","두 친구는 한 번씩 번갈아 가며 줄을 넘었어요.","하람이는 「고마워, 다은아!」 하고 활짝 웃었어요."],"title":"나눠 쓴 줄넘기"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 시우는 비에 젖는 화분을 보고 그냥 지나갔어요.","answer":"X","reason_options":[{"t":"시우는 창문을 닫고 화분을 옮겼으니까","correct":true},{"t":"비 오는 날에는 화분을 그냥 두니까","mis":"K2-1-u1-X11"}],"explanation":["시우는 창문을 닫고 화분을 안쪽으로 옮겼어요.","그냥 지나가지 않았어요.","글에 나온 일을 찾아요."],"asset":{"type":"passage","lines":["아침부터 비가 내렸어요.","교실 창가의 화분이 비에 흠뻑 젖고 있었어요.","시우가 얼른 창문을 닫고 화분을 안쪽으로 옮겼어요.","선생님께서 「시우 덕분에 꽃이 무사하구나.」 하고 칭찬하셨어요.","시우는 쑥스러웠지만 기분이 좋았어요."],"title":"빗속의 화분"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#5','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C6',2,'mc','auto','이야기를 읽고 답해 보세요. 다은이가 줄을 같이 쓰자고 한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X12','K2-1-u1-X11']::text[],true,'{"seq":5,"concept":"K2-1-u1-C6","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 다은이가 줄을 같이 쓰자고 한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"하람이가 줄이 없어 곤란해 보였기 때문이에요","correct":true},{"t":"다은이가 줄넘기를 싫어해서예요","mis":"K2-1-u1-X12"},{"t":"선생님께서 시키셨기 때문이에요","mis":"K2-1-u1-X11"}],"explanation":["다은이는 발을 동동 구르는 하람이를 보았어요.","친구가 곤란해 보여서 돕고 싶었어요.","선생님이 시키셨다는 말은 이야기에 없어요."],"asset":{"type":"passage","lines":["체육 시간에 줄넘기를 했어요.","하람이는 줄넘기 줄을 집에 두고 와서 발을 동동 굴렀어요.","그 모습을 본 다은이가 「내 줄로 같이 연습하자!」 하고 말했어요.","두 친구는 한 번씩 번갈아 가며 줄을 넘었어요.","하람이는 「고마워, 다은아!」 하고 활짝 웃었어요."],"title":"나눠 쓴 줄넘기"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 시우가 창문을 닫은 까닭은 무엇인가요?","options":[{"t":"화분이 비에 젖고 있었기 때문이에요","correct":true},{"t":"교실이 너무 더웠기 때문이에요","mis":"K2-1-u1-X11"},{"t":"선생님께서 시키셨기 때문이에요","mis":"K2-1-u1-X11"}],"explanation":["창가의 화분이 비에 흠뻑 젖고 있었어요.","그래서 시우가 창문을 닫았어요.","이야기에 나온 까닭을 찾아요."],"asset":{"type":"passage","lines":["아침부터 비가 내렸어요.","교실 창가의 화분이 비에 흠뻑 젖고 있었어요.","시우가 얼른 창문을 닫고 화분을 안쪽으로 옮겼어요.","선생님께서 「시우 덕분에 꽃이 무사하구나.」 하고 칭찬하셨어요.","시우는 쑥스러웠지만 기분이 좋았어요."],"title":"빗속의 화분"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#6','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C5',2,'mc','auto','이야기를 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X11']::text[],true,'{"seq":6,"concept":"K2-1-u1-C5","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"줄을 두고 옴 → 같이 하자고 함 → 번갈아 넘음","correct":true},{"t":"같이 하자고 함 → 줄을 두고 옴 → 번갈아 넘음","mis":"K2-1-u1-X11"},{"t":"번갈아 넘음 → 줄을 두고 옴 → 같이 하자고 함","mis":"K2-1-u1-X11"}],"explanation":["먼저 하람이가 줄을 두고 왔어요.","그다음 다은이가 같이 하자고 했고, 둘이 번갈아 넘었어요.","이야기의 앞에서부터 차례로 짚어요."],"asset":{"type":"passage","lines":["체육 시간에 줄넘기를 했어요.","하람이는 줄넘기 줄을 집에 두고 와서 발을 동동 굴렀어요.","그 모습을 본 다은이가 「내 줄로 같이 연습하자!」 하고 말했어요.","두 친구는 한 번씩 번갈아 가며 줄을 넘었어요.","하람이는 「고마워, 다은아!」 하고 활짝 웃었어요."],"title":"나눠 쓴 줄넘기"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이야기를 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"비가 내림 → 화분을 옮김 → 칭찬을 들음","correct":true},{"t":"칭찬을 들음 → 비가 내림 → 화분을 옮김","mis":"K2-1-u1-X11"},{"t":"화분을 옮김 → 칭찬을 들음 → 비가 내림","mis":"K2-1-u1-X11"}],"explanation":["먼저 비가 내렸어요.","그다음 시우가 화분을 옮겼고, 선생님께 칭찬을 들었어요.","이야기의 앞에서부터 차례로 짚어요."],"asset":{"type":"passage","lines":["아침부터 비가 내렸어요.","교실 창가의 화분이 비에 흠뻑 젖고 있었어요.","시우가 얼른 창문을 닫고 화분을 안쪽으로 옮겼어요.","선생님께서 「시우 덕분에 꽃이 무사하구나.」 하고 칭찬하셨어요.","시우는 쑥스러웠지만 기분이 좋았어요."],"title":"빗속의 화분"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#7','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C6',2,'mc','auto','이야기를 읽고 친구들과 생각을 나눌 때 바른 모습은 어느 것인가요?',ARRAY['K2-1-u1-X13','K2-1-u1-X05']::text[],true,'{"seq":7,"concept":"K2-1-u1-C6","difficulty":2,"kind":"mc","stem":"이야기를 읽고 친구들과 생각을 나눌 때 바른 모습은 어느 것인가요?","options":[{"t":"내 생각을 말하고, 친구 생각도 끝까지 들어요","correct":true},{"t":"내 생각과 다르면 「틀렸어!」라고 말해요","mis":"K2-1-u1-X13"},{"t":"내 생각만 여러 번 말해요","mis":"K2-1-u1-X05"}],"explanation":["생각 나누기는 말하기와 듣기를 함께 하는 거예요.","다른 생각도 끝까지 들어요.","내 생각만 되풀이하면 다른 친구가 말할 수 없어요."],"variant_rule":{"alt":[{"stem":"친구가 나와 다른 생각을 말했어요. 알맞은 반응은 어느 것인가요?","options":[{"t":"「그렇게 생각할 수도 있구나.」","correct":true},{"t":"「아니야, 네 생각은 틀렸어.」","mis":"K2-1-u1-X13"},{"t":"못 들은 척 내 이야기를 해요","mis":"K2-1-u1-X04"}],"explanation":["같은 글을 읽어도 생각은 여러 가지일 수 있어요.","다른 생각을 인정해 주어요.","궁금하면 「왜 그렇게 생각해?」 하고 물어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#8','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C6',2,'match','auto','이야기를 읽고, 인물과 그때의 마음을 이어 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u1-C6","difficulty":2,"kind":"match","stem":"이야기를 읽고, 인물과 그때의 마음을 이어 보세요.","pairs":[{"l":"줄을 두고 와 발을 구르는 하람","r":"걱정되는 마음"},{"l":"줄을 빌려준 다은","r":"돕고 싶은 마음"},{"l":"같이 줄을 넘은 하람","r":"고맙고 기쁜 마음"}],"mis":"K2-1-u1-X12","explanation":["줄이 없어 발을 구를 때는 걱정되었어요.","다은이는 친구를 돕고 싶었어요.","같이 줄을 넘게 된 하람이는 고맙고 기뻤어요."],"asset":{"type":"passage","lines":["체육 시간에 줄넘기를 했어요.","하람이는 줄넘기 줄을 집에 두고 와서 발을 동동 굴렀어요.","그 모습을 본 다은이가 「내 줄로 같이 연습하자!」 하고 말했어요.","두 친구는 한 번씩 번갈아 가며 줄을 넘었어요.","하람이는 「고마워, 다은아!」 하고 활짝 웃었어요."],"title":"나눠 쓴 줄넘기"},"variant_rule":{"alt":[{"stem":"일어난 일과 어울리는 마음을 이어 보세요.","pairs":[{"l":"친구가 우산을 씌워 주었을 때","r":"고마운 마음"},{"l":"아끼는 연필을 잃어버렸을 때","r":"속상한 마음"},{"l":"그림 대회에서 상을 받았을 때","r":"뿌듯한 마음"}],"explanation":["도움을 받으면 고마워요.","아끼는 것을 잃으면 속상해요.","애쓴 일이 잘되면 뿌듯해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#9','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C6',2,'ox','auto','같은 이야기를 읽고 친구와 생각이 다르면 둘 중 하나는 틀린 거예요.',ARRAY['K2-1-u1-X13']::text[],true,'{"seq":9,"concept":"K2-1-u1-C6","difficulty":2,"kind":"ox","stem":"같은 이야기를 읽고 친구와 생각이 다르면 둘 중 하나는 틀린 거예요.","answer":"X","reason_options":[{"t":"같은 글을 읽어도 생각은 여러 가지일 수 있으니까","correct":true},{"t":"정답은 언제나 하나뿐이니까","mis":"K2-1-u1-X13"}],"mis":"K2-1-u1-X13","explanation":["생각은 사람마다 다를 수 있어요.","까닭이 있으면 다른 생각도 귀하게 들어요.","「왜 그렇게 생각해?」 하고 물어봐요."],"variant_rule":{"alt":[{"stem":"이야기를 읽고 「나라면 어떻게 했을까?」 하고 생각해 보면 이야기를 나누기 쉬워져요.","answer":"O","reason_options":[{"t":"내 생각을 떠올려야 나눌 수 있으니까","correct":true},{"t":"이야기는 읽기만 하면 끝이니까","mis":"K2-1-u1-X13"}],"explanation":["「나라면?」 하고 떠올리면 내 생각이 생겨요.","떠올린 생각을 친구와 나눠요.","읽기만 하고 끝내지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#10','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C5',3,'error','auto','이야기를 읽고 친구들이 내용을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X11','K2-1-u1-X16']::text[],true,'{"seq":10,"concept":"K2-1-u1-C5","difficulty":3,"kind":"error","stem":"이야기를 읽고 친구들이 내용을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민호 — 다은이가 줄을 두고 와서 하람이가 빌려주었어요","correct":true,"mis_target":"K2-1-u1-X11"},{"t":"소율 — 하람이가 줄을 두고 왔어요","mis":"K2-1-u1-X16"},{"t":"도윤 — 두 친구가 번갈아 줄을 넘었어요","mis":"K2-1-u1-X16"}],"explanation":["줄을 두고 온 친구는 하람이에요.","민호는 두 인물을 바꾸어 말했어요.","누가 무엇을 했는지 글에서 짚어요."],"asset":{"type":"passage","lines":["체육 시간에 줄넘기를 했어요.","하람이는 줄넘기 줄을 집에 두고 와서 발을 동동 굴렀어요.","그 모습을 본 다은이가 「내 줄로 같이 연습하자!」 하고 말했어요.","두 친구는 한 번씩 번갈아 가며 줄을 넘었어요.","하람이는 「고마워, 다은아!」 하고 활짝 웃었어요."],"title":"나눠 쓴 줄넘기"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이야기를 읽고 친구들이 내용을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 선생님께서 창문을 닫고 화분을 옮기셨어요","correct":true,"mis_target":"K2-1-u1-X11"},{"t":"지호 — 비가 와서 화분이 젖고 있었어요","mis":"K2-1-u1-X16"},{"t":"서아 — 시우가 칭찬을 들었어요","mis":"K2-1-u1-X16"}],"explanation":["창문을 닫고 화분을 옮긴 사람은 시우예요.","예린이는 인물을 바꾸어 말했어요.","누가 무엇을 했는지 글에서 짚어요."],"asset":{"type":"passage","lines":["아침부터 비가 내렸어요.","교실 창가의 화분이 비에 흠뻑 젖고 있었어요.","시우가 얼른 창문을 닫고 화분을 안쪽으로 옮겼어요.","선생님께서 「시우 덕분에 꽃이 무사하구나.」 하고 칭찬하셨어요.","시우는 쑥스러웠지만 기분이 좋았어요."],"title":"빗속의 화분"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#1','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C5',2,'mc','auto','이야기를 읽고 답해 보세요. 모래성이 무너진 까닭은 무엇인가요?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":1,"concept":"K2-1-u1-C5","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 모래성이 무너진 까닭은 무엇인가요?","options":[{"t":"큰 파도가 밀려와서","correct":true},{"t":"로아가 밟아서","mis":"K2-1-u1-X11"},{"t":"바람이 세게 불어서","mis":"K2-1-u1-X11"}],"explanation":["「큰 파도가 밀려와 모래성 한쪽이 무너졌어요」라고 나와 있어요.","로아가 밟았다거나 바람이 불었다는 말은 없어요.","까닭도 글에서 찾아요."],"asset":{"type":"passage","lines":["토요일에 지안이와 동생 로아가 바닷가에 갔어요.","둘은 커다란 모래성을 쌓았어요.","그런데 큰 파도가 밀려와 모래성 한쪽이 무너졌어요.","로아가 울먹이자 지안이가 「괜찮아, 다시 쌓으면 더 멋질 거야.」 하고 말했어요.","둘은 무너진 곳에 조개껍데기를 꽂아 더 멋진 모래성을 만들었어요."],"title":"함께 만든 모래성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#2','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C6',2,'mc','auto','이야기를 읽고 답해 보세요. 모래성이 무너졌을 때 로아는 어떤 마음이었을까요?',ARRAY['K2-1-u1-X12']::text[],false,'{"seq":2,"concept":"K2-1-u1-C6","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 모래성이 무너졌을 때 로아는 어떤 마음이었을까요?","options":[{"t":"속상해서 울고 싶은 마음","correct":true},{"t":"신나는 마음","mis":"K2-1-u1-X12"},{"t":"졸린 마음","mis":"K2-1-u1-X12"}],"explanation":["로아는 울먹였어요.","애써 쌓은 모래성이 무너지면 속상해요.","인물의 모습에서 마음을 짐작해요."],"asset":{"type":"passage","lines":["토요일에 지안이와 동생 로아가 바닷가에 갔어요.","둘은 커다란 모래성을 쌓았어요.","그런데 큰 파도가 밀려와 모래성 한쪽이 무너졌어요.","로아가 울먹이자 지안이가 「괜찮아, 다시 쌓으면 더 멋질 거야.」 하고 말했어요.","둘은 무너진 곳에 조개껍데기를 꽂아 더 멋진 모래성을 만들었어요."],"title":"함께 만든 모래성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#3','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C6',3,'mc','auto','이야기를 읽고 답해 보세요. 지안이가 「괜찮아, 다시 쌓으면 더 멋질 거야.」라고 말한 까닭은 무엇일까요?',ARRAY['K2-1-u1-X12']::text[],false,'{"seq":3,"concept":"K2-1-u1-C6","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 지안이가 「괜찮아, 다시 쌓으면 더 멋질 거야.」라고 말한 까닭은 무엇일까요?","options":[{"t":"속상한 동생을 달래 주고 싶어서","correct":true},{"t":"모래성이 싫어져서","mis":"K2-1-u1-X12"},{"t":"집에 빨리 가고 싶어서","mis":"K2-1-u1-X12"}],"explanation":["로아가 울먹이자 지안이가 이 말을 했어요.","동생의 속상한 마음을 달래 주려는 말이에요.","말한 때와 상황을 함께 살펴요."],"asset":{"type":"passage","lines":["토요일에 지안이와 동생 로아가 바닷가에 갔어요.","둘은 커다란 모래성을 쌓았어요.","그런데 큰 파도가 밀려와 모래성 한쪽이 무너졌어요.","로아가 울먹이자 지안이가 「괜찮아, 다시 쌓으면 더 멋질 거야.」 하고 말했어요.","둘은 무너진 곳에 조개껍데기를 꽂아 더 멋진 모래성을 만들었어요."],"title":"함께 만든 모래성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#4','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C5',3,'mc','auto','이야기를 읽고 답해 보세요. 두 사람이 마지막에 한 일은 무엇인가요?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":4,"concept":"K2-1-u1-C5","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 두 사람이 마지막에 한 일은 무엇인가요?","options":[{"t":"무너진 곳에 조개껍데기를 꽂아 모래성을 다시 만들었어요","correct":true},{"t":"모래성을 그대로 두고 집에 갔어요","mis":"K2-1-u1-X11"},{"t":"다른 바닷가로 옮겨 갔어요","mis":"K2-1-u1-X11"}],"explanation":["마지막 문장에 조개껍데기를 꽂아 더 멋진 모래성을 만들었다고 나와요.","집에 가거나 옮겨 갔다는 말은 없어요.","이야기의 끝까지 읽어요."],"asset":{"type":"passage","lines":["토요일에 지안이와 동생 로아가 바닷가에 갔어요.","둘은 커다란 모래성을 쌓았어요.","그런데 큰 파도가 밀려와 모래성 한쪽이 무너졌어요.","로아가 울먹이자 지안이가 「괜찮아, 다시 쌓으면 더 멋질 거야.」 하고 말했어요.","둘은 무너진 곳에 조개껍데기를 꽂아 더 멋진 모래성을 만들었어요."],"title":"함께 만든 모래성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#5','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C6',3,'error','auto','이야기를 읽고 친구들이 생각을 나눴어요. 이야기와 맞지 않게 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X12','K2-1-u1-X16']::text[],false,'{"seq":5,"concept":"K2-1-u1-C6","difficulty":3,"kind":"error","stem":"이야기를 읽고 친구들이 생각을 나눴어요. 이야기와 맞지 않게 말한 친구는 누구인가요?","options":[{"t":"태민 — 지안이는 동생이 울어서 짜증이 났을 것 같아","correct":true,"mis_target":"K2-1-u1-X12"},{"t":"예린 — 지안이는 동생을 아끼는 것 같아","mis":"K2-1-u1-X16"},{"t":"하린 — 나라도 다시 쌓자고 했을 거야","mis":"K2-1-u1-X16"}],"explanation":["지안이는 동생을 따뜻하게 달래 주었어요.","짜증이 났다는 짐작은 지안이의 말과 맞지 않아요.","인물이 한 말과 행동에서 마음을 짐작해요."],"asset":{"type":"passage","lines":["토요일에 지안이와 동생 로아가 바닷가에 갔어요.","둘은 커다란 모래성을 쌓았어요.","그런데 큰 파도가 밀려와 모래성 한쪽이 무너졌어요.","로아가 울먹이자 지안이가 「괜찮아, 다시 쌓으면 더 멋질 거야.」 하고 말했어요.","둘은 무너진 곳에 조개껍데기를 꽂아 더 멋진 모래성을 만들었어요."],"title":"함께 만든 모래성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#6','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C6',3,'ox','auto','「나라면 파도가 닿지 않는 곳에 쌓았을 거야.」는 이야기를 읽고 든 내 생각으로 나눌 수 있어요.',ARRAY['K2-1-u1-X13']::text[],false,'{"seq":6,"concept":"K2-1-u1-C6","difficulty":3,"kind":"ox","stem":"「나라면 파도가 닿지 않는 곳에 쌓았을 거야.」는 이야기를 읽고 든 내 생각으로 나눌 수 있어요.","answer":"O","reason_options":[{"t":"이야기를 읽고 「나라면?」 하고 떠올린 생각이니까","correct":true},{"t":"이야기에 나온 말만 말해야 하니까","mis":"K2-1-u1-X13"}],"mis":"K2-1-u1-X13","explanation":["이야기를 읽고 떠올린 내 생각도 나눌 수 있어요.","「나라면?」은 좋은 생각 나누기예요.","친구들의 다른 생각도 들어 봐요."],"asset":{"type":"passage","lines":["토요일에 지안이와 동생 로아가 바닷가에 갔어요.","둘은 커다란 모래성을 쌓았어요.","그런데 큰 파도가 밀려와 모래성 한쪽이 무너졌어요.","로아가 울먹이자 지안이가 「괜찮아, 다시 쌓으면 더 멋질 거야.」 하고 말했어요.","둘은 무너진 곳에 조개껍데기를 꽂아 더 멋진 모래성을 만들었어요."],"title":"함께 만든 모래성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#7','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C6',3,'mc','auto','이야기를 읽고 생각을 나누고 있어요. 서윤이가 이어서 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X13','K2-1-u1-X04']::text[],false,'{"seq":7,"concept":"K2-1-u1-C6","difficulty":3,"kind":"mc","stem":"이야기를 읽고 생각을 나누고 있어요. 서윤이가 이어서 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「그렇구나. 왜 그렇게 생각해?」","correct":true},{"t":"「그건 틀린 생각이야.」","mis":"K2-1-u1-X13"},{"t":"「나 배고파.」","mis":"K2-1-u1-X04"}],"explanation":["준우는 서윤이와 다른 생각을 말했어요.","다른 생각을 인정하고 까닭을 물으면 이야기가 이어져요.","틀렸다고 하거나 관계없는 말을 하면 나누기가 끊겨요."],"asset":{"type":"speech","turns":[{"who":"서윤","text":"나는 지안이가 참 다정한 것 같아."},{"who":"준우","text":"나는 로아가 울지 않고 다시 쌓자고 했으면 좋았을 것 같아."},{"who":"서윤","text":"( ? )"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#8','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C5',4,'mc','auto','이야기를 읽고 답해 보세요. 이야기의 차례에 맞게 늘어놓은 것은 어느 것인가요?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":8,"concept":"K2-1-u1-C5","difficulty":4,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 이야기의 차례에 맞게 늘어놓은 것은 어느 것인가요?","options":[{"t":"모래성 쌓기 → 파도에 무너짐 → 동생 달래기 → 다시 만들기","correct":true},{"t":"파도에 무너짐 → 모래성 쌓기 → 다시 만들기 → 동생 달래기","mis":"K2-1-u1-X11"},{"t":"동생 달래기 → 모래성 쌓기 → 파도에 무너짐 → 다시 만들기","mis":"K2-1-u1-X11"}],"explanation":["먼저 모래성을 쌓았고, 파도에 무너졌어요.","지안이가 동생을 달랜 뒤 둘이 다시 만들었어요.","일이 일어난 까닭과 결과를 이어 차례를 정해요."],"asset":{"type":"passage","lines":["토요일에 지안이와 동생 로아가 바닷가에 갔어요.","둘은 커다란 모래성을 쌓았어요.","그런데 큰 파도가 밀려와 모래성 한쪽이 무너졌어요.","로아가 울먹이자 지안이가 「괜찮아, 다시 쌓으면 더 멋질 거야.」 하고 말했어요.","둘은 무너진 곳에 조개껍데기를 꽂아 더 멋진 모래성을 만들었어요."],"title":"함께 만든 모래성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#9','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C6',4,'essay','teacher','이야기를 읽고 로아에게 해 주고 싶은 말을 쓰고, 그렇게 생각한 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u1-C6","difficulty":4,"kind":"essay","stem":"이야기를 읽고 로아에게 해 주고 싶은 말을 쓰고, 그렇게 생각한 까닭을 써 보세요.","answer_guide":{"answer":"예: 로아야, 모래성이 무너져서 속상했지? 다시 만든 모래성이 더 멋지니까 힘내! — 애써 쌓은 것이 무너지면 누구나 속상하기 때문입니다.","scoring_points":["로아의 마음을 짐작해 말을 썼는가","그렇게 생각한 까닭을 썼는가","이야기 내용과 맞게 썼는가"]},"explanation":["하고 싶은 말.","까닭.","이야기와 맞게."],"asset":{"type":"passage","lines":["토요일에 지안이와 동생 로아가 바닷가에 갔어요.","둘은 커다란 모래성을 쌓았어요.","그런데 큰 파도가 밀려와 모래성 한쪽이 무너졌어요.","로아가 울먹이자 지안이가 「괜찮아, 다시 쌓으면 더 멋질 거야.」 하고 말했어요.","둘은 무너진 곳에 조개껍데기를 꽂아 더 멋진 모래성을 만들었어요."],"title":"함께 만든 모래성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#10','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C6',4,'essay','teacher','이야기를 읽고 친구들과 생각을 나눌 때 지킬 약속 두 가지를 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u1-C6","difficulty":4,"kind":"essay","stem":"이야기를 읽고 친구들과 생각을 나눌 때 지킬 약속 두 가지를 써 보세요.","answer_guide":{"answer":"예: 한 사람씩 차례대로 말합니다. / 나와 생각이 달라도 끝까지 듣고 「그렇게 생각할 수도 있구나.」라고 말합니다.","scoring_points":["말차례에 관한 약속을 썼는가","다른 생각을 존중하는 약속을 썼는가","지킬 수 있게 구체적으로 썼는가"]},"explanation":["말차례.","다른 생각 존중.","구체적으로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_basic#1','kor',2,1,'u1','L07','g2_1_kor_u1_L07_basic','lesson_basic','K2-1-u1-C7',1,'mc','auto','소개하는 글에 넣을 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],true,'{"seq":1,"concept":"K2-1-u1-C7","difficulty":1,"kind":"mc","stem":"소개하는 글에 넣을 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"내가 잘하는 것","correct":true},{"t":"지금 몇 시인지","mis":"K2-1-u1-X06"},{"t":"버스 도착 시간","mis":"K2-1-u1-X06"}],"explanation":["잘하는 것은 나를 잘 보여 줘요.","시간이나 버스 도착 시간은 나와 관계가 없어요.","나를 알려 주는 내용을 골라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 소개하는 글에 넣을 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"나의 꿈","correct":true},{"t":"오늘 날씨","mis":"K2-1-u1-X06"},{"t":"어제 본 뉴스","mis":"K2-1-u1-X06"}],"explanation":["꿈은 나를 잘 보여 줘요.","날씨나 뉴스는 나를 알려 주지 않아요.","나를 알려 주는 내용을 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_basic#2','kor',2,1,'u1','L07','g2_1_kor_u1_L07_basic','lesson_basic','K2-1-u1-C7',1,'match','auto','소개 항목과 알맞은 예를 이어 보세요.','{}'::text[],true,'{"seq":2,"concept":"K2-1-u1-C7","difficulty":1,"kind":"match","stem":"소개 항목과 알맞은 예를 이어 보세요.","pairs":[{"l":"좋아하는 것","r":"저는 딸기를 좋아합니다."},{"l":"잘하는 것","r":"제가 잘하는 것은 달리기입니다."},{"l":"꿈","r":"제 꿈은 우주 비행사입니다."}],"mis":"K2-1-u1-X10","explanation":["좋아하는 것은 「~을 좋아합니다」로 써요.","잘하는 것은 「제가 잘하는 것은 ~입니다」로 써요.","꿈은 「제 꿈은 ~입니다」로 써요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 소개 항목과 알맞은 예를 이어 보세요.","pairs":[{"l":"이름","r":"저는 정하람입니다."},{"l":"좋아하는 것","r":"저는 공룡 책을 좋아합니다."},{"l":"잘하는 것","r":"제가 잘하는 것은 종이접기입니다."}],"explanation":["이름은 「저는 ○○○입니다」로 써요.","좋아하는 것은 「~을 좋아합니다」로 써요.","잘하는 것은 「제가 잘하는 것은 ~입니다」로 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_basic#3','kor',2,1,'u1','L07','g2_1_kor_u1_L07_basic','lesson_basic','K2-1-u1-C7',1,'mc','auto','「제 꿈은 수의사입니다.」는 어떤 소개 항목인가요?',ARRAY['K2-1-u1-X10']::text[],true,'{"seq":3,"concept":"K2-1-u1-C7","difficulty":1,"kind":"mc","stem":"「제 꿈은 수의사입니다.」는 어떤 소개 항목인가요?","options":[{"t":"꿈","correct":true},{"t":"좋아하는 것","mis":"K2-1-u1-X10"},{"t":"잘하는 것","mis":"K2-1-u1-X10"}],"explanation":["「제 꿈은 ~입니다」는 꿈을 소개하는 문장이에요.","되고 싶은 것을 말하고 있어요.","항목 이름을 문장에서 찾아요."],"variant_rule":{"alt":[{"stem":"「제가 잘하는 것은 수영입니다.」는 어떤 소개 항목인가요?","options":[{"t":"잘하는 것","correct":true},{"t":"꿈","mis":"K2-1-u1-X10"},{"t":"이름","mis":"K2-1-u1-X10"}],"explanation":["「제가 잘하는 것은 ~입니다」는 잘하는 것을 소개해요.","솜씨를 말하고 있어요.","항목 이름을 문장에서 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_basic#4','kor',2,1,'u1','L07','g2_1_kor_u1_L07_basic','lesson_basic','K2-1-u1-C7',1,'ox','auto','소개할 내용을 먼저 정리하면 소개하는 글을 쓰기 쉬워요.',ARRAY['K2-1-u1-X06']::text[],true,'{"seq":4,"concept":"K2-1-u1-C7","difficulty":1,"kind":"ox","stem":"소개할 내용을 먼저 정리하면 소개하는 글을 쓰기 쉬워요.","answer":"O","reason_options":[{"t":"무엇을 쓸지 정하고 쓰니까","correct":true},{"t":"생각나는 대로 쓰는 게 더 빠르니까","mis":"K2-1-u1-X06"}],"mis":"K2-1-u1-X06","explanation":["무엇을 쓸지 먼저 정리해요.","그러면 관계없는 내용이 섞이지 않아요.","이름·좋아하는 것·잘하는 것·꿈 차례로 정리해요."],"variant_rule":{"alt":[{"stem":"소개하는 글에는 생각나는 일을 모두 써야 해요.","answer":"X","reason_options":[{"t":"나를 알려 주는 내용만 골라 써야 하니까","correct":true},{"t":"많이 쓸수록 좋은 글이니까","mis":"K2-1-u1-X06"}],"explanation":["생각나는 일을 다 쓰면 나와 관계없는 내용도 섞여요.","나를 알려 주는 내용만 골라요.","읽을 사람이 궁금해할 것을 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_basic#5','kor',2,1,'u1','L07','g2_1_kor_u1_L07_basic','lesson_basic','K2-1-u1-C7',2,'mc','auto','처음 만난 친구가 더 궁금해할 소개는 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],true,'{"seq":5,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"처음 만난 친구가 더 궁금해할 소개는 어느 것인가요?","options":[{"t":"제가 좋아하는 놀이는 숨바꼭질입니다.","correct":true},{"t":"저는 어제 일찍 잤습니다.","mis":"K2-1-u1-X06"},{"t":"오늘은 월요일입니다.","mis":"K2-1-u1-X06"}],"explanation":["좋아하는 놀이를 알면 같이 놀 수 있어 친구가 궁금해해요.","어제 잔 시간이나 요일은 나를 알려 주지 않아요.","읽을 사람 입장에서 골라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 처음 만난 친구가 더 궁금해할 소개는 어느 것인가요?","options":[{"t":"제가 아끼는 물건은 할머니께서 주신 필통입니다.","correct":true},{"t":"지금 창밖에 비가 옵니다.","mis":"K2-1-u1-X06"},{"t":"저는 오늘 아침밥을 먹었습니다.","mis":"K2-1-u1-X06"}],"explanation":["아끼는 물건은 나를 잘 알려 줘요.","날씨나 아침밥은 친구가 궁금해할 내용이 아니에요.","읽을 사람 입장에서 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_basic#6','kor',2,1,'u1','L07','g2_1_kor_u1_L07_basic','lesson_basic','K2-1-u1-C7',2,'mc','auto','「저는 그림 그리기를 좋아합니다.」에 까닭을 더한 것은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],true,'{"seq":6,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"「저는 그림 그리기를 좋아합니다.」에 까닭을 더한 것은 어느 것인가요?","options":[{"t":"저는 그림 그리기를 좋아합니다. 생각한 것을 마음대로 그릴 수 있기 때문입니다.","correct":true},{"t":"저는 그림 그리기를 좋아합니다. 오늘은 비가 옵니다.","mis":"K2-1-u1-X06"},{"t":"저는 그림 그리기를 좋아합니다. 저는 키가 큽니다.","mis":"K2-1-u1-X06"}],"explanation":["「~기 때문입니다」로 좋아하는 까닭을 더했어요.","날씨나 키는 좋아하는 까닭이 아니에요.","까닭을 더하면 나를 더 잘 알려 줘요."],"variant_rule":{"alt":[{"stem":"「저는 축구를 좋아합니다.」에 까닭을 더한 것은 어느 것인가요?","options":[{"t":"저는 축구를 좋아합니다. 친구들과 함께 뛰면 신나기 때문입니다.","correct":true},{"t":"저는 축구를 좋아합니다. 우리 집은 3층입니다.","mis":"K2-1-u1-X06"},{"t":"저는 축구를 좋아합니다. 어제 늦잠을 잤습니다.","mis":"K2-1-u1-X06"}],"explanation":["「~기 때문입니다」로 좋아하는 까닭을 더했어요.","집 층수나 늦잠은 까닭이 아니에요.","까닭은 앞 문장과 이어져야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_basic#7','kor',2,1,'u1','L07','g2_1_kor_u1_L07_basic','lesson_basic','K2-1-u1-C7',2,'mc','auto','소개할 내용을 정리할 때 소개하기 쉬운 차례는 어느 것인가요?',ARRAY['K2-1-u1-X07','K2-1-u1-X06']::text[],true,'{"seq":7,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"소개할 내용을 정리할 때 소개하기 쉬운 차례는 어느 것인가요?","options":[{"t":"이름 → 좋아하는 것 → 잘하는 것 → 꿈","correct":true},{"t":"잘하는 것 → 꿈 → 좋아하는 것 → 이름","mis":"K2-1-u1-X07"},{"t":"날씨 → 이름 → 급식 → 꿈","mis":"K2-1-u1-X06"}],"explanation":["누구인지 알 수 있게 이름부터 정리해요.","그다음 좋아하는 것, 잘하는 것, 꿈을 이어요.","이름이 끝에 오면 누구 이야기인지 늦게 알게 돼요."],"variant_rule":{"alt":[{"stem":"소개할 내용을 정리할 때 가장 먼저 쓸 항목은 무엇인가요?","options":[{"t":"이름","correct":true},{"t":"꿈","mis":"K2-1-u1-X07"},{"t":"오늘 한 일","mis":"K2-1-u1-X06"}],"explanation":["누구를 소개하는지 이름부터 써요.","꿈은 뒤에 이어 써요.","오늘 한 일은 소개 항목이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_basic#8','kor',2,1,'u1','L07','g2_1_kor_u1_L07_basic','lesson_basic','K2-1-u1-C7',2,'mc','auto','예린이가 정리한 내용을 보고 답해 보세요. 이 정리를 보고 잘못 쓴 문장은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],true,'{"seq":8,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"예린이가 정리한 내용을 보고 답해 보세요. 이 정리를 보고 잘못 쓴 문장은 어느 것인가요?","options":[{"t":"제가 잘하는 것은 고양이입니다.","correct":true},{"t":"저는 오예린입니다.","mis":"K2-1-u1-X16"},{"t":"제 꿈은 동물원 사육사입니다.","mis":"K2-1-u1-X16"}],"explanation":["고양이는 예린이가 좋아하는 것이에요.","잘하는 것은 줄넘기예요.","항목과 내용을 맞추어 문장으로 써요."],"asset":{"type":"passage","lines":["이름: 오예린","좋아하는 것: 고양이","잘하는 것: 줄넘기","꿈: 동물원 사육사"],"title":"소개할 내용 정리"},"variant_rule":{"alt":[{"stem":"태민이가 정리한 내용을 보고 답해 보세요. 이 정리를 보고 잘못 쓴 문장은 어느 것인가요?","options":[{"t":"제 꿈은 수영입니다.","correct":true},{"t":"저는 문태민입니다.","mis":"K2-1-u1-X16"},{"t":"저는 레고 만들기를 좋아합니다.","mis":"K2-1-u1-X16"}],"explanation":["수영은 태민이가 잘하는 것이에요.","태민이의 꿈은 건축가예요.","항목과 내용을 맞추어 문장으로 써요."],"asset":{"type":"passage","lines":["이름: 문태민","좋아하는 것: 레고 만들기","잘하는 것: 수영","꿈: 건축가"],"title":"소개할 내용 정리"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_basic#9','kor',2,1,'u1','L07','g2_1_kor_u1_L07_basic','lesson_basic','K2-1-u1-C7',2,'ox','auto','소개하는 글에는 우리 집 주소도 꼭 넣어야 해요.',ARRAY['K2-1-u1-X14']::text[],true,'{"seq":9,"concept":"K2-1-u1-C7","difficulty":2,"kind":"ox","stem":"소개하는 글에는 우리 집 주소도 꼭 넣어야 해요.","answer":"X","reason_options":[{"t":"주소 같은 개인 정보는 소개하는 글에 넣지 않으니까","correct":true},{"t":"자세하게 쓸수록 좋은 소개니까","mis":"K2-1-u1-X14"}],"mis":"K2-1-u1-X14","explanation":["주소는 남에게 함부로 알리면 안 되는 개인 정보예요.","소개하는 글에는 넣지 않아요.","좋아하는 것, 잘하는 것처럼 나를 알려 주는 내용을 담아요."],"variant_rule":{"alt":[{"stem":"소개하는 글에 내 전화번호를 써야 친구가 나를 잘 알 수 있어요.","answer":"X","reason_options":[{"t":"전화번호는 개인 정보라서 소개하는 글에 넣지 않으니까","correct":true},{"t":"자세하게 쓸수록 좋은 소개니까","mis":"K2-1-u1-X14"}],"explanation":["전화번호는 개인 정보예요.","소개하는 글에는 넣지 않아요.","나를 알려 주는 다른 내용을 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_basic#10','kor',2,1,'u1','L07','g2_1_kor_u1_L07_basic','lesson_basic','K2-1-u1-C7',3,'error','auto','친구들이 소개할 내용을 골랐어요. 알맞지 않게 고른 친구는 누구인가요?',ARRAY['K2-1-u1-X06','K2-1-u1-X16']::text[],true,'{"seq":10,"concept":"K2-1-u1-C7","difficulty":3,"kind":"error","stem":"친구들이 소개할 내용을 골랐어요. 알맞지 않게 고른 친구는 누구인가요?","options":[{"t":"시우 — 「오늘 급식 반찬」을 소개할 내용으로 골랐어요","correct":true,"mis_target":"K2-1-u1-X06"},{"t":"다은 — 「좋아하는 동물」을 골랐어요","mis":"K2-1-u1-X16"},{"t":"지호 — 「잘하는 운동」을 골랐어요","mis":"K2-1-u1-X16"}],"explanation":["오늘 급식 반찬은 시우를 알려 주지 않아요.","좋아하는 동물과 잘하는 운동은 나를 알려 줘요.","나를 알려 주는 내용을 골라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 소개할 내용을 골랐어요. 알맞지 않게 고른 친구는 누구인가요?","options":[{"t":"로아 — 「어제 본 영화 줄거리」를 골랐어요","correct":true,"mis_target":"K2-1-u1-X06"},{"t":"준우 — 「내 꿈」을 골랐어요","mis":"K2-1-u1-X16"},{"t":"하린 — 「아끼는 물건」을 골랐어요","mis":"K2-1-u1-X16"}],"explanation":["영화 줄거리는 로아를 알려 주지 않아요.","꿈과 아끼는 물건은 나를 알려 줘요.","나를 알려 주는 내용을 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#1','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C7',2,'mc','auto','소개할 내용을 고를 때 생각할 점은 무엇인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":1,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"소개할 내용을 고를 때 생각할 점은 무엇인가요?","options":[{"t":"읽을 사람이 궁금해하고 나를 잘 알려 주는 내용인가","correct":true},{"t":"글이 길어지는 내용인가","mis":"K2-1-u1-X06"},{"t":"어려운 낱말이 들어가는 내용인가","mis":"K2-1-u1-X06"}],"explanation":["읽을 사람이 궁금해할지 생각해요.","나를 잘 알려 주는지 생각해요.","길이나 어려운 낱말은 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#2','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C7',2,'mc','auto','「제 꿈은 요리사입니다.」에 까닭을 더하려고 해요. 이어 쓸 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":2,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"「제 꿈은 요리사입니다.」에 까닭을 더하려고 해요. 이어 쓸 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"가족에게 맛있는 음식을 만들어 주고 싶기 때문입니다.","correct":true},{"t":"어제 저녁에 라면을 먹었기 때문입니다.","mis":"K2-1-u1-X06"},{"t":"요리사는 하얀 모자를 씁니다.","mis":"K2-1-u1-X06"}],"explanation":["요리사가 되고 싶은 까닭을 더했어요.","어제 먹은 라면이나 요리사의 모자는 꿈의 까닭이 아니에요.","까닭은 「왜?」에 대한 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#3','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C7',3,'mc','auto','도윤이가 정리한 내용을 보고 답해 보세요. 고쳐야 할 곳은 어디인가요?',ARRAY['K2-1-u1-X16']::text[],false,'{"seq":3,"concept":"K2-1-u1-C7","difficulty":3,"kind":"mc","stem":"도윤이가 정리한 내용을 보고 답해 보세요. 고쳐야 할 곳은 어디인가요?","options":[{"t":"「잘하는 것」 칸에 꿈을 썼어요","correct":true},{"t":"이름 칸에 이름을 썼어요","mis":"K2-1-u1-X16"},{"t":"좋아하는 것 칸에 놀이를 썼어요","mis":"K2-1-u1-X16"}],"explanation":["「경찰관」은 되고 싶은 것, 곧 꿈이에요.","그래서 꿈 칸으로 옮기고, 잘하는 것 칸에는 솜씨를 써요.","항목 이름과 내용이 맞는지 살펴요."],"asset":{"type":"passage","lines":["이름: 한도윤","좋아하는 것: 레고 만들기","잘하는 것: 경찰관","꿈: (비어 있음)"],"title":"소개할 내용 정리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#4','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C7',3,'error','auto','친구들이 소개할 내용에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X10','K2-1-u1-X16']::text[],false,'{"seq":4,"concept":"K2-1-u1-C7","difficulty":3,"kind":"error","stem":"친구들이 소개할 내용에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 좋아하는 것과 잘하는 것은 언제나 같은 거예요","correct":true,"mis_target":"K2-1-u1-X10"},{"t":"소율 — 좋아하는 것에 까닭을 더하면 나를 더 잘 알려 줘요","mis":"K2-1-u1-X16"},{"t":"민호 — 읽을 사람이 궁금해할 것을 골라요","mis":"K2-1-u1-X16"}],"explanation":["좋아하는 것과 잘하는 것은 다를 수 있어요.","노래를 좋아해도 잘하는 것은 달리기일 수 있어요.","항목을 나누어 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#5','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C7',3,'ox','auto','좋아하는 것과 잘하는 것은 다를 수 있어요.',ARRAY['K2-1-u1-X10']::text[],false,'{"seq":5,"concept":"K2-1-u1-C7","difficulty":3,"kind":"ox","stem":"좋아하는 것과 잘하는 것은 다를 수 있어요.","answer":"O","reason_options":[{"t":"좋아해도 아직 잘 못할 수 있고, 잘해도 덜 좋아할 수 있으니까","correct":true},{"t":"좋아하면 언제나 잘하게 되니까","mis":"K2-1-u1-X10"}],"mis":"K2-1-u1-X10","explanation":["좋아하는 것과 잘하는 것은 서로 다른 항목이에요.","둘이 같을 때도 있지만 다를 때도 있어요.","그래서 따로 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#6','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C7',3,'mc','auto','새 짝에게 나를 소개하려고 해요. 빼는 것이 좋은 내용은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],false,'{"seq":6,"concept":"K2-1-u1-C7","difficulty":3,"kind":"mc","stem":"새 짝에게 나를 소개하려고 해요. 빼는 것이 좋은 내용은 어느 것인가요?","options":[{"t":"우리 집 현관 비밀번호","correct":true},{"t":"좋아하는 놀이","mis":"K2-1-u1-X16"},{"t":"잘하는 운동","mis":"K2-1-u1-X16"}],"explanation":["비밀번호는 남에게 알리면 안 되는 개인 정보예요.","좋아하는 놀이와 잘하는 운동은 소개에 넣어요.","묻는 말 「빼는 것」을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#7','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C7',3,'mc','auto','「저는 책 읽기를 좋아합니다.」 뒤에 이어 쓰기 가장 알맞은 문장은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":7,"concept":"K2-1-u1-C7","difficulty":3,"kind":"mc","stem":"「저는 책 읽기를 좋아합니다.」 뒤에 이어 쓰기 가장 알맞은 문장은 어느 것인가요?","options":[{"t":"특히 공룡이 나오는 책을 좋아합니다.","correct":true},{"t":"어제는 늦잠을 잤습니다.","mis":"K2-1-u1-X06"},{"t":"제 동생은 우유를 싫어합니다.","mis":"K2-1-u1-X06"}],"explanation":["좋아하는 책을 더 자세히 알려 주는 문장이에요.","늦잠이나 동생 이야기는 앞 문장과 이어지지 않아요.","앞 문장의 내용을 더 자세히 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#8','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C7',4,'mc','auto','두 친구가 소개할 내용을 정리했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#9','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C7',4,'essay','teacher','나를 소개할 내용을 이름·좋아하는 것·잘하는 것·꿈으로 정리해 쓰고, 그중 하나에 까닭을 더해 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u1-C7","difficulty":4,"kind":"essay","stem":"나를 소개할 내용을 이름·좋아하는 것·잘하는 것·꿈으로 정리해 쓰고, 그중 하나에 까닭을 더해 보세요.","answer_guide":{"answer":"예: 이름 — 김하늘 / 좋아하는 것 — 별 보기(밤하늘이 반짝여서 보고 있으면 마음이 편하기 때문입니다) / 잘하는 것 — 줄넘기 / 꿈 — 천문학자","scoring_points":["네 항목을 알맞게 나누어 썼는가","나를 알려 주는 내용을 골랐는가","까닭을 하나 더했는가"]},"explanation":["네 항목.","나를 알려 주는 내용.","까닭 더하기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#10','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C7',4,'essay','teacher','처음 만난 친구가 나에 대해 가장 궁금해할 것 같은 내용 두 가지와 그렇게 생각한 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u1-C7","difficulty":4,"kind":"essay","stem":"처음 만난 친구가 나에 대해 가장 궁금해할 것 같은 내용 두 가지와 그렇게 생각한 까닭을 써 보세요.","answer_guide":{"answer":"예: 좋아하는 놀이와 잘하는 운동이 궁금할 것 같습니다. 같이 놀 수 있는지 알고 싶을 것이기 때문입니다.","scoring_points":["궁금해할 내용 두 가지를 썼는가","나를 알려 주는 내용인가","그렇게 생각한 까닭을 썼는가"]},"explanation":["두 가지.","나를 알려 주는 내용.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_basic#1','kor',2,1,'u1','L09','g2_1_kor_u1_L09_basic','lesson_basic','K2-1-u1-C8',1,'mc','auto','나를 소개하는 글의 첫 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06','K2-1-u1-X07']::text[],true,'{"seq":1,"concept":"K2-1-u1-C8","difficulty":1,"kind":"mc","stem":"나를 소개하는 글의 첫 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"저는 이하준입니다.","correct":true},{"t":"오늘은 날씨가 맑습니다.","mis":"K2-1-u1-X06"},{"t":"제가 잘하는 것은 줄넘기입니다.","mis":"K2-1-u1-X07"}],"explanation":["소개하는 글은 「저는 ○○○입니다.」로 시작해요.","그래야 누구의 글인지 바로 알 수 있어요.","잘하는 것은 이름 다음에 이어 써요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나를 소개하는 글의 첫 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"저는 박서아입니다.","correct":true},{"t":"어제 학교에 일찍 왔습니다.","mis":"K2-1-u1-X06"},{"t":"제 꿈은 화가입니다.","mis":"K2-1-u1-X07"}],"explanation":["첫 문장에는 내 이름을 써요.","누구의 글인지 바로 알 수 있어요.","꿈은 뒤에 이어 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_basic#2','kor',2,1,'u1','L09','g2_1_kor_u1_L09_basic','lesson_basic','K2-1-u1-C8',1,'blank','auto','빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_basic#3','kor',2,1,'u1','L09','g2_1_kor_u1_L09_basic','lesson_basic','K2-1-u1-C8',1,'ox','auto','소개하는 글은 한 문장에 한 가지 내용만 담으면 읽기 쉬워요.',ARRAY['K2-1-u1-X09']::text[],true,'{"seq":3,"concept":"K2-1-u1-C8","difficulty":1,"kind":"ox","stem":"소개하는 글은 한 문장에 한 가지 내용만 담으면 읽기 쉬워요.","answer":"O","reason_options":[{"t":"내용이 섞이지 않아 알아보기 쉬우니까","correct":true},{"t":"한 문장에 모두 넣어야 짧아지니까","mis":"K2-1-u1-X09"}],"mis":"K2-1-u1-X09","explanation":["한 문장에 한 가지 내용을 담아요.","내용이 섞이지 않아 읽기 쉬워요.","좋아하는 것, 잘하는 것, 꿈을 문장마다 나누어 써요."],"variant_rule":{"alt":[{"stem":"「저는 서아이고 그림을 좋아하고 수영을 잘하고 꿈은 화가입니다.」처럼 한 문장에 모두 쓰는 것이 좋아요.","answer":"X","reason_options":[{"t":"한 문장에 한 가지씩 나누어 써야 읽기 쉬우니까","correct":true},{"t":"문장 수가 적을수록 좋은 글이니까","mis":"K2-1-u1-X09"}],"explanation":["한 문장에 여러 내용을 몰아 쓰면 읽기 어려워요.","「그리고」가 나오는 곳에서 문장을 나누어요.","한 문장에 한 가지 내용을 담아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_basic#4','kor',2,1,'u1','L09','g2_1_kor_u1_L09_basic','lesson_basic','K2-1-u1-C10',1,'mc','auto','소개하는 글을 발표할 때 바른 모습은 어느 것인가요?',ARRAY['K2-1-u1-X15']::text[],true,'{"seq":4,"concept":"K2-1-u1-C10","difficulty":1,"kind":"mc","stem":"소개하는 글을 발표할 때 바른 모습은 어느 것인가요?","options":[{"t":"친구들을 바라보며 또박또박 말해요","correct":true},{"t":"종이만 보며 작은 목소리로 읽어요","mis":"K2-1-u1-X15"},{"t":"빨리 끝내려고 서둘러 말해요","mis":"K2-1-u1-X15"}],"explanation":["듣는 친구들을 바라보며 말해요.","알맞은 빠르기와 크기로 또박또박 말해요.","작게, 빨리 말하면 친구들이 알아듣기 어려워요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 소개하는 글을 발표할 때 바른 모습은 어느 것인가요?","options":[{"t":"바른 자세로 서서 알맞은 크기로 말해요","correct":true},{"t":"몸을 흔들며 혼잣말처럼 말해요","mis":"K2-1-u1-X15"},{"t":"고개를 숙이고 웅얼거려요","mis":"K2-1-u1-X15"}],"explanation":["바른 자세로 서서 말해요.","맨 뒤 친구에게도 들리게 알맞은 크기로 말해요.","고개를 들고 친구들을 바라봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_basic#5','kor',2,1,'u1','L09','g2_1_kor_u1_L09_basic','lesson_basic','K2-1-u1-C8',2,'mc','auto','나를 소개하는 글에 어울리는 문장은 어느 것인가요?',ARRAY['K2-1-u1-X06','K2-1-u1-X08']::text[],true,'{"seq":5,"concept":"K2-1-u1-C8","difficulty":2,"kind":"mc","stem":"나를 소개하는 글에 어울리는 문장은 어느 것인가요?","options":[{"t":"제가 좋아하는 것은 수영입니다.","correct":true},{"t":"오늘 급식은 카레였습니다.","mis":"K2-1-u1-X06"},{"t":"수영. 달리기.","mis":"K2-1-u1-X08"}],"explanation":["좋아하는 것을 문장으로 썼어요.","급식 이야기는 나를 알려 주지 않아요.","낱말만 늘어놓으면 문장이 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나를 소개하는 글에 어울리는 문장은 어느 것인가요?","options":[{"t":"제 꿈은 소방관입니다.","correct":true},{"t":"어제는 비가 많이 왔습니다.","mis":"K2-1-u1-X06"},{"t":"소방관. 불.","mis":"K2-1-u1-X08"}],"explanation":["꿈을 문장으로 썼어요.","날씨는 나를 알려 주지 않아요.","낱말만 늘어놓으면 문장이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_basic#6','kor',2,1,'u1','L09','g2_1_kor_u1_L09_basic','lesson_basic','K2-1-u1-C8',2,'mc','auto','소개하는 글을 쓰고 다시 읽으며 확인할 것이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],true,'{"seq":6,"concept":"K2-1-u1-C8","difficulty":2,"kind":"mc","stem":"소개하는 글을 쓰고 다시 읽으며 확인할 것이 아닌 것은 어느 것인가요?","options":[{"t":"친구 글보다 내 글이 더 긴가요?","correct":true},{"t":"내 이름으로 시작했나요?","mis":"K2-1-u1-X16"},{"t":"한 문장에 한 가지 내용을 담았나요?","mis":"K2-1-u1-X16"}],"explanation":["이름으로 시작했는지, 한 문장에 한 가지를 담았는지 확인해요.","글의 길이를 친구와 견줄 필요는 없어요.","묻는 말 「아닌 것」을 확인해요."],"variant_rule":{"alt":[{"stem":"소개하는 글을 쓰고 다시 읽으며 확인할 것은 어느 것인가요?","options":[{"t":"나를 알려 주지 않는 문장이 섞이지 않았나요?","correct":true},{"t":"글씨를 다른 색으로 썼나요?","mis":"K2-1-u1-X16"},{"t":"친구 글보다 더 긴가요?","mis":"K2-1-u1-X16"}],"explanation":["나와 관계없는 문장이 있으면 빼요.","글씨 색이나 길이는 확인할 점이 아니에요.","이름·내용·문장을 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_basic#7','kor',2,1,'u1','L09','g2_1_kor_u1_L09_basic','lesson_basic','K2-1-u1-C8',2,'mc','auto','문장의 끝을 바르게 맺어 쓴 것은 어느 것인가요?',ARRAY['K2-1-u1-X08']::text[],true,'{"seq":7,"concept":"K2-1-u1-C8","difficulty":2,"kind":"mc","stem":"문장의 끝을 바르게 맺어 쓴 것은 어느 것인가요?","options":[{"t":"저는 강아지를 좋아합니다.","correct":true},{"t":"저는 강아지를 좋아합니다","mis":"K2-1-u1-X08"},{"t":"저는, 강아지를, 좋아합니다","mis":"K2-1-u1-X08"}],"explanation":["문장이 끝나면 끝에 마침표(.)를 찍어요.","마침표가 없으면 문장이 끝났는지 알기 어려워요.","쉼표를 낱말마다 찍지 않아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 문장의 끝을 바르게 맺어 쓴 것은 어느 것인가요?","options":[{"t":"제 꿈은 경찰관입니다.","correct":true},{"t":"제 꿈은 경찰관입니다","mis":"K2-1-u1-X08"},{"t":"제 꿈은, 경찰관","mis":"K2-1-u1-X08"}],"explanation":["문장이 끝나면 마침표(.)를 찍어요.","「제 꿈은, 경찰관」은 문장이 끝나지 않았어요.","문장을 끝까지 쓰고 마침표를 찍어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_basic#8','kor',2,1,'u1','L09','g2_1_kor_u1_L09_basic','lesson_basic','K2-1-u1-C8',2,'match','auto','소개하는 글의 문장과 담긴 내용을 이어 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u1-C8","difficulty":2,"kind":"match","stem":"소개하는 글의 문장과 담긴 내용을 이어 보세요.","pairs":[{"l":"저는 오지안입니다.","r":"이름"},{"l":"저는 별 보기를 좋아합니다.","r":"좋아하는 것"},{"l":"제 꿈은 천문학자입니다.","r":"꿈"}],"mis":"K2-1-u1-X10","explanation":["「저는 ○○○입니다」는 이름이에요.","「~을 좋아합니다」는 좋아하는 것이에요.","「제 꿈은 ~입니다」는 꿈이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 소개하는 글의 문장과 담긴 내용을 이어 보세요.","pairs":[{"l":"저는 문태민입니다.","r":"이름"},{"l":"제가 잘하는 것은 축구입니다.","r":"잘하는 것"},{"l":"제 꿈은 축구 선수입니다.","r":"꿈"}],"explanation":["「저는 ○○○입니다」는 이름이에요.","「제가 잘하는 것은 ~입니다」는 잘하는 것이에요.","「제 꿈은 ~입니다」는 꿈이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_basic#9','kor',2,1,'u1','L09','g2_1_kor_u1_L09_basic','lesson_basic','K2-1-u1-C10',2,'ox','auto','친구의 소개 발표가 끝나면 박수를 치고, 궁금한 것은 손을 들고 물어요.',ARRAY['K2-1-u1-X02']::text[],true,'{"seq":9,"concept":"K2-1-u1-C10","difficulty":2,"kind":"ox","stem":"친구의 소개 발표가 끝나면 박수를 치고, 궁금한 것은 손을 들고 물어요.","answer":"O","reason_options":[{"t":"끝까지 듣고 고마움과 관심을 전하는 것이니까","correct":true},{"t":"궁금하면 발표 중에 바로 물어야 하니까","mis":"K2-1-u1-X02"}],"mis":"K2-1-u1-X02","explanation":["발표가 끝난 뒤 박수로 고마움을 전해요.","궁금한 것은 손을 들고 물어요.","발표 중에 끼어들어 묻지 않아요."],"variant_rule":{"alt":[{"stem":"발표를 들을 때 궁금한 점이 생기면 발표 중간에 바로 물어봐요.","answer":"X","reason_options":[{"t":"발표가 끝난 뒤 손을 들고 물어야 하니까","correct":true},{"t":"궁금할 때 바로 물어야 잊지 않으니까","mis":"K2-1-u1-X02"}],"explanation":["발표 중에 물으면 발표가 끊겨요.","끝난 뒤 손을 들고 물어요.","잊을까 걱정되면 짧게 적어 두어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_basic#10','kor',2,1,'u1','L09','g2_1_kor_u1_L09_basic','lesson_basic','K2-1-u1-C8',3,'error','auto','친구들이 하람이가 쓴 소개 글을 읽고 말했어요. 잘못 말한 친구는 누구인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#1','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C8',2,'mc','auto','소개하는 글을 「저는 ○○○입니다.」로 시작하는 까닭은 무엇인가요?',ARRAY['K2-1-u1-X07']::text[],false,'{"seq":1,"concept":"K2-1-u1-C8","difficulty":2,"kind":"mc","stem":"소개하는 글을 「저는 ○○○입니다.」로 시작하는 까닭은 무엇인가요?","options":[{"t":"읽는 사람이 누구의 글인지 바로 알 수 있어서","correct":true},{"t":"글이 더 길어 보여서","mis":"K2-1-u1-X07"},{"t":"이름을 쓰면 글씨 연습이 되어서","mis":"K2-1-u1-X07"}],"explanation":["첫 문장에 이름을 쓰면 누구의 글인지 바로 알아요.","길어 보이게 하거나 글씨 연습을 하려는 것이 아니에요.","읽는 사람을 생각해 이름부터 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#2','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C10',2,'mc','auto','소개하는 글을 발표하기 전에 하면 좋은 것은 무엇인가요?',ARRAY['K2-1-u1-X15']::text[],false,'{"seq":2,"concept":"K2-1-u1-C10","difficulty":2,"kind":"mc","stem":"소개하는 글을 발표하기 전에 하면 좋은 것은 무엇인가요?","options":[{"t":"쓴 글을 소리 내어 읽으며 연습해요","correct":true},{"t":"연습 없이 바로 발표해요","mis":"K2-1-u1-X15"},{"t":"글을 다 외우지 못하면 발표하지 않아요","mis":"K2-1-u1-X15"}],"explanation":["소리 내어 읽어 보면 어디서 쉴지, 어떻게 말할지 알 수 있어요.","다 외우지 못해도 글을 보며 발표할 수 있어요.","연습하면 또박또박 말하기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#3','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C8',3,'mc','auto','서윤이가 쓴 소개 글을 보고 답해 보세요. 다듬을 때 빼야 할 문장은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],false,'{"seq":3,"concept":"K2-1-u1-C8","difficulty":3,"kind":"mc","stem":"서윤이가 쓴 소개 글을 보고 답해 보세요. 다듬을 때 빼야 할 문장은 어느 것인가요?","options":[{"t":"어제는 엄마와 마트에 갔습니다.","correct":true},{"t":"저는 문서윤입니다.","mis":"K2-1-u1-X16"},{"t":"제 꿈은 수의사입니다.","mis":"K2-1-u1-X16"}],"explanation":["마트에 간 일은 서윤이를 알려 주는 내용이 아니에요.","이름과 꿈은 소개하는 글에 꼭 맞는 문장이에요.","다시 읽으며 관계없는 문장을 빼요."],"asset":{"type":"passage","lines":["저는 문서윤입니다.","저는 고양이를 좋아합니다.","어제는 엄마와 마트에 갔습니다.","제 꿈은 수의사입니다."],"title":"서윤이가 쓴 소개 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#4','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C8',3,'mc','auto','서윤이가 쓴 소개 글을 보고 답해 보세요. 「저는 고양이를 좋아합니다.」에 까닭을 더해 다듬은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06','K2-1-u1-X08']::text[],false,'{"seq":4,"concept":"K2-1-u1-C8","difficulty":3,"kind":"mc","stem":"서윤이가 쓴 소개 글을 보고 답해 보세요. 「저는 고양이를 좋아합니다.」에 까닭을 더해 다듬은 것은 어느 것인가요?","options":[{"t":"저는 고양이를 좋아합니다. 부드러운 털을 쓰다듬으면 기분이 좋기 때문입니다.","correct":true},{"t":"저는 고양이를 좋아합니다. 마트는 크기 때문입니다.","mis":"K2-1-u1-X06"},{"t":"저는 고양이 좋아","mis":"K2-1-u1-X08"}],"explanation":["고양이를 좋아하는 까닭을 더했어요.","마트가 크다는 것은 까닭이 아니에요.","문장을 끝까지 쓰고 마침표를 찍어요."],"asset":{"type":"passage","lines":["저는 문서윤입니다.","저는 고양이를 좋아합니다.","어제는 엄마와 마트에 갔습니다.","제 꿈은 수의사입니다."],"title":"서윤이가 쓴 소개 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#5','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C8',3,'ox','auto','「저는 강아지를 좋아합니다」처럼 마침표를 찍지 않아도 문장이 끝난 것을 알 수 있으니 괜찮아요.',ARRAY['K2-1-u1-X08']::text[],false,'{"seq":5,"concept":"K2-1-u1-C8","difficulty":3,"kind":"ox","stem":"「저는 강아지를 좋아합니다」처럼 마침표를 찍지 않아도 문장이 끝난 것을 알 수 있으니 괜찮아요.","answer":"X","reason_options":[{"t":"문장이 끝나면 마침표(.)를 찍어야 하니까","correct":true},{"t":"소리 내어 읽으면 다 알 수 있으니까","mis":"K2-1-u1-X08"}],"mis":"K2-1-u1-X08","explanation":["글로 쓸 때는 문장이 끝나면 마침표를 찍어요.","마침표가 있어야 읽는 사람이 문장의 끝을 알아요.","다 쓴 뒤 문장 끝을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#6','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C10',3,'error','auto','친구들이 소개 글 발표에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X15','K2-1-u1-X16']::text[],false,'{"seq":6,"concept":"K2-1-u1-C10","difficulty":3,"kind":"error","stem":"친구들이 소개 글 발표에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"로아 — 부끄러우면 종이로 얼굴을 가리고 작게 읽어요","correct":true,"mis_target":"K2-1-u1-X15"},{"t":"지호 — 듣는 친구들을 바라보며 말해요","mis":"K2-1-u1-X16"},{"t":"서아 — 끝까지 또박또박 말해요","mis":"K2-1-u1-X16"}],"explanation":["얼굴을 가리고 작게 읽으면 친구들이 알아듣기 어려워요.","부끄러워도 고개를 들고 또박또박 말해요.","지호와 서아는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#7','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C8',3,'mc','auto','「달리기. 잘함. 꿈 체육 선생님.」을 소개하는 글의 문장으로 바르게 고친 것은 어느 것인가요?',ARRAY['K2-1-u1-X08','K2-1-u1-X09']::text[],false,'{"seq":7,"concept":"K2-1-u1-C8","difficulty":3,"kind":"mc","stem":"「달리기. 잘함. 꿈 체육 선생님.」을 소개하는 글의 문장으로 바르게 고친 것은 어느 것인가요?","options":[{"t":"제가 잘하는 것은 달리기입니다. 제 꿈은 체육 선생님입니다.","correct":true},{"t":"달리기, 잘함, 꿈은 체육 선생님.","mis":"K2-1-u1-X08"},{"t":"저는 달리기를 잘하고 꿈은 체육 선생님이고 축구도 좋아합니다","mis":"K2-1-u1-X09"}],"explanation":["낱말을 이어 문장으로 썼어요.","한 문장에 한 가지 내용을 담고 마침표를 찍었어요.","낱말만 늘어놓거나 한 문장에 몰아 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#8','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C8',4,'mc','auto','두 친구가 쓴 소개 글이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#9','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C8',4,'essay','teacher','「저는 ○○○입니다.」로 시작해 나를 소개하는 글을 네 문장으로 써 보세요. 한 문장에는 한 가지 내용만 담아요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u1-C8","difficulty":4,"kind":"essay","stem":"「저는 ○○○입니다.」로 시작해 나를 소개하는 글을 네 문장으로 써 보세요. 한 문장에는 한 가지 내용만 담아요.","answer_guide":{"answer":"예: 저는 김하늘입니다. / 저는 별 보기를 좋아합니다. / 제가 잘하는 것은 줄넘기입니다. / 제 꿈은 천문학자입니다.","scoring_points":["이름으로 시작했는가","한 문장에 한 가지 내용을 담았는가","나를 알려 주는 내용을 문장으로 쓰고 마침표를 찍었는가"]},"explanation":["이름으로 시작.","한 문장에 한 가지.","문장과 마침표."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#10','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C10',4,'essay','teacher','소개하는 글을 발표할 때 지킬 점 두 가지와, 친구 발표를 들을 때 지킬 점 한 가지를 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u1-C10","difficulty":4,"kind":"essay","stem":"소개하는 글을 발표할 때 지킬 점 두 가지와, 친구 발표를 들을 때 지킬 점 한 가지를 써 보세요.","answer_guide":{"answer":"예: 발표할 때 — 친구들을 바라보며 말합니다. / 또박또박 알맞은 크기로 말합니다. 들을 때 — 끝까지 듣고 궁금한 것은 손을 들고 묻습니다.","scoring_points":["발표할 때 지킬 점 두 가지를 썼는가","들을 때 지킬 점 한 가지를 썼는가","바라보기·또박또박·끝까지 듣기 같은 실천할 수 있는 말로 썼는가"]},"explanation":["발표 두 가지.","듣기 한 가지.","실천할 수 있게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_basic#1','kor',2,1,'u1','L11','g2_1_kor_u1_L11_basic','lesson_basic','K2-1-u1-C9',1,'mc','auto','주변 사람을 소개하는 첫 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X14','K2-1-u1-X07']::text[],true,'{"seq":1,"concept":"K2-1-u1-C9","difficulty":1,"kind":"mc","stem":"주변 사람을 소개하는 첫 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"제 친구 도윤이를 소개합니다.","correct":true},{"t":"도윤이는 어제 늦잠을 잤습니다.","mis":"K2-1-u1-X14"},{"t":"그 친구는 우리 반에 있습니다.","mis":"K2-1-u1-X07"}],"explanation":["「제 ○○ ○○○를 소개합니다.」로 누구를 소개하는지 밝혀요.","늦잠 이야기는 흉이 될 수 있어요.","「그 친구」라고만 하면 누구인지 알 수 없어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 주변 사람을 소개하는 첫 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"제 동생 지우를 소개합니다.","correct":true},{"t":"지우는 자주 웁니다.","mis":"K2-1-u1-X14"},{"t":"그 아이는 우리 집에 삽니다.","mis":"K2-1-u1-X07"}],"explanation":["누구를 소개하는지 첫 문장에서 밝혀요.","자주 운다는 말은 흉이 될 수 있어요.","「그 아이」라고만 하면 누구인지 알 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_basic#2','kor',2,1,'u1','L11','g2_1_kor_u1_L11_basic','lesson_basic','K2-1-u1-C9',1,'mc','auto','주변 사람 소개에 넣으면 좋은 내용은 어느 것인가요?',ARRAY['K2-1-u1-X14']::text[],true,'{"seq":2,"concept":"K2-1-u1-C9","difficulty":1,"kind":"mc","stem":"주변 사람 소개에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"그 사람이 잘하는 것","correct":true},{"t":"그 사람의 전화번호","mis":"K2-1-u1-X14"},{"t":"그 사람 집 비밀번호","mis":"K2-1-u1-X14"}],"explanation":["잘하는 것은 그 사람을 잘 보여 줘요.","전화번호나 비밀번호는 알리면 안 되는 개인 정보예요.","좋은 점, 잘하는 것, 함께한 일을 넣어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 주변 사람 소개에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"그 사람의 좋은 점","correct":true},{"t":"그 사람의 집 주소","mis":"K2-1-u1-X14"},{"t":"그 사람이 실수한 일","mis":"K2-1-u1-X14"}],"explanation":["좋은 점은 그 사람을 따뜻하게 알려 줘요.","주소는 개인 정보, 실수한 일은 흉이 될 수 있어요.","존중하는 마음으로 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_basic#3','kor',2,1,'u1','L11','g2_1_kor_u1_L11_basic','lesson_basic','K2-1-u1-C9',1,'ox','auto','주변 사람을 소개할 때는 아끼고 존중하는 마음으로 좋은 점을 전해요.',ARRAY['K2-1-u1-X14']::text[],true,'{"seq":3,"concept":"K2-1-u1-C9","difficulty":1,"kind":"ox","stem":"주변 사람을 소개할 때는 아끼고 존중하는 마음으로 좋은 점을 전해요.","answer":"O","reason_options":[{"t":"좋은 점을 따뜻하게 전하면 소개받는 사람도 듣는 사람도 기분이 좋으니까","correct":true},{"t":"재미있게 하려면 흉을 보아도 되니까","mis":"K2-1-u1-X14"}],"mis":"K2-1-u1-X14","explanation":["소개하는 사람을 아끼는 마음으로 소개해요.","좋은 점을 따뜻하게 전해요.","흉을 보면 그 사람이 속상해요."],"variant_rule":{"alt":[{"stem":"친구를 소개할 때 친구가 부끄러워하는 일을 재미로 말해도 돼요.","answer":"X","reason_options":[{"t":"소개하는 사람을 존중해야 하니까","correct":true},{"t":"모두 웃으면 좋은 소개니까","mis":"K2-1-u1-X14"}],"explanation":["부끄러워하는 일을 말하면 친구가 속상해요.","소개는 그 사람을 존중하는 마음으로 해요.","좋은 점을 골라 전해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_basic#4','kor',2,1,'u1','L11','g2_1_kor_u1_L11_basic','lesson_basic','K2-1-u1-C9',1,'mc','auto','주변 사람을 잘 소개한 것은 어느 것인가요?',ARRAY['K2-1-u1-X07','K2-1-u1-X14']::text[],true,'{"seq":4,"concept":"K2-1-u1-C9","difficulty":1,"kind":"mc","stem":"주변 사람을 잘 소개한 것은 어느 것인가요?","options":[{"t":"제 짝 소율이는 노래를 잘 부릅니다.","correct":true},{"t":"그 사람은 그냥 옆 반에 있습니다.","mis":"K2-1-u1-X07"},{"t":"우리 형은 방을 안 치웁니다.","mis":"K2-1-u1-X14"}],"explanation":["누구인지 밝히고 잘하는 것을 소개했어요.","「그 사람」만으로는 누구인지 알 수 없어요.","방을 안 치운다는 말은 흉이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 주변 사람을 잘 소개한 것은 어느 것인가요?","options":[{"t":"저희 할머니께서는 맛있는 떡을 잘 만드십니다.","correct":true},{"t":"그분은 그냥 우리 동네에 사십니다.","mis":"K2-1-u1-X07"},{"t":"저희 할머니께서는 자주 깜빡하십니다.","mis":"K2-1-u1-X14"}],"explanation":["누구인지 밝히고 잘하시는 것을 소개했어요.","「그분」만으로는 누구인지 알 수 없어요.","깜빡하신다는 말은 흉이 될 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_basic#5','kor',2,1,'u1','L11','g2_1_kor_u1_L11_basic','lesson_basic','K2-1-u1-C10',2,'mc','auto','친구가 「제 친구 하린이는 종이접기를 잘합니다.」 하고 소개했어요. 소개를 듣고 할 질문으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X04','K2-1-u1-X13']::text[],true,'{"seq":5,"concept":"K2-1-u1-C10","difficulty":2,"kind":"mc","stem":"친구가 「제 친구 하린이는 종이접기를 잘합니다.」 하고 소개했어요. 소개를 듣고 할 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"「하린이는 무엇을 가장 잘 접나요?」","correct":true},{"t":"「너 어제 뭐 먹었어?」","mis":"K2-1-u1-X04"},{"t":"「종이접기는 재미없어.」","mis":"K2-1-u1-X13"}],"explanation":["소개한 내용과 관련 있는 것을 물어요.","관계없는 질문이나 깎아내리는 말은 하지 않아요.","손을 들고 정중하게 물어요."],"variant_rule":{"alt":[{"stem":"친구가 「저희 형은 축구를 잘합니다.」 하고 소개했어요. 소개를 듣고 할 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"「형은 축구를 언제부터 했나요?」","correct":true},{"t":"「오늘 급식 뭐야?」","mis":"K2-1-u1-X04"},{"t":"「축구 잘하는 게 뭐가 대단해?」","mis":"K2-1-u1-X13"}],"explanation":["소개한 내용과 관련 있는 것을 물어요.","관계없는 질문이나 깎아내리는 말은 하지 않아요.","손을 들고 정중하게 물어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_basic#6','kor',2,1,'u1','L11','g2_1_kor_u1_L11_basic','lesson_basic','K2-1-u1-C9',2,'mc','auto','친구 소개를 읽고 답해 보세요. 민호의 좋은 점으로 소개한 것은 무엇인가요?',ARRAY['K2-1-u1-X11']::text[],true,'{"seq":6,"concept":"K2-1-u1-C9","difficulty":2,"kind":"mc","stem":"친구 소개를 읽고 답해 보세요. 민호의 좋은 점으로 소개한 것은 무엇인가요?","options":[{"t":"넘어진 친구를 먼저 일으켜 줘요","correct":true},{"t":"그림을 잘 그려요","mis":"K2-1-u1-X11"},{"t":"노래를 잘 불러요","mis":"K2-1-u1-X11"}],"explanation":["「친구가 넘어지면 먼저 달려가 일으켜 줍니다.」라고 했어요.","그림이나 노래는 글에 나오지 않아요.","글에서 찾아 답해요."],"asset":{"type":"passage","lines":["제 친구 민호를 소개합니다.","민호는 달리기를 잘합니다.","민호는 친구가 넘어지면 먼저 달려가 일으켜 줍니다."],"title":"우리 반 친구 소개"},"variant_rule":{"alt":[{"stem":"친구 소개를 읽고 답해 보세요. 민호가 잘하는 것은 무엇인가요?","options":[{"t":"달리기","correct":true},{"t":"그림 그리기","mis":"K2-1-u1-X11"},{"t":"종이접기","mis":"K2-1-u1-X11"}],"explanation":["「민호는 달리기를 잘합니다.」라고 했어요.","그림 그리기나 종이접기는 글에 나오지 않아요.","글에서 찾아 답해요."],"asset":{"type":"passage","lines":["제 친구 민호를 소개합니다.","민호는 달리기를 잘합니다.","민호는 친구가 넘어지면 먼저 달려가 일으켜 줍니다."],"title":"우리 반 친구 소개"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_basic#7','kor',2,1,'u1','L11','g2_1_kor_u1_L11_basic','lesson_basic','K2-1-u1-C9',2,'match','auto','소개할 사람과 어울리는 소개 문장을 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"K2-1-u1-C9","difficulty":2,"kind":"match","stem":"소개할 사람과 어울리는 소개 문장을 이어 보세요.","pairs":[{"l":"우리 선생님","r":"저희 선생님께서는 재미있는 이야기를 잘 들려주십니다."},{"l":"내 짝","r":"제 짝 예린이는 웃는 모습이 환합니다."},{"l":"우리 할아버지","r":"저희 할아버지께서는 텃밭에서 채소를 잘 기르십니다."}],"mis":"K2-1-u1-X07","explanation":["누구를 소개하는지 문장 앞에 밝혀요.","선생님, 짝, 할아버지에 맞게 이어요.","어른을 소개할 때는 「-께서는, -십니다」처럼 높여 말해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 소개할 사람과 어울리는 소개 문장을 이어 보세요.","pairs":[{"l":"우리 언니","r":"저희 언니는 피아노를 잘 칩니다."},{"l":"옆집 아기","r":"옆집 아기 하늘이는 잘 웃습니다."},{"l":"우리 반 친구","r":"우리 반 시우는 친구를 잘 도와줍니다."}],"explanation":["누구를 소개하는지 문장 앞에 밝혀요.","언니, 옆집 아기, 우리 반 친구에 맞게 이어요.","좋은 점을 따뜻하게 전해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_basic#8','kor',2,1,'u1','L11','g2_1_kor_u1_L11_basic','lesson_basic','K2-1-u1-C9',2,'mc','auto','주변 사람을 소개할 때 따뜻한 소개말은 어느 것인가요?',ARRAY['K2-1-u1-X14']::text[],true,'{"seq":8,"concept":"K2-1-u1-C9","difficulty":2,"kind":"mc","stem":"주변 사람을 소개할 때 따뜻한 소개말은 어느 것인가요?","options":[{"t":"친구를 잘 도와줍니다.","correct":true},{"t":"자주 늦잠을 잡니다.","mis":"K2-1-u1-X14"},{"t":"밥을 늦게 먹습니다.","mis":"K2-1-u1-X14"}],"explanation":["친구를 잘 도와준다는 것은 좋은 점이에요.","늦잠이나 늦게 먹는 것은 흉이 될 수 있어요.","듣는 사람이 기분 좋은 말을 골라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 주변 사람을 소개할 때 따뜻한 소개말은 어느 것인가요?","options":[{"t":"웃는 모습이 환합니다.","correct":true},{"t":"숙제를 자주 잊습니다.","mis":"K2-1-u1-X14"},{"t":"목소리가 너무 큽니다.","mis":"K2-1-u1-X14"}],"explanation":["웃는 모습이 환하다는 것은 좋은 점이에요.","숙제를 잊거나 목소리가 크다는 것은 흉이 될 수 있어요.","좋은 점을 골라 전해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_basic#9','kor',2,1,'u1','L11','g2_1_kor_u1_L11_basic','lesson_basic','K2-1-u1-C10',2,'ox','auto','친구가 주변 사람을 소개할 때는 말하는 친구를 바라보며 끝까지 들어요.',ARRAY['K2-1-u1-X01']::text[],true,'{"seq":9,"concept":"K2-1-u1-C10","difficulty":2,"kind":"ox","stem":"친구가 주변 사람을 소개할 때는 말하는 친구를 바라보며 끝까지 들어요.","answer":"O","reason_options":[{"t":"잘 들어야 소개한 사람을 알 수 있으니까","correct":true},{"t":"내 차례 준비만 하면 되니까","mis":"K2-1-u1-X01"}],"mis":"K2-1-u1-X01","explanation":["친구를 바라보며 끝까지 들어요.","내 차례 준비만 하면 친구 소개를 놓쳐요.","들은 뒤 박수로 반응해요."],"variant_rule":{"alt":[{"stem":"친구 소개가 끝나면 박수를 쳐 고마움을 전해요.","answer":"O","reason_options":[{"t":"끝까지 들었다는 마음을 전하는 것이니까","correct":true},{"t":"박수는 상을 받을 때만 치니까","mis":"K2-1-u1-X01"}],"explanation":["박수는 「잘 들었어요.」라는 마음이에요.","소개한 친구의 용기에 고마움을 전해요.","궁금한 것은 손을 들고 물어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_basic#10','kor',2,1,'u1','L11','g2_1_kor_u1_L11_basic','lesson_basic','K2-1-u1-C9',3,'error','auto','친구들이 주변 사람을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?',ARRAY['K2-1-u1-X14','K2-1-u1-X16']::text[],true,'{"seq":10,"concept":"K2-1-u1-C9","difficulty":3,"kind":"error","stem":"친구들이 주변 사람을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"준우 — 「제 형의 전화번호는 공일공…입니다.」 하고 전화번호를 말했어요","correct":true,"mis_target":"K2-1-u1-X14"},{"t":"다은 — 「저희 엄마께서는 요리를 잘하십니다.」","mis":"K2-1-u1-X16"},{"t":"태민 — 「제 짝 로아는 책을 많이 읽습니다.」","mis":"K2-1-u1-X16"}],"explanation":["전화번호는 남에게 알리면 안 되는 개인 정보예요.","다은이와 태민이는 잘하는 것을 소개했어요.","개인 정보는 소개에 넣지 않아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 주변 사람을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"하린 — 「제 동생은 아직도 밤에 이불에 실수를 합니다.」","correct":true,"mis_target":"K2-1-u1-X14"},{"t":"지호 — 「제 동생은 블록 쌓기를 잘합니다.」","mis":"K2-1-u1-X16"},{"t":"서아 — 「저희 아빠께서는 노래를 잘 부르십니다.」","mis":"K2-1-u1-X16"}],"explanation":["동생이 부끄러워할 일을 말했어요.","소개는 존중하는 마음으로 좋은 점을 전해요.","지호와 서아는 알맞게 소개했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#1','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C9',2,'mc','auto','주변 사람을 소개할 때 전화번호나 집 주소를 넣지 않는 까닭은 무엇인가요?',ARRAY['K2-1-u1-X14']::text[],false,'{"seq":1,"concept":"K2-1-u1-C9","difficulty":2,"kind":"mc","stem":"주변 사람을 소개할 때 전화번호나 집 주소를 넣지 않는 까닭은 무엇인가요?","options":[{"t":"그 사람이 원하지 않는데 알려지면 위험할 수 있어서","correct":true},{"t":"전화번호는 너무 길어서","mis":"K2-1-u1-X14"},{"t":"주소는 쓰기 어려워서","mis":"K2-1-u1-X14"}],"explanation":["전화번호와 주소는 개인 정보예요.","함부로 알려지면 위험할 수 있어요.","그래서 소개에 넣지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#2','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C10',2,'mc','auto','소개를 들은 뒤 질문할 때 알맞은 모습은 어느 것인가요?',ARRAY['K2-1-u1-X02','K2-1-u1-X04']::text[],false,'{"seq":2,"concept":"K2-1-u1-C10","difficulty":2,"kind":"mc","stem":"소개를 들은 뒤 질문할 때 알맞은 모습은 어느 것인가요?","options":[{"t":"손을 들고, 소개한 내용과 관련 있는 것을 물어요","correct":true},{"t":"발표 중에 끼어들어 물어요","mis":"K2-1-u1-X02"},{"t":"소개와 상관없는 것을 물어요","mis":"K2-1-u1-X04"}],"explanation":["소개가 끝난 뒤 손을 들고 물어요.","소개한 내용과 관련 있는 것을 물어요.","관련 없는 질문은 대화를 끊어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#3','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C9',3,'mc','auto','태민이가 쓴 친구 소개를 보고 답해 보세요. 빼는 것이 좋은 문장은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],false,'{"seq":3,"concept":"K2-1-u1-C9","difficulty":3,"kind":"mc","stem":"태민이가 쓴 친구 소개를 보고 답해 보세요. 빼는 것이 좋은 문장은 어느 것인가요?","options":[{"t":"지안이는 지난번에 받아쓰기를 틀려서 울었습니다.","correct":true},{"t":"지안이는 줄넘기를 잘합니다.","mis":"K2-1-u1-X16"},{"t":"지안이는 친구들에게 늘 먼저 인사를 합니다.","mis":"K2-1-u1-X16"}],"explanation":["받아쓰기를 틀려 운 일은 지안이가 부끄러워할 수 있어요.","줄넘기와 인사는 지안이의 좋은 점이에요.","존중하는 마음으로 골라요."],"asset":{"type":"passage","lines":["제 친구 지안이를 소개합니다.","지안이는 줄넘기를 잘합니다.","지안이는 지난번에 받아쓰기를 틀려서 울었습니다.","지안이는 친구들에게 늘 먼저 인사를 합니다."],"title":"태민이가 쓴 친구 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#4','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C9',3,'mc','auto','태민이가 쓴 친구 소개를 보고 답해 보세요. 더하면 좋은 문장은 어느 것인가요?',ARRAY['K2-1-u1-X14','K2-1-u1-X06']::text[],false,'{"seq":4,"concept":"K2-1-u1-C9","difficulty":3,"kind":"mc","stem":"태민이가 쓴 친구 소개를 보고 답해 보세요. 더하면 좋은 문장은 어느 것인가요?","options":[{"t":"지안이와 저는 쉬는 시간마다 함께 줄넘기를 합니다.","correct":true},{"t":"지안이네 집은 행복아파트 5동입니다.","mis":"K2-1-u1-X14"},{"t":"오늘은 비가 옵니다.","mis":"K2-1-u1-X06"}],"explanation":["함께한 일을 더하면 소개가 생생해져요.","집 주소는 개인 정보예요.","날씨는 지안이를 알려 주지 않아요."],"asset":{"type":"passage","lines":["제 친구 지안이를 소개합니다.","지안이는 줄넘기를 잘합니다.","지안이는 지난번에 받아쓰기를 틀려서 울었습니다.","지안이는 친구들에게 늘 먼저 인사를 합니다."],"title":"태민이가 쓴 친구 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#5','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C9',3,'error','auto','친구들이 주변 사람을 소개하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X14','K2-1-u1-X16']::text[],false,'{"seq":5,"concept":"K2-1-u1-C9","difficulty":3,"kind":"error","stem":"친구들이 주변 사람을 소개하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 재미있게 하려면 그 사람의 흉을 말해도 돼요","correct":true,"mis_target":"K2-1-u1-X14"},{"t":"서윤 — 누구를 소개하는지 처음에 말해요","mis":"K2-1-u1-X16"},{"t":"민호 — 그 사람이 잘하는 것이나 함께한 일을 말해요","mis":"K2-1-u1-X16"}],"explanation":["흉을 말하면 소개받는 사람이 속상해요.","존중하는 마음으로 좋은 점을 전해요.","서윤이와 민호는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#6','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C10',3,'mc','auto','대화를 읽고 답해 보세요. 시우의 대답으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X04']::text[],false,'{"seq":6,"concept":"K2-1-u1-C10","difficulty":3,"kind":"mc","stem":"대화를 읽고 답해 보세요. 시우의 대답으로 알맞은 것은 어느 것인가요?","options":[{"t":"「아린이는 우리 가족 얼굴을 즐겨 그려요.」","correct":true},{"t":"「나는 어제 축구를 했어요.」","mis":"K2-1-u1-X04"},{"t":"「몰라요. 그건 안 알려 줄래요.」","mis":"K2-1-u1-X04"}],"explanation":["다은이는 아린이가 무엇을 그리는지 물었어요.","묻는 말에 맞게 대답해요.","관계없는 말이나 대답하지 않는 말은 대화를 끊어요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"제 동생 아린이를 소개합니다. 아린이는 그림을 잘 그립니다."},{"who":"다은","text":"아린이는 무엇을 즐겨 그려요?"},{"who":"시우","text":"( ? )"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#7','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C9',3,'ox','auto','주변 사람을 소개할 때 내가 그 사람과 함께한 일을 넣으면 소개가 더 생생해져요.',ARRAY['K2-1-u1-X07']::text[],false,'{"seq":7,"concept":"K2-1-u1-C9","difficulty":3,"kind":"ox","stem":"주변 사람을 소개할 때 내가 그 사람과 함께한 일을 넣으면 소개가 더 생생해져요.","answer":"O","reason_options":[{"t":"함께한 일로 그 사람을 더 잘 보여 줄 수 있으니까","correct":true},{"t":"소개에는 이름만 있으면 되니까","mis":"K2-1-u1-X07"}],"mis":"K2-1-u1-X07","explanation":["함께한 일을 넣으면 그 사람이 더 잘 보여요.","이름만으로는 어떤 사람인지 알 수 없어요.","좋은 점과 함께한 일을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#8','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C9',4,'mc','auto','두 친구가 현우를 소개했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#9','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C9',4,'essay','teacher','내 주변 사람 한 명을 골라 「제 ○○ ○○○를 소개합니다.」로 시작해 세 문장으로 소개하는 글을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u1-C9","difficulty":4,"kind":"essay","stem":"내 주변 사람 한 명을 골라 「제 ○○ ○○○를 소개합니다.」로 시작해 세 문장으로 소개하는 글을 써 보세요.","answer_guide":{"answer":"예: 제 짝 이서윤을 소개합니다. / 서윤이는 그림을 잘 그립니다. / 서윤이는 제가 아플 때 보건실에 함께 가 주었습니다.","scoring_points":["누구를 소개하는지 첫 문장에서 밝혔는가","잘하는 것·좋은 점·함께한 일을 담았는가","흉이나 개인 정보 없이 존중하는 마음으로 썼는가"]},"explanation":["누구인지 밝히기.","좋은 점·함께한 일.","존중하는 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#10','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C10',4,'essay','teacher','친구가 주변 사람을 소개했을 때 해 줄 질문 두 가지를 쓰고, 왜 그것이 궁금한지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u1-C10","difficulty":4,"kind":"essay","stem":"친구가 주변 사람을 소개했을 때 해 줄 질문 두 가지를 쓰고, 왜 그것이 궁금한지 써 보세요.","answer_guide":{"answer":"예: 「동생은 그림을 언제부터 그렸나요?」 「가장 좋아하는 그림은 무엇인가요?」 — 동생이 그림을 얼마나 좋아하는지 알고 싶기 때문입니다.","scoring_points":["소개 내용과 관련 있는 질문 두 가지를 썼는가","정중한 말로 썼는가","궁금한 까닭을 썼는가"]},"explanation":["관련 있는 질문.","정중한 말.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#1','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C1',1,'mc','auto','친구가 발표할 때 바른 듣기 태도는 어느 것인가요?',ARRAY['K2-1-u1-X02','K2-1-u1-X01']::text[],false,'{"seq":1,"concept":"K2-1-u1-C1","difficulty":1,"kind":"mc","stem":"친구가 발표할 때 바른 듣기 태도는 어느 것인가요?","options":[{"t":"친구를 바라보며 끝까지 들어요","correct":true},{"t":"중간에 끼어들어 내 말을 해요","mis":"K2-1-u1-X02"},{"t":"옆 친구와 떠들며 들어요","mis":"K2-1-u1-X01"}],"explanation":["말하는 사람을 바라보며 끝까지 들어요.","끼어들거나 다른 일을 하면 잘 들을 수 없어요.","잘 들어 주면 말하는 사람도 기분이 좋아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#2','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C2',1,'mc','auto','나를 소개하는 글에 넣으면 좋은 내용은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":2,"concept":"K2-1-u1-C2","difficulty":1,"kind":"mc","stem":"나를 소개하는 글에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"내가 좋아하는 것","correct":true},{"t":"어제 본 만화 줄거리","mis":"K2-1-u1-X06"},{"t":"내일 날씨","mis":"K2-1-u1-X06"}],"explanation":["내가 좋아하는 것은 나를 알려 주는 내용이에요.","다른 둘은 나와 관계가 없어요.","소개하는 글에는 나를 알려 주는 내용을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#3','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C3',1,'mc','auto','말차례란 무엇인가요?',ARRAY['K2-1-u1-X03','K2-1-u1-X05']::text[],false,'{"seq":3,"concept":"K2-1-u1-C3","difficulty":1,"kind":"mc","stem":"말차례란 무엇인가요?","options":[{"t":"대화할 때 한 사람씩 차례대로 말하는 것","correct":true},{"t":"먼저 큰 소리로 말하는 사람이 말하는 것","mis":"K2-1-u1-X03"},{"t":"한 사람만 계속 말하는 것","mis":"K2-1-u1-X05"}],"explanation":["말차례는 한 사람씩 차례대로 말하는 거예요.","먼저·크게 말하거나 혼자 계속 말하는 것은 말차례가 아니에요.","모두가 돌아가며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#4','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C4',1,'mc','auto','말차례를 지키지 못한 행동은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],false,'{"seq":4,"concept":"K2-1-u1-C4","difficulty":1,"kind":"mc","stem":"말차례를 지키지 못한 행동은 어느 것인가요?","options":[{"t":"친구가 말하는데 끼어들기","correct":true},{"t":"손 들고 기다리기","mis":"K2-1-u1-X16"},{"t":"끝까지 잘 듣기","mis":"K2-1-u1-X16"}],"explanation":["끼어드는 것은 말차례를 어긴 거예요.","말하고 싶으면 손을 들고 기다려요.","친구 말이 끝나면 내 차례에 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#5','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 바닥을 함께 닦은 친구는 누구인가요?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":5,"concept":"K2-1-u1-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 바닥을 함께 닦은 친구는 누구인가요?","options":[{"t":"준우","correct":true},{"t":"예린","mis":"K2-1-u1-X11"},{"t":"선생님","mis":"K2-1-u1-X11"}],"explanation":["글에 「준우가 휴지로 바닥을 함께 닦았어요」라고 나와 있어요.","다른 보기는 글에 나오지 않거나 다른 사람이 한 일이에요.","누가 무엇을 했는지 글에서 짚어요."],"asset":{"type":"passage","lines":["쉬는 시간에 예린이가 물통을 쏟았어요.","옆에 있던 준우가 휴지로 바닥을 함께 닦았어요.","예린이는 「고마워.」 하고 웃었어요."],"title":"쏟아진 물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#6','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C7',1,'mc','auto','「제 꿈은 수의사입니다.」는 어떤 소개 항목인가요?',ARRAY['K2-1-u1-X10']::text[],false,'{"seq":6,"concept":"K2-1-u1-C7","difficulty":1,"kind":"mc","stem":"「제 꿈은 수의사입니다.」는 어떤 소개 항목인가요?","options":[{"t":"꿈","correct":true},{"t":"좋아하는 것","mis":"K2-1-u1-X10"},{"t":"잘하는 것","mis":"K2-1-u1-X10"}],"explanation":["「제 꿈은 수의사입니다.」는 꿈을 소개하는 문장이에요.","항목 이름이 문장에 들어 있어요.","이름·좋아하는 것·잘하는 것·꿈을 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#7','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C8',1,'mc','auto','나를 소개하는 글의 첫 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06','K2-1-u1-X07']::text[],false,'{"seq":7,"concept":"K2-1-u1-C8","difficulty":1,"kind":"mc","stem":"나를 소개하는 글의 첫 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"저는 이하준입니다.","correct":true},{"t":"오늘은 날씨가 맑습니다.","mis":"K2-1-u1-X06"},{"t":"제가 잘하는 것은 줄넘기입니다.","mis":"K2-1-u1-X07"}],"explanation":["소개하는 글은 「저는 ○○○입니다.」로 시작해요.","그래야 누구의 글인지 바로 알 수 있어요.","나머지 내용은 이름 다음에 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#8','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C9',1,'mc','auto','주변 사람 소개에 넣으면 좋은 내용은 어느 것인가요?',ARRAY['K2-1-u1-X14']::text[],false,'{"seq":8,"concept":"K2-1-u1-C9","difficulty":1,"kind":"mc","stem":"주변 사람 소개에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"그 사람이 잘하는 것","correct":true},{"t":"그 사람의 전화번호","mis":"K2-1-u1-X14"},{"t":"그 사람 집 비밀번호","mis":"K2-1-u1-X14"}],"explanation":["그 사람이 잘하는 것은 그 사람을 따뜻하게 알려 줘요.","개인 정보나 흉은 넣지 않아요.","존중하는 마음으로 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#9','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C1',2,'ox','auto','친구가 말할 때 딴 곳을 보아도 귀로 들리면 잘 듣는 것이에요.',ARRAY['K2-1-u1-X01']::text[],false,'{"seq":9,"concept":"K2-1-u1-C1","difficulty":2,"kind":"ox","stem":"친구가 말할 때 딴 곳을 보아도 귀로 들리면 잘 듣는 것이에요.","answer":"X","reason_options":[{"t":"말하는 사람을 바라보며 마음을 기울여 들어야 하니까","correct":true},{"t":"귀로 소리만 들리면 되니까","mis":"K2-1-u1-X01"}],"mis":"K2-1-u1-X01","explanation":["잘 듣기는 눈과 마음으로도 해요.","딴 곳을 보면 친구는 내가 안 듣는다고 느껴요.","말하는 사람을 바라보며 끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#10','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C4',2,'mc','auto','짝이 「좋아하는 음식이 뭐야?」 하고 물었어요. 말차례를 지켜 알맞게 대답한 것은 어느 것인가요?',ARRAY['K2-1-u1-X04']::text[],false,'{"seq":10,"concept":"K2-1-u1-C4","difficulty":2,"kind":"mc","stem":"짝이 「좋아하는 음식이 뭐야?」 하고 물었어요. 말차례를 지켜 알맞게 대답한 것은 어느 것인가요?","options":[{"t":"「나는 떡볶이를 좋아해. 너는?」","correct":true},{"t":"「나 어제 축구했어!」","mis":"K2-1-u1-X04"},{"t":"「몰라. 그런데 오늘 비 온대.」","mis":"K2-1-u1-X04"}],"explanation":["묻는 말에 맞게 대답했어요.","그리고 짝에게 되물어 차례를 건넸어요.","관계없는 말을 하면 대화가 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#11','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C6',2,'mc','auto','이야기를 읽고 답해 보세요. 줄을 함께 쓰게 된 하람이의 마음은?',ARRAY['K2-1-u1-X12']::text[],false,'{"seq":11,"concept":"K2-1-u1-C6","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 줄을 함께 쓰게 된 하람이의 마음은?","options":[{"t":"고맙고 기쁜 마음","correct":true},{"t":"화나는 마음","mis":"K2-1-u1-X12"},{"t":"심심한 마음","mis":"K2-1-u1-X12"}],"explanation":["하람이는 「고마워!」 하며 웃었어요.","곤란할 때 도움을 받으면 고맙고 기뻐요.","일어난 일과 인물의 말·모습에서 마음을 짐작해요."],"asset":{"type":"passage","lines":["하람이가 줄넘기 줄을 집에 두고 왔어요.","다은이가 「내 줄로 같이 하자!」 하고 말했어요.","하람이는 「고마워!」 하며 활짝 웃었어요."],"title":"나눠 쓴 줄넘기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#12','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C7',2,'mc','auto','「저는 그림 그리기를 좋아합니다.」에 까닭을 더해 이어 쓸 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":12,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"「저는 그림 그리기를 좋아합니다.」에 까닭을 더해 이어 쓸 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"생각한 것을 마음대로 그릴 수 있기 때문입니다.","correct":true},{"t":"오늘은 비가 옵니다.","mis":"K2-1-u1-X06"},{"t":"저는 키가 큽니다.","mis":"K2-1-u1-X06"}],"explanation":["「~기 때문입니다」로 까닭을 더했어요.","다른 문장은 앞 문장의 까닭이 아니에요.","까닭은 「왜?」에 대한 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#13','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C8',2,'mc','auto','문장의 끝을 바르게 맺어 쓴 것은 어느 것인가요?',ARRAY['K2-1-u1-X08']::text[],false,'{"seq":13,"concept":"K2-1-u1-C8","difficulty":2,"kind":"mc","stem":"문장의 끝을 바르게 맺어 쓴 것은 어느 것인가요?","options":[{"t":"저는 강아지를 좋아합니다.","correct":true},{"t":"저는 강아지를 좋아합니다","mis":"K2-1-u1-X08"},{"t":"저는, 강아지를, 좋아합니다","mis":"K2-1-u1-X08"}],"explanation":["문장이 끝나면 끝에 마침표(.)를 찍어요.","마침표가 없거나 낱말만 늘어놓으면 문장이 끝나지 않아요.","다 쓴 뒤 문장 끝을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#14','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C10',2,'mc','auto','소개하는 글을 발표할 때 바른 모습은 어느 것인가요?',ARRAY['K2-1-u1-X15']::text[],false,'{"seq":14,"concept":"K2-1-u1-C10","difficulty":2,"kind":"mc","stem":"소개하는 글을 발표할 때 바른 모습은 어느 것인가요?","options":[{"t":"친구들을 바라보며 또박또박 말해요","correct":true},{"t":"종이만 보며 작은 목소리로 읽어요","mis":"K2-1-u1-X15"},{"t":"빨리 끝내려고 서둘러 말해요","mis":"K2-1-u1-X15"}],"explanation":["듣는 친구들을 바라보며 말해요.","알맞은 크기와 빠르기로 또박또박 말해요.","작게, 빨리, 고개 숙여 말하면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#15','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C3',2,'ox','auto','말차례를 지키면 한 사람이 혼자 오래 말해도 괜찮아요.',ARRAY['K2-1-u1-X05']::text[],false,'{"seq":15,"concept":"K2-1-u1-C3","difficulty":2,"kind":"ox","stem":"말차례를 지키면 한 사람이 혼자 오래 말해도 괜찮아요.","answer":"X","reason_options":[{"t":"모두가 돌아가며 말할 수 있게 해야 하니까","correct":true},{"t":"먼저 말을 시작한 사람이 끝까지 말해야 하니까","mis":"K2-1-u1-X05"}],"mis":"K2-1-u1-X05","explanation":["한 사람이 오래 말하면 다른 친구는 말할 수 없어요.","내 말을 마치면 차례를 건네요.","모두가 돌아가며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#16','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C9',2,'mc','auto','주변 사람을 소개할 때 따뜻한 소개말은 어느 것인가요?',ARRAY['K2-1-u1-X14']::text[],false,'{"seq":16,"concept":"K2-1-u1-C9","difficulty":2,"kind":"mc","stem":"주변 사람을 소개할 때 따뜻한 소개말은 어느 것인가요?","options":[{"t":"친구를 잘 도와줍니다.","correct":true},{"t":"자주 늦잠을 잡니다.","mis":"K2-1-u1-X14"},{"t":"밥을 늦게 먹습니다.","mis":"K2-1-u1-X14"}],"explanation":["「는 좋은 점을 전하는 말이에요.친구를 잘 도와줍니다.」","다른 둘은 흉이 될 수 있어요.","존중하는 마음으로 좋은 점을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#17','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C4',3,'error','auto','모둠 친구들이 말차례에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X03','K2-1-u1-X16']::text[],false,'{"seq":17,"concept":"K2-1-u1-C4","difficulty":3,"kind":"error","stem":"모둠 친구들이 말차례에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준우 — 목소리가 큰 사람이 먼저 말하는 게 말차례예요","correct":true,"mis_target":"K2-1-u1-X03"},{"t":"소율 — 한 사람씩 차례대로 말해요","mis":"K2-1-u1-X16"},{"t":"예린 — 다른 사람 말을 끝까지 들어요","mis":"K2-1-u1-X16"}],"explanation":["목소리가 크다고 먼저 말하는 것이 아니에요.","말차례는 한 사람씩 차례대로 말하는 거예요.","다른 두 친구는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#18','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C6',3,'mc','auto','이야기를 읽고 생각을 나누고 있어요. 서윤이가 이어서 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X13','K2-1-u1-X04']::text[],false,'{"seq":18,"concept":"K2-1-u1-C6","difficulty":3,"kind":"mc","stem":"이야기를 읽고 생각을 나누고 있어요. 서윤이가 이어서 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「그렇구나. 왜 그렇게 생각해?」","correct":true},{"t":"「그건 틀린 생각이야.」","mis":"K2-1-u1-X13"},{"t":"「나 배고파.」","mis":"K2-1-u1-X04"}],"explanation":["친구가 나와 다른 생각을 말했어요.","다른 생각을 인정하고 까닭을 물으면 이야기가 이어져요.","틀렸다고 하거나 관계없는 말을 하면 나누기가 끊겨요."],"asset":{"type":"speech","turns":[{"who":"서윤","text":"나는 지안이가 참 다정한 것 같아."},{"who":"준우","text":"나는 로아가 다시 쌓자고 먼저 말했으면 좋았을 것 같아."},{"who":"서윤","text":"( ? )"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#19','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C8',3,'mc','auto','친구가 쓴 소개 글을 보고 답해 보세요. 다듬을 때 빼야 할 문장은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],false,'{"seq":19,"concept":"K2-1-u1-C8","difficulty":3,"kind":"mc","stem":"친구가 쓴 소개 글을 보고 답해 보세요. 다듬을 때 빼야 할 문장은 어느 것인가요?","options":[{"t":"어제는 엄마와 마트에 갔습니다.","correct":true},{"t":"저는 문서윤입니다.","mis":"K2-1-u1-X16"},{"t":"제 꿈은 수의사입니다.","mis":"K2-1-u1-X16"}],"explanation":["「어제는 엄마와 마트에 갔습니다」는 글쓴이를 알려 주는 내용이 아니에요.","이름과 꿈·좋아하는 것은 소개하는 글에 맞는 문장이에요.","다시 읽으며 관계없는 문장을 빼요."],"asset":{"type":"passage","lines":["저는 문서윤입니다.","저는 고양이를 좋아합니다.","어제는 엄마와 마트에 갔습니다.","제 꿈은 수의사입니다."],"title":"친구가 쓴 소개 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#20','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C9',3,'error','auto','친구들이 주변 사람을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?',ARRAY['K2-1-u1-X14','K2-1-u1-X16']::text[],false,'{"seq":20,"concept":"K2-1-u1-C9","difficulty":3,"kind":"error","stem":"친구들이 주변 사람을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"준우 — 「제 형의 전화번호는 공일공…입니다.」","correct":true,"mis_target":"K2-1-u1-X14"},{"t":"다은 — 「저희 엄마께서는 요리를 잘하십니다.」","mis":"K2-1-u1-X16"},{"t":"태민 — 「제 짝 로아는 책을 많이 읽습니다.」","mis":"K2-1-u1-X16"}],"explanation":["전화번호는 알리면 안 되는 개인 정보예요.","소개는 존중하는 마음으로 좋은 점을 전해요.","다른 두 친구는 알맞게 소개했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#21','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C5',3,'mc','auto','이야기를 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":21,"concept":"K2-1-u1-C5","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"줄을 두고 옴 → 같이 하자고 함 → 번갈아 넘음","correct":true},{"t":"같이 하자고 함 → 줄을 두고 옴 → 번갈아 넘음","mis":"K2-1-u1-X11"},{"t":"번갈아 넘음 → 줄을 두고 옴 → 같이 하자고 함","mis":"K2-1-u1-X11"}],"explanation":["이야기의 앞에서부터 차례로 짚어요.","줄을 두고 옴 → 같이 하자고 함 → 번갈아 넘음 차례예요.","까닭이 먼저, 결과가 나중에 와요."],"asset":{"type":"passage","lines":["하람이가 줄넘기 줄을 집에 두고 왔어요.","다은이가 같이 하자고 했어요.","둘은 번갈아 줄을 넘었어요."],"title":"나눠 쓴 줄넘기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#22','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C10',3,'mc','auto','친구가 「제 친구 하린이는 종이접기를 잘합니다.」 하고 소개했어요. 소개를 듣고 할 질문으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X04','K2-1-u1-X13']::text[],false,'{"seq":22,"concept":"K2-1-u1-C10","difficulty":3,"kind":"mc","stem":"친구가 「제 친구 하린이는 종이접기를 잘합니다.」 하고 소개했어요. 소개를 듣고 할 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"「하린이는 무엇을 가장 잘 접나요?」","correct":true},{"t":"「너 어제 뭐 먹었어?」","mis":"K2-1-u1-X04"},{"t":"「종이접기는 재미없어.」","mis":"K2-1-u1-X13"}],"explanation":["소개한 내용과 관련 있는 것을 물어요.","관계없는 질문이나 깎아내리는 말은 하지 않아요.","소개가 끝난 뒤 손을 들고 정중하게 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#23','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C8',4,'mc','auto','두 친구가 쓴 소개 글이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#24','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C4',4,'essay','teacher','짝에게 「좋아하는 놀이가 뭐야?」 하고 물었을 때 이어질 대화를 말차례를 지켜 네 마디로 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u1-C4","difficulty":4,"kind":"essay","stem":"짝에게 「좋아하는 놀이가 뭐야?」 하고 물었을 때 이어질 대화를 말차례를 지켜 네 마디로 써 보세요.","answer_guide":{"answer":"예: 나: 좋아하는 놀이가 뭐야? / 짝: 나는 술래잡기를 좋아해. 너는? / 나: 나는 공기놀이를 좋아해. / 짝: 그럼 쉬는 시간에 같이 하자!","scoring_points":["한 사람씩 번갈아 네 마디를 썼는가","묻는 말에 알맞게 대답했는가","되묻거나 이어 말해 대화가 이어졌는가"]},"explanation":["번갈아 말하기.","알맞은 대답.","대화 잇기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#25','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C8',4,'essay','teacher','「저는 ○○○입니다.」로 시작해 나를 소개하는 글을 네 문장으로 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u1-C8","difficulty":4,"kind":"essay","stem":"「저는 ○○○입니다.」로 시작해 나를 소개하는 글을 네 문장으로 써 보세요.","answer_guide":{"answer":"예: 저는 김하늘입니다. / 저는 별 보기를 좋아합니다. / 제가 잘하는 것은 줄넘기입니다. / 제 꿈은 천문학자입니다.","scoring_points":["이름으로 시작했는가","나(그 사람)를 알려 주는 내용을 담았는가","한 문장에 한 가지씩 문장으로 쓰고 마침표를 찍었는가"]},"explanation":["첫 문장.","알려 주는 내용.","한 문장에 한 가지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#1','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C1',1,'mc','auto','선생님께서 설명하실 때 바른 듣기 태도는 어느 것인가요?',ARRAY['K2-1-u1-X02','K2-1-u1-X01']::text[],false,'{"seq":1,"concept":"K2-1-u1-C1","difficulty":1,"kind":"mc","stem":"선생님께서 설명하실 때 바른 듣기 태도는 어느 것인가요?","options":[{"t":"선생님을 바라보며 끝까지 들어요","correct":true},{"t":"궁금한 것이 생기면 바로 끼어들어요","mis":"K2-1-u1-X02"},{"t":"공책에 낙서하며 들어요","mis":"K2-1-u1-X01"}],"explanation":["말하는 사람을 바라보며 끝까지 들어요.","끼어들거나 다른 일을 하면 잘 들을 수 없어요.","잘 들어 주면 말하는 사람도 기분이 좋아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#2','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C2',1,'mc','auto','나를 소개하는 글에 넣으면 좋은 내용은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":2,"concept":"K2-1-u1-C2","difficulty":1,"kind":"mc","stem":"나를 소개하는 글에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"내가 잘하는 것","correct":true},{"t":"오늘 급식 반찬","mis":"K2-1-u1-X06"},{"t":"버스 도착 시간","mis":"K2-1-u1-X06"}],"explanation":["내가 잘하는 것은 나를 알려 주는 내용이에요.","다른 둘은 나와 관계가 없어요.","소개하는 글에는 나를 알려 주는 내용을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#3','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C3',1,'mc','auto','「말차례를 지킨다」는 것은 무엇인가요?',ARRAY['K2-1-u1-X03','K2-1-u1-X05']::text[],false,'{"seq":3,"concept":"K2-1-u1-C3","difficulty":1,"kind":"mc","stem":"「말차례를 지킨다」는 것은 무엇인가요?","options":[{"t":"한 사람씩 돌아가며 차례대로 말하는 것","correct":true},{"t":"목소리가 큰 사람부터 말하는 것","mis":"K2-1-u1-X03"},{"t":"말을 시작한 사람이 끝까지 혼자 말하는 것","mis":"K2-1-u1-X05"}],"explanation":["말차례는 한 사람씩 차례대로 말하는 거예요.","먼저·크게 말하거나 혼자 계속 말하는 것은 말차례가 아니에요.","모두가 돌아가며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#4','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C4',1,'mc','auto','말차례를 잘 지킨 행동은 어느 것인가요?',ARRAY['K2-1-u1-X02','K2-1-u1-X03']::text[],false,'{"seq":4,"concept":"K2-1-u1-C4","difficulty":1,"kind":"mc","stem":"말차례를 잘 지킨 행동은 어느 것인가요?","options":[{"t":"친구 말이 끝난 뒤 내 차례에 말하기","correct":true},{"t":"생각나면 바로 끼어들기","mis":"K2-1-u1-X02"},{"t":"친구보다 먼저 크게 말하기","mis":"K2-1-u1-X03"}],"explanation":["친구 말이 끝난 뒤 말하는 것이 말차례를 지킨 거예요.","말하고 싶으면 손을 들고 기다려요.","친구 말이 끝나면 내 차례에 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#5','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 소율이가 물고기에게 준 것은 무엇인가요?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":5,"concept":"K2-1-u1-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 소율이가 물고기에게 준 것은 무엇인가요?","options":[{"t":"먹이","correct":true},{"t":"물","mis":"K2-1-u1-X11"},{"t":"장난감","mis":"K2-1-u1-X11"}],"explanation":["글에 「소율이는 먹이를 조금 주었어요」라고 나와 있어요.","다른 보기는 글에 나오지 않거나 다른 사람이 한 일이에요.","누가 무엇을 했는지 글에서 짚어요."],"asset":{"type":"passage","lines":["아침에 소율이가 교실에 들어왔어요.","칠판 옆 어항의 물고기가 배고파 보였어요.","소율이는 먹이를 조금 주었어요."],"title":"어항 당번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#6','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C7',1,'mc','auto','「제가 잘하는 것은 수영입니다.」는 어떤 소개 항목인가요?',ARRAY['K2-1-u1-X10']::text[],false,'{"seq":6,"concept":"K2-1-u1-C7","difficulty":1,"kind":"mc","stem":"「제가 잘하는 것은 수영입니다.」는 어떤 소개 항목인가요?","options":[{"t":"잘하는 것","correct":true},{"t":"꿈","mis":"K2-1-u1-X10"},{"t":"이름","mis":"K2-1-u1-X10"}],"explanation":["「제가 잘하는 것은 수영입니다.」는 잘하는 것을 소개하는 문장이에요.","항목 이름이 문장에 들어 있어요.","이름·좋아하는 것·잘하는 것·꿈을 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#7','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C8',1,'mc','auto','나를 소개하는 글의 첫 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06','K2-1-u1-X07']::text[],false,'{"seq":7,"concept":"K2-1-u1-C8","difficulty":1,"kind":"mc","stem":"나를 소개하는 글의 첫 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"저는 박서아입니다.","correct":true},{"t":"어제 학교에 일찍 왔습니다.","mis":"K2-1-u1-X06"},{"t":"제 꿈은 화가입니다.","mis":"K2-1-u1-X07"}],"explanation":["소개하는 글은 「저는 ○○○입니다.」로 시작해요.","그래야 누구의 글인지 바로 알 수 있어요.","나머지 내용은 이름 다음에 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#8','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C9',1,'mc','auto','주변 사람 소개에 넣으면 좋은 내용은 어느 것인가요?',ARRAY['K2-1-u1-X14']::text[],false,'{"seq":8,"concept":"K2-1-u1-C9","difficulty":1,"kind":"mc","stem":"주변 사람 소개에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"그 사람의 좋은 점","correct":true},{"t":"그 사람의 집 주소","mis":"K2-1-u1-X14"},{"t":"그 사람이 실수한 일","mis":"K2-1-u1-X14"}],"explanation":["그 사람의 좋은 점은 그 사람을 따뜻하게 알려 줘요.","개인 정보나 흉은 넣지 않아요.","존중하는 마음으로 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#9','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C1',2,'ox','auto','친구 말이 끝날 때까지 기다렸다가 내 생각을 말하는 것은 잘 듣는 태도예요.',ARRAY['K2-1-u1-X02']::text[],false,'{"seq":9,"concept":"K2-1-u1-C1","difficulty":2,"kind":"ox","stem":"친구 말이 끝날 때까지 기다렸다가 내 생각을 말하는 것은 잘 듣는 태도예요.","answer":"O","reason_options":[{"t":"끼어들지 않고 끝까지 들었으니까","correct":true},{"t":"생각나면 바로 말해야 잊지 않으니까","mis":"K2-1-u1-X02"}],"mis":"K2-1-u1-X02","explanation":["끝까지 기다리는 것이 잘 듣는 태도예요.","끼어들면 친구 말이 끊겨요.","말하는 사람을 바라보며 끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#10','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C4',2,'mc','auto','짝이 「주말에 뭐 했어?」 하고 물었어요. 말차례를 지켜 알맞게 대답한 것은 어느 것인가요?',ARRAY['K2-1-u1-X04']::text[],false,'{"seq":10,"concept":"K2-1-u1-C4","difficulty":2,"kind":"mc","stem":"짝이 「주말에 뭐 했어?」 하고 물었어요. 말차례를 지켜 알맞게 대답한 것은 어느 것인가요?","options":[{"t":"「할머니 댁에 갔어. 너는 뭐 했어?」","correct":true},{"t":"「나 연필 새로 샀다!」","mis":"K2-1-u1-X04"},{"t":"「배고프다.」","mis":"K2-1-u1-X04"}],"explanation":["묻는 말에 맞게 대답했어요.","그리고 짝에게 되물어 차례를 건넸어요.","관계없는 말을 하면 대화가 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#11','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C6',2,'mc','auto','이야기를 읽고 답해 보세요. 모래성이 무너졌을 때 로아의 마음은?',ARRAY['K2-1-u1-X12']::text[],false,'{"seq":11,"concept":"K2-1-u1-C6","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 모래성이 무너졌을 때 로아의 마음은?","options":[{"t":"속상한 마음","correct":true},{"t":"신나는 마음","mis":"K2-1-u1-X12"},{"t":"졸린 마음","mis":"K2-1-u1-X12"}],"explanation":["로아는 울먹였어요.","애써 쌓은 것이 무너지면 속상해요.","일어난 일과 인물의 말·모습에서 마음을 짐작해요."],"asset":{"type":"passage","lines":["지안이와 로아가 모래성을 쌓았어요.","큰 파도가 와서 모래성이 무너졌어요.","로아는 울먹였어요."],"title":"무너진 모래성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#12','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C7',2,'mc','auto','「제 꿈은 요리사입니다.」에 까닭을 더해 이어 쓸 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":12,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"「제 꿈은 요리사입니다.」에 까닭을 더해 이어 쓸 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"가족에게 맛있는 음식을 만들어 주고 싶기 때문입니다.","correct":true},{"t":"어제 라면을 먹었습니다.","mis":"K2-1-u1-X06"},{"t":"요리사는 하얀 모자를 씁니다.","mis":"K2-1-u1-X06"}],"explanation":["「~기 때문입니다」로 까닭을 더했어요.","다른 문장은 앞 문장의 까닭이 아니에요.","까닭은 「왜?」에 대한 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#13','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C8',2,'mc','auto','문장의 끝을 바르게 맺어 쓴 것은 어느 것인가요?',ARRAY['K2-1-u1-X08']::text[],false,'{"seq":13,"concept":"K2-1-u1-C8","difficulty":2,"kind":"mc","stem":"문장의 끝을 바르게 맺어 쓴 것은 어느 것인가요?","options":[{"t":"제 꿈은 경찰관입니다.","correct":true},{"t":"제 꿈은 경찰관입니다","mis":"K2-1-u1-X08"},{"t":"제 꿈은, 경찰관","mis":"K2-1-u1-X08"}],"explanation":["문장이 끝나면 끝에 마침표(.)를 찍어요.","마침표가 없거나 낱말만 늘어놓으면 문장이 끝나지 않아요.","다 쓴 뒤 문장 끝을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#14','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C10',2,'mc','auto','소개하는 글을 발표할 때 바른 모습은 어느 것인가요?',ARRAY['K2-1-u1-X15']::text[],false,'{"seq":14,"concept":"K2-1-u1-C10","difficulty":2,"kind":"mc","stem":"소개하는 글을 발표할 때 바른 모습은 어느 것인가요?","options":[{"t":"바른 자세로 서서 알맞은 크기로 말해요","correct":true},{"t":"몸을 흔들며 혼잣말처럼 말해요","mis":"K2-1-u1-X15"},{"t":"고개를 숙이고 웅얼거려요","mis":"K2-1-u1-X15"}],"explanation":["듣는 친구들을 바라보며 말해요.","알맞은 크기와 빠르기로 또박또박 말해요.","작게, 빨리, 고개 숙여 말하면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#15','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C3',2,'ox','auto','여러 친구가 한꺼번에 말하면 서로의 말을 알아듣기 어려워요.',ARRAY['K2-1-u1-X03']::text[],false,'{"seq":15,"concept":"K2-1-u1-C3","difficulty":2,"kind":"ox","stem":"여러 친구가 한꺼번에 말하면 서로의 말을 알아듣기 어려워요.","answer":"O","reason_options":[{"t":"말소리가 섞여 무슨 말인지 알 수 없으니까","correct":true},{"t":"한꺼번에 말해야 이야기가 빨리 끝나니까","mis":"K2-1-u1-X03"}],"mis":"K2-1-u1-X03","explanation":["한꺼번에 말하면 말소리가 섞여요.","그래서 말차례가 필요해요.","모두가 돌아가며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#16','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C9',2,'mc','auto','주변 사람을 소개할 때 따뜻한 소개말은 어느 것인가요?',ARRAY['K2-1-u1-X14']::text[],false,'{"seq":16,"concept":"K2-1-u1-C9","difficulty":2,"kind":"mc","stem":"주변 사람을 소개할 때 따뜻한 소개말은 어느 것인가요?","options":[{"t":"웃는 모습이 환합니다.","correct":true},{"t":"숙제를 자주 잊습니다.","mis":"K2-1-u1-X14"},{"t":"목소리가 너무 큽니다.","mis":"K2-1-u1-X14"}],"explanation":["「는 좋은 점을 전하는 말이에요.웃는 모습이 환합니다.」","다른 둘은 흉이 될 수 있어요.","존중하는 마음으로 좋은 점을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#17','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C4',3,'error','auto','모둠 친구들이 말차례에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X02','K2-1-u1-X16']::text[],false,'{"seq":17,"concept":"K2-1-u1-C4","difficulty":3,"kind":"error","stem":"모둠 친구들이 말차례에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 내 생각이 맞으면 친구 말을 끊어도 돼요","correct":true,"mis_target":"K2-1-u1-X02"},{"t":"서윤 — 말하고 싶으면 손을 들고 기다려요","mis":"K2-1-u1-X16"},{"t":"태민 — 친구 말이 끝나면 내 차례에 말해요","mis":"K2-1-u1-X16"}],"explanation":["생각이 맞아도 친구 말을 끊으면 안 돼요.","말차례는 한 사람씩 차례대로 말하는 거예요.","다른 두 친구는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#18','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C6',3,'mc','auto','이야기를 읽고 생각을 나누고 있어요. 예린이가 이어서 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X13','K2-1-u1-X04']::text[],false,'{"seq":18,"concept":"K2-1-u1-C6","difficulty":3,"kind":"mc","stem":"이야기를 읽고 생각을 나누고 있어요. 예린이가 이어서 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「그런 방법도 있구나!」","correct":true},{"t":"「아니야, 빌려주는 게 맞아.」","mis":"K2-1-u1-X13"},{"t":"「오늘 급식 뭐야?」","mis":"K2-1-u1-X04"}],"explanation":["친구가 나와 다른 생각을 말했어요.","다른 생각을 인정하고 까닭을 물으면 이야기가 이어져요.","틀렸다고 하거나 관계없는 말을 하면 나누기가 끊겨요."],"asset":{"type":"speech","turns":[{"who":"예린","text":"나라면 줄을 빌려주었을 거야."},{"who":"도윤","text":"나는 선생님께 줄을 빌려 달라고 했을 것 같아."},{"who":"예린","text":"( ? )"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#19','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C8',3,'mc','auto','친구가 쓴 소개 글을 보고 답해 보세요. 다듬을 때 빼야 할 문장은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],false,'{"seq":19,"concept":"K2-1-u1-C8","difficulty":3,"kind":"mc","stem":"친구가 쓴 소개 글을 보고 답해 보세요. 다듬을 때 빼야 할 문장은 어느 것인가요?","options":[{"t":"오늘 아침에 버스가 늦게 왔습니다.","correct":true},{"t":"저는 강소율입니다.","mis":"K2-1-u1-X16"},{"t":"제가 잘하는 것은 줄넘기입니다.","mis":"K2-1-u1-X16"}],"explanation":["「오늘 아침에 버스가 늦게 왔습니다」는 글쓴이를 알려 주는 내용이 아니에요.","이름과 꿈·좋아하는 것은 소개하는 글에 맞는 문장이에요.","다시 읽으며 관계없는 문장을 빼요."],"asset":{"type":"passage","lines":["저는 강소율입니다.","저는 곤충 관찰을 좋아합니다.","오늘 아침에 버스가 늦게 왔습니다.","제가 잘하는 것은 줄넘기입니다."],"title":"친구가 쓴 소개 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#20','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C9',3,'error','auto','친구들이 주변 사람을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?',ARRAY['K2-1-u1-X14','K2-1-u1-X16']::text[],false,'{"seq":20,"concept":"K2-1-u1-C9","difficulty":3,"kind":"error","stem":"친구들이 주변 사람을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"하린 — 「제 동생은 아직도 밤에 이불에 실수를 합니다.」","correct":true,"mis_target":"K2-1-u1-X14"},{"t":"지호 — 「제 동생은 블록 쌓기를 잘합니다.」","mis":"K2-1-u1-X16"},{"t":"서아 — 「저희 아빠께서는 노래를 잘 부르십니다.」","mis":"K2-1-u1-X16"}],"explanation":["동생이 부끄러워할 일을 말했어요.","소개는 존중하는 마음으로 좋은 점을 전해요.","다른 두 친구는 알맞게 소개했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#21','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C5',3,'mc','auto','이야기를 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":21,"concept":"K2-1-u1-C5","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"비가 내림 → 화분을 옮김 → 칭찬을 들음","correct":true},{"t":"칭찬을 들음 → 비가 내림 → 화분을 옮김","mis":"K2-1-u1-X11"},{"t":"화분을 옮김 → 칭찬을 들음 → 비가 내림","mis":"K2-1-u1-X11"}],"explanation":["이야기의 앞에서부터 차례로 짚어요.","비가 내림 → 화분을 옮김 → 칭찬을 들음 차례예요.","까닭이 먼저, 결과가 나중에 와요."],"asset":{"type":"passage","lines":["아침부터 비가 내렸어요.","시우가 젖는 화분을 안으로 옮겼어요.","선생님께서 시우를 칭찬하셨어요."],"title":"빗속의 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#22','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C10',3,'mc','auto','친구가 「저희 형은 축구를 잘합니다.」 하고 소개했어요. 소개를 듣고 할 질문으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X04','K2-1-u1-X13']::text[],false,'{"seq":22,"concept":"K2-1-u1-C10","difficulty":3,"kind":"mc","stem":"친구가 「저희 형은 축구를 잘합니다.」 하고 소개했어요. 소개를 듣고 할 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"「형은 축구를 언제부터 했나요?」","correct":true},{"t":"「오늘 급식 뭐야?」","mis":"K2-1-u1-X04"},{"t":"「축구 잘하는 게 뭐가 대단해?」","mis":"K2-1-u1-X13"}],"explanation":["소개한 내용과 관련 있는 것을 물어요.","관계없는 질문이나 깎아내리는 말은 하지 않아요.","소개가 끝난 뒤 손을 들고 정중하게 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#23','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C8',4,'mc','auto','두 친구가 쓴 소개 글이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#24','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C4',4,'essay','teacher','짝에게 「좋아하는 계절이 언제야?」 하고 물었을 때 이어질 대화를 말차례를 지켜 네 마디로 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u1-C4","difficulty":4,"kind":"essay","stem":"짝에게 「좋아하는 계절이 언제야?」 하고 물었을 때 이어질 대화를 말차례를 지켜 네 마디로 써 보세요.","answer_guide":{"answer":"예: 나: 좋아하는 계절이 언제야? / 짝: 나는 여름이 좋아. 너는? / 나: 나는 눈이 와서 겨울이 좋아. / 짝: 겨울에 같이 눈사람 만들자!","scoring_points":["한 사람씩 번갈아 네 마디를 썼는가","묻는 말에 알맞게 대답했는가","되묻거나 이어 말해 대화가 이어졌는가"]},"explanation":["번갈아 말하기.","알맞은 대답.","대화 잇기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#25','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C8',4,'essay','teacher','나를 소개하는 글을 세 문장으로 쓰고, 좋아하는 것에는 까닭을 더해 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u1-C8","difficulty":4,"kind":"essay","stem":"나를 소개하는 글을 세 문장으로 쓰고, 좋아하는 것에는 까닭을 더해 보세요.","answer_guide":{"answer":"예: 저는 이도담입니다. / 저는 그림 그리기를 좋아합니다. 생각한 것을 마음대로 그릴 수 있기 때문입니다. / 제 꿈은 화가입니다.","scoring_points":["이름으로 시작했는가","나(그 사람)를 알려 주는 내용을 담았는가","한 문장에 한 가지씩 문장으로 쓰고 마침표를 찍었는가"]},"explanation":["첫 문장.","알려 주는 내용.","한 문장에 한 가지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#1','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C1',1,'mc','auto','짝이 주말 이야기를 할 때 바른 듣기 태도는 어느 것인가요?',ARRAY['K2-1-u1-X02','K2-1-u1-X01']::text[],false,'{"seq":1,"concept":"K2-1-u1-C1","difficulty":1,"kind":"mc","stem":"짝이 주말 이야기를 할 때 바른 듣기 태도는 어느 것인가요?","options":[{"t":"짝을 바라보며 고개를 끄덕여요","correct":true},{"t":"짝 말을 자르고 내 주말 이야기를 해요","mis":"K2-1-u1-X02"},{"t":"딴 곳을 보며 들어요","mis":"K2-1-u1-X01"}],"explanation":["말하는 사람을 바라보며 끝까지 들어요.","끼어들거나 다른 일을 하면 잘 들을 수 없어요.","잘 들어 주면 말하는 사람도 기분이 좋아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#2','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C2',1,'mc','auto','나를 소개하는 글에 넣으면 좋은 내용은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":2,"concept":"K2-1-u1-C2","difficulty":1,"kind":"mc","stem":"나를 소개하는 글에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"나의 꿈","correct":true},{"t":"지금 몇 시인지","mis":"K2-1-u1-X06"},{"t":"어제 본 뉴스","mis":"K2-1-u1-X06"}],"explanation":["나의 꿈은 나를 알려 주는 내용이에요.","다른 둘은 나와 관계가 없어요.","소개하는 글에는 나를 알려 주는 내용을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#3','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C3',1,'mc','auto','여럿이 이야기할 때 꼭 지켜야 할 것은 무엇인가요?',ARRAY['K2-1-u1-X03','K2-1-u1-X05']::text[],false,'{"seq":3,"concept":"K2-1-u1-C3","difficulty":1,"kind":"mc","stem":"여럿이 이야기할 때 꼭 지켜야 할 것은 무엇인가요?","options":[{"t":"한 사람씩 차례대로 말하기","correct":true},{"t":"먼저 말하려고 크게 외치기","mis":"K2-1-u1-X03"},{"t":"말 잘하는 친구 혼자 말하기","mis":"K2-1-u1-X05"}],"explanation":["말차례는 한 사람씩 차례대로 말하는 거예요.","먼저·크게 말하거나 혼자 계속 말하는 것은 말차례가 아니에요.","모두가 돌아가며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#4','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C4',1,'mc','auto','말차례를 지키지 못한 행동은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],false,'{"seq":4,"concept":"K2-1-u1-C4","difficulty":1,"kind":"mc","stem":"말차례를 지키지 못한 행동은 어느 것인가요?","options":[{"t":"친구 말을 자르고 「내 말 들어 봐!」 하기","correct":true},{"t":"손을 들고 차례 기다리기","mis":"K2-1-u1-X16"},{"t":"고개를 끄덕이며 듣기","mis":"K2-1-u1-X16"}],"explanation":["친구 말을 자르는 것은 말차례를 어긴 거예요.","말하고 싶으면 손을 들고 기다려요.","친구 말이 끝나면 내 차례에 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#5','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 나무에 걸린 것은 무엇인가요?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":5,"concept":"K2-1-u1-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 나무에 걸린 것은 무엇인가요?","options":[{"t":"공","correct":true},{"t":"연","mis":"K2-1-u1-X11"},{"t":"모자","mis":"K2-1-u1-X11"}],"explanation":["글에 「태민이의 공이 나무에 걸렸어요」라고 나와 있어요.","다른 보기는 글에 나오지 않거나 다른 사람이 한 일이에요.","누가 무엇을 했는지 글에서 짚어요."],"asset":{"type":"passage","lines":["운동장에서 태민이의 공이 나무에 걸렸어요.","키가 큰 지호가 나뭇가지를 흔들어 공을 떨어뜨렸어요.","둘은 다시 공놀이를 했어요."],"title":"나무에 걸린 공"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#6','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C7',1,'mc','auto','「저는 공룡 책을 좋아합니다.」는 어떤 소개 항목인가요?',ARRAY['K2-1-u1-X10']::text[],false,'{"seq":6,"concept":"K2-1-u1-C7","difficulty":1,"kind":"mc","stem":"「저는 공룡 책을 좋아합니다.」는 어떤 소개 항목인가요?","options":[{"t":"좋아하는 것","correct":true},{"t":"잘하는 것","mis":"K2-1-u1-X10"},{"t":"꿈","mis":"K2-1-u1-X10"}],"explanation":["「저는 공룡 책을 좋아합니다.」는 좋아하는 것을 소개하는 문장이에요.","항목 이름이 문장에 들어 있어요.","이름·좋아하는 것·잘하는 것·꿈을 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#7','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C8',1,'mc','auto','나를 소개하는 글의 첫 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06','K2-1-u1-X07']::text[],false,'{"seq":7,"concept":"K2-1-u1-C8","difficulty":1,"kind":"mc","stem":"나를 소개하는 글의 첫 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"저는 최도윤입니다.","correct":true},{"t":"급식에 카레가 나왔습니다.","mis":"K2-1-u1-X06"},{"t":"저는 축구를 좋아합니다.","mis":"K2-1-u1-X07"}],"explanation":["소개하는 글은 「저는 ○○○입니다.」로 시작해요.","그래야 누구의 글인지 바로 알 수 있어요.","나머지 내용은 이름 다음에 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#8','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C9',1,'mc','auto','주변 사람 소개에 넣으면 좋은 내용은 어느 것인가요?',ARRAY['K2-1-u1-X14']::text[],false,'{"seq":8,"concept":"K2-1-u1-C9","difficulty":1,"kind":"mc","stem":"주변 사람 소개에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"그 사람과 함께한 일","correct":true},{"t":"그 사람의 전화번호","mis":"K2-1-u1-X14"},{"t":"그 사람이 부끄러워하는 일","mis":"K2-1-u1-X14"}],"explanation":["그 사람과 함께한 일은 그 사람을 따뜻하게 알려 줘요.","개인 정보나 흉은 넣지 않아요.","존중하는 마음으로 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#9','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C1',2,'ox','auto','고개를 끄덕이며 들으면 말하는 친구가 내가 잘 듣고 있다는 것을 알 수 있어요.',ARRAY['K2-1-u1-X01']::text[],false,'{"seq":9,"concept":"K2-1-u1-C1","difficulty":2,"kind":"ox","stem":"고개를 끄덕이며 들으면 말하는 친구가 내가 잘 듣고 있다는 것을 알 수 있어요.","answer":"O","reason_options":[{"t":"끄덕임은 잘 듣고 있다는 신호이니까","correct":true},{"t":"듣는 사람은 아무 반응도 하지 않아야 하니까","mis":"K2-1-u1-X01"}],"mis":"K2-1-u1-X01","explanation":["고개를 끄덕이면 잘 듣고 있다는 마음이 전해져요.","반응을 하면 말하는 친구도 힘이 나요.","말하는 사람을 바라보며 끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#10','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C4',2,'mc','auto','짝이 「좋아하는 동물이 뭐야?」 하고 물었어요. 말차례를 지켜 알맞게 대답한 것은 어느 것인가요?',ARRAY['K2-1-u1-X04']::text[],false,'{"seq":10,"concept":"K2-1-u1-C4","difficulty":2,"kind":"mc","stem":"짝이 「좋아하는 동물이 뭐야?」 하고 물었어요. 말차례를 지켜 알맞게 대답한 것은 어느 것인가요?","options":[{"t":"「나는 펭귄이 좋아. 너는 어떤 동물이 좋아?」","correct":true},{"t":"「오늘 급식은 카레래.」","mis":"K2-1-u1-X04"},{"t":"「내 가방 예쁘지?」","mis":"K2-1-u1-X04"}],"explanation":["묻는 말에 맞게 대답했어요.","그리고 짝에게 되물어 차례를 건넸어요.","관계없는 말을 하면 대화가 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#11','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C6',2,'mc','auto','이야기를 읽고 답해 보세요. 칭찬을 들은 시우의 마음은?',ARRAY['K2-1-u1-X12']::text[],false,'{"seq":11,"concept":"K2-1-u1-C6","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 칭찬을 들은 시우의 마음은?","options":[{"t":"쑥스럽지만 기쁜 마음","correct":true},{"t":"슬픈 마음","mis":"K2-1-u1-X12"},{"t":"무서운 마음","mis":"K2-1-u1-X12"}],"explanation":["시우는 얼굴이 빨개졌지만 웃었어요.","칭찬을 들으면 쑥스러워도 기뻐요.","일어난 일과 인물의 말·모습에서 마음을 짐작해요."],"asset":{"type":"passage","lines":["비에 젖는 화분을 시우가 안으로 옮겼어요.","선생님께서 시우를 칭찬하셨어요.","시우는 얼굴이 빨개졌지만 싱긋 웃었어요."],"title":"빗속의 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#12','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C7',2,'mc','auto','「저는 축구를 좋아합니다.」에 까닭을 더해 이어 쓸 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":12,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"「저는 축구를 좋아합니다.」에 까닭을 더해 이어 쓸 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"친구들과 함께 뛰면 신나기 때문입니다.","correct":true},{"t":"우리 집은 3층입니다.","mis":"K2-1-u1-X06"},{"t":"어제 늦잠을 잤습니다.","mis":"K2-1-u1-X06"}],"explanation":["「~기 때문입니다」로 까닭을 더했어요.","다른 문장은 앞 문장의 까닭이 아니에요.","까닭은 「왜?」에 대한 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#13','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C8',2,'mc','auto','문장의 끝을 바르게 맺어 쓴 것은 어느 것인가요?',ARRAY['K2-1-u1-X08']::text[],false,'{"seq":13,"concept":"K2-1-u1-C8","difficulty":2,"kind":"mc","stem":"문장의 끝을 바르게 맺어 쓴 것은 어느 것인가요?","options":[{"t":"제가 잘하는 것은 달리기입니다.","correct":true},{"t":"제가 잘하는 것은 달리기입니다","mis":"K2-1-u1-X08"},{"t":"달리기, 잘함","mis":"K2-1-u1-X08"}],"explanation":["문장이 끝나면 끝에 마침표(.)를 찍어요.","마침표가 없거나 낱말만 늘어놓으면 문장이 끝나지 않아요.","다 쓴 뒤 문장 끝을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#14','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C10',2,'mc','auto','소개하는 글을 발표할 때 바른 모습은 어느 것인가요?',ARRAY['K2-1-u1-X15']::text[],false,'{"seq":14,"concept":"K2-1-u1-C10","difficulty":2,"kind":"mc","stem":"소개하는 글을 발표할 때 바른 모습은 어느 것인가요?","options":[{"t":"한 문장 읽고 고개를 들어 친구들을 봐요","correct":true},{"t":"칠판만 보며 말해요","mis":"K2-1-u1-X15"},{"t":"종이로 얼굴을 가리고 읽어요","mis":"K2-1-u1-X15"}],"explanation":["듣는 친구들을 바라보며 말해요.","알맞은 크기와 빠르기로 또박또박 말해요.","작게, 빨리, 고개 숙여 말하면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#15','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C3',2,'ox','auto','목소리가 큰 사람이 먼저 말하는 것이 말차례예요.',ARRAY['K2-1-u1-X03']::text[],false,'{"seq":15,"concept":"K2-1-u1-C3","difficulty":2,"kind":"ox","stem":"목소리가 큰 사람이 먼저 말하는 것이 말차례예요.","answer":"X","reason_options":[{"t":"말차례는 한 사람씩 차례대로 말하는 것이니까","correct":true},{"t":"크게 말해야 잘 들리니까","mis":"K2-1-u1-X03"}],"mis":"K2-1-u1-X03","explanation":["목소리 크기로 차례가 정해지지 않아요.","손을 들고 차례를 기다려요.","모두가 돌아가며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#16','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C9',2,'mc','auto','주변 사람을 소개할 때 따뜻한 소개말은 어느 것인가요?',ARRAY['K2-1-u1-X14']::text[],false,'{"seq":16,"concept":"K2-1-u1-C9","difficulty":2,"kind":"mc","stem":"주변 사람을 소개할 때 따뜻한 소개말은 어느 것인가요?","options":[{"t":"인사를 밝게 잘합니다.","correct":true},{"t":"신발을 거꾸로 신은 적이 있습니다.","mis":"K2-1-u1-X14"},{"t":"받아쓰기를 자주 틀립니다.","mis":"K2-1-u1-X14"}],"explanation":["「는 좋은 점을 전하는 말이에요.인사를 밝게 잘합니다.」","다른 둘은 흉이 될 수 있어요.","존중하는 마음으로 좋은 점을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#17','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C4',3,'error','auto','모둠 친구들이 말차례에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X05','K2-1-u1-X16']::text[],false,'{"seq":17,"concept":"K2-1-u1-C4","difficulty":3,"kind":"error","stem":"모둠 친구들이 말차례에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 먼저 말하기 시작한 사람이 끝까지 혼자 말해요","correct":true,"mis_target":"K2-1-u1-X05"},{"t":"지호 — 내 차례에 또박또박 말해요","mis":"K2-1-u1-X16"},{"t":"다은 — 말하지 못한 친구에게 차례를 건네요","mis":"K2-1-u1-X16"}],"explanation":["한 사람이 혼자 말하면 다른 친구는 말할 수 없어요.","말차례는 한 사람씩 차례대로 말하는 거예요.","다른 두 친구는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#18','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C6',3,'mc','auto','이야기를 읽고 생각을 나누고 있어요. 지호가 이어서 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X13','K2-1-u1-X04']::text[],false,'{"seq":18,"concept":"K2-1-u1-C6","difficulty":3,"kind":"mc","stem":"이야기를 읽고 생각을 나누고 있어요. 지호가 이어서 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「그럴 수도 있겠다. 어디서 그렇게 느꼈어?」","correct":true},{"t":"「틀렸어. 신났을 거야.」","mis":"K2-1-u1-X13"},{"t":"「나 어제 게임 했어.」","mis":"K2-1-u1-X04"}],"explanation":["친구가 나와 다른 생각을 말했어요.","다른 생각을 인정하고 까닭을 물으면 이야기가 이어져요.","틀렸다고 하거나 관계없는 말을 하면 나누기가 끊겨요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"시우는 칭찬받아서 신났을 것 같아."},{"who":"하린","text":"나는 시우가 좀 부끄러웠을 것 같아."},{"who":"지호","text":"( ? )"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#19','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C8',3,'mc','auto','친구가 쓴 소개 글을 보고 답해 보세요. 다듬을 때 빼야 할 문장은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],false,'{"seq":19,"concept":"K2-1-u1-C8","difficulty":3,"kind":"mc","stem":"친구가 쓴 소개 글을 보고 답해 보세요. 다듬을 때 빼야 할 문장은 어느 것인가요?","options":[{"t":"급식에 카레가 나왔습니다.","correct":true},{"t":"저는 최도윤입니다.","mis":"K2-1-u1-X16"},{"t":"제 꿈은 건축가입니다.","mis":"K2-1-u1-X16"}],"explanation":["「급식에 카레가 나왔습니다」는 글쓴이를 알려 주는 내용이 아니에요.","이름과 꿈·좋아하는 것은 소개하는 글에 맞는 문장이에요.","다시 읽으며 관계없는 문장을 빼요."],"asset":{"type":"passage","lines":["저는 최도윤입니다.","저는 레고 만들기를 좋아합니다.","급식에 카레가 나왔습니다.","제 꿈은 건축가입니다."],"title":"친구가 쓴 소개 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#20','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C9',3,'error','auto','친구들이 주변 사람을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?',ARRAY['K2-1-u1-X14','K2-1-u1-X16']::text[],false,'{"seq":20,"concept":"K2-1-u1-C9","difficulty":3,"kind":"error","stem":"친구들이 주변 사람을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"민호 — 「제 친구 시우네 집 비밀번호는 1234입니다.」","correct":true,"mis_target":"K2-1-u1-X14"},{"t":"소율 — 「제 친구 시우는 친구를 잘 도와줍니다.」","mis":"K2-1-u1-X16"},{"t":"예린 — 「저희 할머니께서는 떡을 잘 만드십니다.」","mis":"K2-1-u1-X16"}],"explanation":["비밀번호는 알리면 안 되는 개인 정보예요.","소개는 존중하는 마음으로 좋은 점을 전해요.","다른 두 친구는 알맞게 소개했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#21','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C5',3,'mc','auto','이야기를 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":21,"concept":"K2-1-u1-C5","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"모래성을 쌓음 → 파도에 무너짐 → 다시 만듦","correct":true},{"t":"파도에 무너짐 → 모래성을 쌓음 → 다시 만듦","mis":"K2-1-u1-X11"},{"t":"다시 만듦 → 모래성을 쌓음 → 파도에 무너짐","mis":"K2-1-u1-X11"}],"explanation":["이야기의 앞에서부터 차례로 짚어요.","모래성을 쌓음 → 파도에 무너짐 → 다시 만듦 차례예요.","까닭이 먼저, 결과가 나중에 와요."],"asset":{"type":"passage","lines":["지안이와 로아가 모래성을 쌓았어요.","파도에 모래성이 무너졌어요.","둘은 조개껍데기를 꽂아 다시 만들었어요."],"title":"함께 만든 모래성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#22','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C10',3,'mc','auto','친구가 「제 동생 아린이는 그림을 잘 그립니다.」 하고 소개했어요. 소개를 듣고 할 질문으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X04','K2-1-u1-X13']::text[],false,'{"seq":22,"concept":"K2-1-u1-C10","difficulty":3,"kind":"mc","stem":"친구가 「제 동생 아린이는 그림을 잘 그립니다.」 하고 소개했어요. 소개를 듣고 할 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"「아린이는 무엇을 즐겨 그리나요?」","correct":true},{"t":"「너 가방 새로 샀어?」","mis":"K2-1-u1-X04"},{"t":"「그림은 나도 잘 그려. 별거 아니야.」","mis":"K2-1-u1-X13"}],"explanation":["소개한 내용과 관련 있는 것을 물어요.","관계없는 질문이나 깎아내리는 말은 하지 않아요.","소개가 끝난 뒤 손을 들고 정중하게 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#23','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C8',4,'mc','auto','두 친구가 쓴 소개 글이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#24','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C4',4,'essay','teacher','짝에게 「주말에 뭐 하고 싶어?」 하고 물었을 때 이어질 대화를 말차례를 지켜 네 마디로 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u1-C4","difficulty":4,"kind":"essay","stem":"짝에게 「주말에 뭐 하고 싶어?」 하고 물었을 때 이어질 대화를 말차례를 지켜 네 마디로 써 보세요.","answer_guide":{"answer":"예: 나: 주말에 뭐 하고 싶어? / 짝: 나는 자전거를 타고 싶어. 너는? / 나: 나는 도서관에 가고 싶어. / 짝: 다음 주말에는 둘 다 해 보자!","scoring_points":["한 사람씩 번갈아 네 마디를 썼는가","묻는 말에 알맞게 대답했는가","되묻거나 이어 말해 대화가 이어졌는가"]},"explanation":["번갈아 말하기.","알맞은 대답.","대화 잇기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#25','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C8',4,'essay','teacher','「제 ○○ ○○○를 소개합니다.」로 시작해 주변 사람을 소개하는 글을 세 문장으로 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u1-C8","difficulty":4,"kind":"essay","stem":"「제 ○○ ○○○를 소개합니다.」로 시작해 주변 사람을 소개하는 글을 세 문장으로 써 보세요.","answer_guide":{"answer":"예: 제 짝 이서윤을 소개합니다. / 서윤이는 그림을 잘 그립니다. / 서윤이는 제가 아플 때 보건실에 함께 가 주었습니다.","scoring_points":["소개할 사람을 밝히며 시작했는가","나(그 사람)를 알려 주는 내용을 담았는가","한 문장에 한 가지씩 문장으로 쓰고 마침표를 찍었는가"]},"explanation":["첫 문장.","알려 주는 내용.","한 문장에 한 가지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#1','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C1',1,'mc','auto','모둠 친구가 의견을 말할 때 바른 듣기 태도는 어느 것인가요?',ARRAY['K2-1-u1-X02','K2-1-u1-X01']::text[],false,'{"seq":1,"concept":"K2-1-u1-C1","difficulty":1,"kind":"mc","stem":"모둠 친구가 의견을 말할 때 바른 듣기 태도는 어느 것인가요?","options":[{"t":"친구 말이 끝날 때까지 바라보며 들어요","correct":true},{"t":"「아니야!」 하고 바로 끼어들어요","mis":"K2-1-u1-X02"},{"t":"책상 위 물건을 만지작거려요","mis":"K2-1-u1-X01"}],"explanation":["말하는 사람을 바라보며 끝까지 들어요.","끼어들거나 다른 일을 하면 잘 들을 수 없어요.","잘 들어 주면 말하는 사람도 기분이 좋아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#2','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C2',1,'mc','auto','나를 소개하는 글에 넣으면 좋은 내용은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":2,"concept":"K2-1-u1-C2","difficulty":1,"kind":"mc","stem":"나를 소개하는 글에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"내가 아끼는 물건","correct":true},{"t":"우리 동네 날씨","mis":"K2-1-u1-X06"},{"t":"텔레비전 광고","mis":"K2-1-u1-X06"}],"explanation":["내가 아끼는 물건은 나를 알려 주는 내용이에요.","다른 둘은 나와 관계가 없어요.","소개하는 글에는 나를 알려 주는 내용을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#3','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C3',1,'mc','auto','말차례를 바르게 설명한 것은 어느 것인가요?',ARRAY['K2-1-u1-X03','K2-1-u1-X05']::text[],false,'{"seq":3,"concept":"K2-1-u1-C3","difficulty":1,"kind":"mc","stem":"말차례를 바르게 설명한 것은 어느 것인가요?","options":[{"t":"내 차례를 기다렸다가 한 사람씩 말해요","correct":true},{"t":"생각나는 사람이 먼저 크게 말해요","mis":"K2-1-u1-X03"},{"t":"한 사람이 오래오래 말해요","mis":"K2-1-u1-X05"}],"explanation":["말차례는 한 사람씩 차례대로 말하는 거예요.","먼저·크게 말하거나 혼자 계속 말하는 것은 말차례가 아니에요.","모두가 돌아가며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#4','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C4',1,'mc','auto','말차례를 잘 지킨 행동은 어느 것인가요?',ARRAY['K2-1-u1-X03','K2-1-u1-X02']::text[],false,'{"seq":4,"concept":"K2-1-u1-C4","difficulty":1,"kind":"mc","stem":"말차례를 잘 지킨 행동은 어느 것인가요?","options":[{"t":"손을 들고 내 차례를 기다리기","correct":true},{"t":"친구와 동시에 큰 소리로 말하기","mis":"K2-1-u1-X03"},{"t":"친구 말 중간에 「아니야!」 하기","mis":"K2-1-u1-X02"}],"explanation":["손을 들고 기다리는 것이 말차례를 지킨 거예요.","말하고 싶으면 손을 들고 기다려요.","친구 말이 끝나면 내 차례에 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#5','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 크레파스를 함께 쓰자고 한 친구는 누구인가요?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":5,"concept":"K2-1-u1-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 크레파스를 함께 쓰자고 한 친구는 누구인가요?","options":[{"t":"서아","correct":true},{"t":"하린","mis":"K2-1-u1-X11"},{"t":"민호","mis":"K2-1-u1-X11"}],"explanation":["글에 「짝 서아가 자기 크레파스를 함께 쓰자고 했어요」라고 나와 있어요.","다른 보기는 글에 나오지 않거나 다른 사람이 한 일이에요.","누가 무엇을 했는지 글에서 짚어요."],"asset":{"type":"passage","lines":["미술 시간에 하린이의 크레파스가 부러졌어요.","짝 서아가 자기 크레파스를 함께 쓰자고 했어요.","둘은 나란히 앉아 그림을 완성했어요."],"title":"부러진 크레파스"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#6','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C7',1,'mc','auto','「저는 김나래입니다.」는 어떤 소개 항목인가요?',ARRAY['K2-1-u1-X10']::text[],false,'{"seq":6,"concept":"K2-1-u1-C7","difficulty":1,"kind":"mc","stem":"「저는 김나래입니다.」는 어떤 소개 항목인가요?","options":[{"t":"이름","correct":true},{"t":"꿈","mis":"K2-1-u1-X10"},{"t":"좋아하는 것","mis":"K2-1-u1-X10"}],"explanation":["「저는 김나래입니다.」는 이름을 소개하는 문장이에요.","항목 이름이 문장에 들어 있어요.","이름·좋아하는 것·잘하는 것·꿈을 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#7','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C8',1,'mc','auto','나를 소개하는 글의 첫 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06','K2-1-u1-X07']::text[],false,'{"seq":7,"concept":"K2-1-u1-C8","difficulty":1,"kind":"mc","stem":"나를 소개하는 글의 첫 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"저는 강소율입니다.","correct":true},{"t":"버스가 늦게 왔습니다.","mis":"K2-1-u1-X06"},{"t":"제가 잘하는 것은 그림 그리기입니다.","mis":"K2-1-u1-X07"}],"explanation":["소개하는 글은 「저는 ○○○입니다.」로 시작해요.","그래야 누구의 글인지 바로 알 수 있어요.","나머지 내용은 이름 다음에 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#8','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C9',1,'mc','auto','주변 사람 소개에 넣으면 좋은 내용은 어느 것인가요?',ARRAY['K2-1-u1-X14']::text[],false,'{"seq":8,"concept":"K2-1-u1-C9","difficulty":1,"kind":"mc","stem":"주변 사람 소개에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"그 사람이 잘하는 것","correct":true},{"t":"그 사람이 사는 아파트 동 호수","mis":"K2-1-u1-X14"},{"t":"그 사람이 혼난 일","mis":"K2-1-u1-X14"}],"explanation":["그 사람이 잘하는 것은 그 사람을 따뜻하게 알려 줘요.","개인 정보나 흉은 넣지 않아요.","존중하는 마음으로 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#9','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C1',2,'ox','auto','발표를 들으며 그림을 그려도 귀만 열려 있으면 잘 듣는 거예요.',ARRAY['K2-1-u1-X01']::text[],false,'{"seq":9,"concept":"K2-1-u1-C1","difficulty":2,"kind":"ox","stem":"발표를 들으며 그림을 그려도 귀만 열려 있으면 잘 듣는 거예요.","answer":"X","reason_options":[{"t":"다른 일을 하면 말을 놓치고 친구도 속상하니까","correct":true},{"t":"귀로 소리만 들리면 되니까","mis":"K2-1-u1-X01"}],"mis":"K2-1-u1-X01","explanation":["다른 일을 하면서는 잘 들을 수 없어요.","발표하는 친구를 바라보며 들어요.","말하는 사람을 바라보며 끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#10','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C4',2,'mc','auto','짝이 「쉬는 시간에 뭐 하고 놀까?」 하고 물었어요. 말차례를 지켜 알맞게 대답한 것은 어느 것인가요?',ARRAY['K2-1-u1-X04']::text[],false,'{"seq":10,"concept":"K2-1-u1-C4","difficulty":2,"kind":"mc","stem":"짝이 「쉬는 시간에 뭐 하고 놀까?」 하고 물었어요. 말차례를 지켜 알맞게 대답한 것은 어느 것인가요?","options":[{"t":"「공기놀이 어때? 너는 하고 싶은 놀이 있어?」","correct":true},{"t":"「어제 만화 진짜 재밌었어.」","mis":"K2-1-u1-X04"},{"t":"「나 숙제 다 했다!」","mis":"K2-1-u1-X04"}],"explanation":["묻는 말에 맞게 대답했어요.","그리고 짝에게 되물어 차례를 건넸어요.","관계없는 말을 하면 대화가 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#11','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C6',2,'mc','auto','이야기를 읽고 답해 보세요. 머리핀을 찾지 못한 예린이의 마음은?',ARRAY['K2-1-u1-X12']::text[],false,'{"seq":11,"concept":"K2-1-u1-C6","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 머리핀을 찾지 못한 예린이의 마음은?","options":[{"t":"속상하고 아쉬운 마음","correct":true},{"t":"뿌듯한 마음","mis":"K2-1-u1-X12"},{"t":"설레는 마음","mis":"K2-1-u1-X12"}],"explanation":["예린이는 고개를 푹 숙였어요.","아끼던 것을 잃어버리면 속상해요.","일어난 일과 인물의 말·모습에서 마음을 짐작해요."],"asset":{"type":"passage","lines":["예린이가 아끼던 머리핀을 잃어버렸어요.","하루 종일 교실 구석구석을 찾았지만 없었어요.","예린이는 고개를 푹 숙였어요."],"title":"잃어버린 머리핀"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#12','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C7',2,'mc','auto','「저는 고양이를 좋아합니다.」에 까닭을 더해 이어 쓸 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":12,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"「저는 고양이를 좋아합니다.」에 까닭을 더해 이어 쓸 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"부드러운 털을 쓰다듬으면 기분이 좋기 때문입니다.","correct":true},{"t":"마트는 크기 때문입니다.","mis":"K2-1-u1-X06"},{"t":"동생은 우유를 싫어합니다.","mis":"K2-1-u1-X06"}],"explanation":["「~기 때문입니다」로 까닭을 더했어요.","다른 문장은 앞 문장의 까닭이 아니에요.","까닭은 「왜?」에 대한 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#13','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C8',2,'mc','auto','문장의 끝을 바르게 맺어 쓴 것은 어느 것인가요?',ARRAY['K2-1-u1-X08']::text[],false,'{"seq":13,"concept":"K2-1-u1-C8","difficulty":2,"kind":"mc","stem":"문장의 끝을 바르게 맺어 쓴 것은 어느 것인가요?","options":[{"t":"저는 오지안입니다.","correct":true},{"t":"저는 오지안입니다","mis":"K2-1-u1-X08"},{"t":"저는, 지안","mis":"K2-1-u1-X08"}],"explanation":["문장이 끝나면 끝에 마침표(.)를 찍어요.","마침표가 없거나 낱말만 늘어놓으면 문장이 끝나지 않아요.","다 쓴 뒤 문장 끝을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#14','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C10',2,'mc','auto','소개하는 글을 발표할 때 바른 모습은 어느 것인가요?',ARRAY['K2-1-u1-X15']::text[],false,'{"seq":14,"concept":"K2-1-u1-C10","difficulty":2,"kind":"mc","stem":"소개하는 글을 발표할 때 바른 모습은 어느 것인가요?","options":[{"t":"맨 뒤 친구에게도 들리게 또박또박 말해요","correct":true},{"t":"앞자리 친구에게만 들리게 속삭여요","mis":"K2-1-u1-X15"},{"t":"한 번에 몰아서 빠르게 읽어요","mis":"K2-1-u1-X15"}],"explanation":["듣는 친구들을 바라보며 말해요.","알맞은 크기와 빠르기로 또박또박 말해요.","작게, 빨리, 고개 숙여 말하면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#15','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C3',2,'ox','auto','친구 말에 끼어들면 말하던 친구가 속상할 수 있어요.',ARRAY['K2-1-u1-X03']::text[],false,'{"seq":15,"concept":"K2-1-u1-C3","difficulty":2,"kind":"ox","stem":"친구 말에 끼어들면 말하던 친구가 속상할 수 있어요.","answer":"O","reason_options":[{"t":"하고 싶은 말을 끝내지 못하니까","correct":true},{"t":"끼어들면 대화가 더 재미있어지니까","mis":"K2-1-u1-X03"}],"mis":"K2-1-u1-X03","explanation":["말이 끊긴 친구는 속상해요.","친구 말이 끝날 때까지 기다려요.","모두가 돌아가며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#16','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C9',2,'mc','auto','주변 사람을 소개할 때 따뜻한 소개말은 어느 것인가요?',ARRAY['K2-1-u1-X14']::text[],false,'{"seq":16,"concept":"K2-1-u1-C9","difficulty":2,"kind":"mc","stem":"주변 사람을 소개할 때 따뜻한 소개말은 어느 것인가요?","options":[{"t":"동생을 잘 돌봐 줍니다.","correct":true},{"t":"방을 잘 안 치웁니다.","mis":"K2-1-u1-X14"},{"t":"편식을 합니다.","mis":"K2-1-u1-X14"}],"explanation":["「는 좋은 점을 전하는 말이에요.동생을 잘 돌봐 줍니다.」","다른 둘은 흉이 될 수 있어요.","존중하는 마음으로 좋은 점을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#17','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C4',3,'error','auto','모둠 친구들이 말차례에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X04','K2-1-u1-X16']::text[],false,'{"seq":17,"concept":"K2-1-u1-C4","difficulty":3,"kind":"error","stem":"모둠 친구들이 말차례에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"로아 — 짝이 물으면 내가 하고 싶은 말만 하면 돼요","correct":true,"mis_target":"K2-1-u1-X04"},{"t":"민호 — 묻는 말에 맞게 대답해요","mis":"K2-1-u1-X16"},{"t":"서아 — 대답한 뒤 짝에게도 물어봐요","mis":"K2-1-u1-X16"}],"explanation":["묻는 말과 관계없는 말을 하면 대화가 끊겨요.","말차례는 한 사람씩 차례대로 말하는 거예요.","다른 두 친구는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#18','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C6',3,'mc','auto','이야기를 읽고 생각을 나누고 있어요. 소율이가 이어서 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X13','K2-1-u1-X04']::text[],false,'{"seq":18,"concept":"K2-1-u1-C6","difficulty":3,"kind":"mc","stem":"이야기를 읽고 생각을 나누고 있어요. 소율이가 이어서 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「좋은 생각이다. 어떤 머리핀을 줄 거야?」","correct":true},{"t":"「그런 건 쓸데없어.」","mis":"K2-1-u1-X13"},{"t":"「나 지금 졸려.」","mis":"K2-1-u1-X04"}],"explanation":["친구가 나와 다른 생각을 말했어요.","다른 생각을 인정하고 까닭을 물으면 이야기가 이어져요.","틀렸다고 하거나 관계없는 말을 하면 나누기가 끊겨요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"나는 예린이가 머리핀을 꼭 찾았으면 좋겠어."},{"who":"태민","text":"나는 예린이에게 새 머리핀을 선물해 주고 싶어."},{"who":"소율","text":"( ? )"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#19','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C8',3,'mc','auto','친구가 쓴 소개 글을 보고 답해 보세요. 다듬을 때 빼야 할 문장은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],false,'{"seq":19,"concept":"K2-1-u1-C8","difficulty":3,"kind":"mc","stem":"친구가 쓴 소개 글을 보고 답해 보세요. 다듬을 때 빼야 할 문장은 어느 것인가요?","options":[{"t":"지금 창밖에 비가 옵니다.","correct":true},{"t":"저는 오예린입니다.","mis":"K2-1-u1-X16"},{"t":"제가 잘하는 것은 피아노 치기입니다.","mis":"K2-1-u1-X16"}],"explanation":["「지금 창밖에 비가 옵니다」는 글쓴이를 알려 주는 내용이 아니에요.","이름과 꿈·좋아하는 것은 소개하는 글에 맞는 문장이에요.","다시 읽으며 관계없는 문장을 빼요."],"asset":{"type":"passage","lines":["저는 오예린입니다.","저는 노래 부르기를 좋아합니다.","지금 창밖에 비가 옵니다.","제가 잘하는 것은 피아노 치기입니다."],"title":"친구가 쓴 소개 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#20','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C9',3,'error','auto','친구들이 주변 사람을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?',ARRAY['K2-1-u1-X14','K2-1-u1-X16']::text[],false,'{"seq":20,"concept":"K2-1-u1-C9","difficulty":3,"kind":"error","stem":"친구들이 주변 사람을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"로아 — 「제 짝 하람이는 지난번에 넘어져서 엉엉 울었습니다.」","correct":true,"mis_target":"K2-1-u1-X14"},{"t":"도윤 — 「제 짝 하람이는 그림을 잘 그립니다.」","mis":"K2-1-u1-X16"},{"t":"서윤 — 「저희 언니는 동생을 잘 돌봐 줍니다.」","mis":"K2-1-u1-X16"}],"explanation":["짝이 부끄러워할 일을 말했어요.","소개는 존중하는 마음으로 좋은 점을 전해요.","다른 두 친구는 알맞게 소개했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#21','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C5',3,'mc','auto','이야기를 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":21,"concept":"K2-1-u1-C5","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"물통을 쏟음 → 함께 닦음 → 고맙다고 함","correct":true},{"t":"함께 닦음 → 물통을 쏟음 → 고맙다고 함","mis":"K2-1-u1-X11"},{"t":"고맙다고 함 → 함께 닦음 → 물통을 쏟음","mis":"K2-1-u1-X11"}],"explanation":["이야기의 앞에서부터 차례로 짚어요.","물통을 쏟음 → 함께 닦음 → 고맙다고 함 차례예요.","까닭이 먼저, 결과가 나중에 와요."],"asset":{"type":"passage","lines":["예린이가 물통을 쏟았어요.","준우가 휴지로 바닥을 함께 닦았어요.","예린이가 「고마워.」 하고 웃었어요."],"title":"쏟아진 물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#22','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C10',3,'mc','auto','친구가 「저희 할아버지께서는 텃밭에서 채소를 잘 기르십니다.」 하고 소개했어요. 소개를 듣고 할 질문으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X04','K2-1-u1-X13']::text[],false,'{"seq":22,"concept":"K2-1-u1-C10","difficulty":3,"kind":"mc","stem":"친구가 「저희 할아버지께서는 텃밭에서 채소를 잘 기르십니다.」 하고 소개했어요. 소개를 듣고 할 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"「할아버지께서는 어떤 채소를 기르시나요?」","correct":true},{"t":"「주말에 뭐 할 거야?」","mis":"K2-1-u1-X04"},{"t":"「채소는 맛없어.」","mis":"K2-1-u1-X13"}],"explanation":["소개한 내용과 관련 있는 것을 물어요.","관계없는 질문이나 깎아내리는 말은 하지 않아요.","소개가 끝난 뒤 손을 들고 정중하게 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#23','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C8',4,'mc','auto','두 친구가 쓴 소개 글이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#24','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C4',4,'essay','teacher','짝에게 「좋아하는 책이 뭐야?」 하고 물었을 때 이어질 대화를 말차례를 지켜 네 마디로 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u1-C4","difficulty":4,"kind":"essay","stem":"짝에게 「좋아하는 책이 뭐야?」 하고 물었을 때 이어질 대화를 말차례를 지켜 네 마디로 써 보세요.","answer_guide":{"answer":"예: 나: 좋아하는 책이 뭐야? / 짝: 나는 공룡 책을 좋아해. 너는? / 나: 나는 동물 이야기책을 좋아해. / 짝: 우리 서로 바꿔 읽어 볼래?","scoring_points":["한 사람씩 번갈아 네 마디를 썼는가","묻는 말에 알맞게 대답했는가","되묻거나 이어 말해 대화가 이어졌는가"]},"explanation":["번갈아 말하기.","알맞은 대답.","대화 잇기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#25','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C8',4,'essay','teacher','처음 만난 친구에게 나를 소개하는 글을 네 문장으로 써 보세요. 친구가 궁금해할 내용을 골라요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u1-C8","difficulty":4,"kind":"essay","stem":"처음 만난 친구에게 나를 소개하는 글을 네 문장으로 써 보세요. 친구가 궁금해할 내용을 골라요.","answer_guide":{"answer":"예: 저는 박지후입니다. / 제가 좋아하는 놀이는 숨바꼭질입니다. / 제가 잘하는 것은 달리기입니다. / 쉬는 시간에 같이 놀아요.","scoring_points":["이름으로 시작했는가","나(그 사람)를 알려 주는 내용을 담았는가","한 문장에 한 가지씩 문장으로 쓰고 마침표를 찍었는가"]},"explanation":["첫 문장.","알려 주는 내용.","한 문장에 한 가지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
